// js/10-main-app.js — dipindah dari <script> di index.html lama (baris 8094). Isi tidak diubah.
// ============================================================
// SHARED UTILS
// ============================================================
function pbRenderAkunCard(){
  try{
    var u=JSON.parse(localStorage.getItem('pb_auth_user')||'null');
    var e=document.getElementById('pb-akun-email'); if(e) e.textContent=(u&&u.email)||'-';
    var t=(typeof pbGetTier==='function')?pbGetTier():'free';
    var C=window.PB_TIER_CONFIG, p=document.getElementById('pb-akun-paket');
    if(p) p.textContent=(C&&C[t])?(C[t].label+' ('+C[t].limit+' produk/hari)'):'Gratis';
  }catch(x){}
}
function switchPage(id,btn){
  if(id==='panduan'){ try{ pbRenderAkunCard(); }catch(x){} }
  document.querySelectorAll('.page').forEach(e=>e.classList.remove('active'));
  document.querySelectorAll('.ntab').forEach(e=>e.classList.remove('active'));
  document.getElementById(id).classList.add('active');
  btn.classList.add('active');
  let shell=document.getElementById('app-shell');
  if(shell) shell.scrollTop=0; else window.scrollTo(0,0);
  // FITUR BARU (permintaan user, Sept 2026): catat tab/page yang sedang
  // aktif ('foto'/'video'/'riwayat'/'panduan') ke key TERPISAH dari draft
  // wizard (pb_wizard_draft_v1). SENGAJA terpisah — key ini TETAP hidup
  // walau user refresh (draft wizard tetap dihapus & isian tetap mulai
  // dari 0 seperti yang sudah disepakati), supaya begitu app kebuka lagi
  // setelah refresh, tab yang ditampilkan balik ke tab TERAKHIR yang
  // dibuka (mis. tab Video), bukan selalu balik ke tab Foto (default
  // bawaan HTML). Lihat pemulihannya di window.load paling bawah file
  // (cari string "pb_last_active_page_v1").
  try{ localStorage.setItem('pb_last_active_page_v1', id); }catch(e){}
  // FITUR BARU (permintaan user): begitu tab "Foto" dibuka, sinkronkan
  // lagi thumbnail foto Karakter Sheet di kartu Subjek Foto (f0) — lihat
  // pbF0KsThumbSync() untuk logikanya.
  if(id==='foto' && typeof pbF0KsThumbSync==='function') pbF0KsThumbSync();
}

// Dipakai menu step desktop (#f-step-nav). scrollIntoView() sudah di-override
// jadi no-op (lihat <script> paling atas) dan step yang sudah selesai
// disembunyikan total oleh doneCard(), jadi dulu klik menu ini tidak
// melakukan apa-apa. Sekarang: step yang sudah selesai dibuka lewat
// fSummaryEdit() (jalur yang sama dengan sheet \"Lompat ke step\"), step yang
// sedang aktif cukup di-scroll, step yang belum sampai dikasih tahu lewat toast.
function fJumpStep(id){
  let el=document.getElementById(id);
  if(!el)return;
  if(el.classList.contains('done')){
    let m=/^f(\d+)$/.exec(id);
    if(m && typeof fSummaryEdit==='function'){
      fSummaryEdit(parseInt(m[1],10));
      setTimeout(function(){fScrollToCard(el);},80);
      return;
    }
  }
  if(el.classList.contains('pending')){
    showToast('Selesaikan step sebelumnya dulu ya','info');
    return;
  }
  fScrollToCard(el);
}

function openApiKeyModal(){
  let m=document.getElementById('apikey-modal-overlay');
  if(m)m.style.display='flex';
  let errBox=document.getElementById('vai-key-error');
  if(errBox){errBox.classList.add('hidden');errBox.textContent='';}
  // FIX: tombol "Simpan & Mulai" di dalam modal ini di-disable sesaat
  // selagi proses simpan key berjalan (lihat vaiSaveKey). Kalau proses itu
  // kebetulan terhenti di tengah jalan (mis. tab di-refresh/pindah pas lagi
  // proses), tombolnya bisa nyangkut permanen dalam keadaan disabled untuk
  // sesi berikutnya. Supaya tombol "AI" ini SELALU bisa dipakai lagi tiap
  // dibuka, statusnya dipaksa reset ke kondisi normal di sini.
  let saveBtn=document.querySelector('#vai-key .btn');
  if(saveBtn&&saveBtn.disabled){
    saveBtn.disabled=false;
    saveBtn.innerHTML='<svg class="icon"><use href="#ic-check"></use></svg> Simpan & Mulai';
  }
}
function closeApiKeyModal(){
  let m=document.getElementById('apikey-modal-overlay');
  if(m)m.style.display='none';
}

// ============================================================
// KEYBOARD SHORTCUTS (desktop) — Esc tutup modal, Ctrl/Cmd+Enter
// generate, C salin hasil. Tidak aktif saat user sedang mengetik
// di input/textarea supaya tidak mengganggu.
// ============================================================
// ============================================================
// UNDO PILIHAN CHIP (Ctrl+Z) — kalau salah pencet chip (pose,
// lokasi, angle, dll), Ctrl+Z balikin ke pilihan sebelumnya di
// grup yang sama. Generik: dipantau lewat capture-phase listener,
// tidak perlu ubah tiap fungsi fPickX/vbPickX satu-satu.
// ============================================================
let CHIP_UNDO_STACK=[];
document.addEventListener('click',function(e){
  let chip=e.target.closest?e.target.closest('.chip,#vcam-chips .pb-fk,#vcam-hook-chips .pb-fk'):null;
  if(!chip||!chip.parentElement)return;
  // Cari chip lain yang sedang 'sel' dalam grup yang sama (sibling langsung)
  let siblings=chip.parentElement.querySelectorAll(':scope > .chip.sel,:scope > .pb-fk.sel');
  let prevSel=null;
  siblings.forEach(function(s){if(s!==chip)prevSel=s;});
  // Hanya catat undo kalau memang ada pilihan sebelumnya di grup ini,
  // dan yang diklik sekarang bukan chip yang sudah 'sel' juga (klik ulang)
  if(prevSel&&!chip.classList.contains('sel')){
    CHIP_UNDO_STACK.push(prevSel);
    if(CHIP_UNDO_STACK.length>30)CHIP_UNDO_STACK.shift();
  }
},true); // capture phase — jalan SEBELUM onclick milik chip itu sendiri

// ============================================================
// FITUR (diminta user): double-click / double-tap CEPAT pada chip atau
// kartu pilihan langsung menjalankan tombol "Konfirmasi & Lanjut →" yang
// dibuat fShowConfirm() — user tidak perlu klik chip dulu lalu klik lagi ke
// tombol konfirmasi terpisah di bawahnya; 2x klik cepat di chip yang sama
// sudah cukup untuk loncat ke step berikutnya.
//
// FIX: awalnya dipakai event 'dblclick' bawaan browser, tapi user lapor
// kerasa delay. Penyebabnya: browser/OS (terutama di HP) sengaja MENUNDA
// event 'dblclick' sekitar ~300ms setelah tap pertama, buat mastiin itu
// beneran mau di-tap 2x dan bukan tap tunggal biasa — jadi walau jari user
// sudah selesai ngetuk 2x secepat mungkin, event yang ditunggu tetap baru
// nembak belakangan. Sekarang diganti: deteksi double-click dibikin manual
// lewat event 'click' biasa (yang SELALU instan, tidak pernah ditunda) —
// catat elemen + waktu klik terakhir, kalau klik berikutnya jatuh di elemen
// YANG SAMA dalam jeda cepat (di bawah FAST_PICK_THRESHOLD_MS), langsung
// anggap itu "klik cepat ke-2" dan tekan tombol konfirmasinya saat itu juga
// — tanpa nunggu event dblclick sama sekali.
//
// CARA KERJA: didesain generik di level fShowConfirm (bukan menambal tiap
// fPick*/vbPick* satu per satu). Listener ini didaftarkan di document pada
// FASE BUBBLE (bukan capture), jadi dia otomatis jalan SETELAH onclick
// bawaan si chip (mis. fPickSubjek) selesai — begitu klik cepat ke-2
// terdeteksi, kartu (.wcard) tempat elemen itu berada dicek: kalau bar
// konfirmasi sudah ada di situ (artinya requirement step ini sudah lengkap
// setelah handler onclick bawaan barusan jalan), langsung "tekan" tombolnya.
// Kalau belum ada (mis. step butuh beberapa field dan belum semua keisi),
// tidak terjadi apa-apa — jadi tidak mungkin melompati field wajib yang
// belum diisi.
//
// CAKUPAN: otomatis berlaku di SEMUA step yang pakai fShowConfirm() — saat
// ditulis ini mencakup f0, f2, f3, f4, f5, f7, f8, f9 (Foto) dan v2, v3, v4
// (Video). TIDAK berlaku di f1 (Foto Referensi — multi-pilih) dan v1 (Mode
// Referensi Foto + sub-langkah Lokasi/Lighting Mode 3), karena step-step itu
// pakai tombol "Lanjut →" yang statis (selalu ada), bukan bar dinamis dari
// fShowConfirm() — perlu penanganan terpisah kalau suatu saat mau diperluas
// ke situ juga.
// ============================================================
let _fastPickLastEl=null,_fastPickLastTime=0;
const FAST_PICK_THRESHOLD_MS=400;
document.addEventListener('click',function(e){
  let el=e.target&&e.target.closest?e.target.closest('.chip,.subjek-card,.ftype-btn,.catcard,.vstyle-card,.produk-choice,.suara-card,#vmotion-chips .pb-fk,#v4-box .pb-fk'):null;
  if(!el)return;
  let now=Date.now();
  let isFastRepeat=(el===_fastPickLastEl)&&(now-_fastPickLastTime<FAST_PICK_THRESHOLD_MS);
  _fastPickLastEl=el;_fastPickLastTime=now;
  if(!isFastRepeat)return;
  // Klik cepat ke-2 di elemen yang sama terdeteksi — reset dulu supaya
  // klik ke-3 dst (kalau ada) tidak ikut ke-trigger tanpa klik baru.
  _fastPickLastEl=null;_fastPickLastTime=0;
  let card=el.closest('.wcard');
  if(!card||!card.id)return;
  let bar=document.getElementById(card.id+'-confirmbar');
  if(!bar)return;
  let btn=bar.querySelector('button');
  if(btn)btn.click();
});

document.addEventListener('keydown', function(e){
  let ae=document.activeElement;
  let tag=(ae&&ae.tagName)||'';
  let isTyping = tag==='INPUT'||tag==='TEXTAREA'||(ae&&ae.isContentEditable);

  if(e.key==='Escape'){
    let om=document.getElementById('outfit-random-modal');
    if(om&&om.style.display==='flex'){fCloseOutfitRandom();return;}
    let am=document.getElementById('apikey-modal-overlay');
    if(am&&am.style.display==='flex'){closeApiKeyModal();return;}
    return;
  }

  // ENTER di dalam input teks (bukan textarea) → klik tombol Konfirmasi/Lanjut
  // terdekat, supaya user bisa isi step lalu langsung tekan Enter tanpa raih mouse.
  if(e.key==='Enter'&&!e.ctrlKey&&!e.metaKey&&isTyping){
    if(tag==='INPUT'&&ae.type!=='checkbox'&&ae.type!=='radio'){
      // FIX BUG (ditemukan saat audit mendalam khusus builder video): sebelumnya
      // Enter di field MANAPUN pada step "Script/Dialog" yang formnya PUNYA
      // BEBERAPA field wajib (Mode AI: Nama Produk + Target Audience; Mode
      // Bulk: Nama Produk 1..N + Keunggulan + Target Audience) langsung
      // memicu klik tombol Generate — walau field-field lain di form yang
      // sama belum tentu selesai diisi/dicek user. Reproducible paling parah
      // di Mode Bulk: user mengoreksi salah SATU baris produk di tengah
      // (misal baris ke-3 dari 5), baris lain kebetulan sudah terisi dari
      // cache (lihat FIX BUG#15), lalu refleks pencet Enter setelah selesai
      // ngetik satu field → memicu panggilan API Gemini SUNGGUHAN sebelum
      // user sempat review semua baris. Sekarang Enter di field yang BUKAN
      // field terakhir cuma memindahkan fokus ke field berikutnya (seperti
      // tombol "next" di keyboard HP) — Generate cuma ke-trigger dari Enter
      // di field paling akhir (Target Audience), sama seperti niat awal
      // shortcut ini (submit setelah SEMUA field selesai).
      // FIX: lompat hanya ke kolom yang TERLIHAT. Target Audience ada di tab Penonton
      // (pindah tab dulu), keunggulan bisa tersembunyi di kotak "Atur detail" yang tertutup.
      let vbGo=function(el){
        if(!el)return false;
        if(el.id==='vb-bulk-target'){try{vbInfoTab('penonton');}catch(_e){}}
        if(el.offsetParent===null)return false;
        e.preventDefault();el.focus();el.select&&el.select();return true;
      };
      // FIX: Enter di kolom jumlah produk dulu jatuh ke handler generik dan mengklik Generate
      // (tombolnya cuma beberapa level di atas). Sekarang cuma mengesahkan jumlah lalu pindah ke Nama Produk 1.
      if(ae.id==='vb-bulk-count'){
        try{vbBulkSetCount();}catch(_e){}
        if(!vbGo(document.getElementById('vb-bulk-nama-0')))e.preventDefault();
        return;
      }
      if(ae.id&&ae.id.indexOf('vb-bulk-nama-')===0){
        let rowIdx=parseInt(ae.id.slice('vb-bulk-nama-'.length),10);
        if(vbGo(document.getElementById('vb-bulk-keunggulan-'+rowIdx)))return;
        if(vbGo(document.getElementById('vb-bulk-ta-'+rowIdx)))return;
        if(vbGo(document.getElementById('vb-bulk-nama-'+(rowIdx+1))))return;
        vbGo(document.getElementById('vb-bulk-target'));
        return;
      }
      if(ae.id&&ae.id.indexOf('vb-bulk-keunggulan-')===0){
        let rowIdx=parseInt(ae.id.slice('vb-bulk-keunggulan-'.length),10);
        if(vbGo(document.getElementById('vb-bulk-ta-'+rowIdx)))return;
        if(vbGo(document.getElementById('vb-bulk-nama-'+(rowIdx+1))))return;
        vbGo(document.getElementById('vb-bulk-target'));
        return;
      }
      // Target audience per produk: Enter hanya pindah ke produk berikutnya (atau ke Target Audience umum), tidak pernah memicu Generate.
      if(ae.id&&ae.id.indexOf('vb-bulk-ta-')===0){
        let rowIdx=parseInt(ae.id.slice('vb-bulk-ta-'.length),10);
        if(vbGo(document.getElementById('vb-bulk-nama-'+(rowIdx+1))))return;
        if(!vbGo(document.getElementById('vb-bulk-target')))e.preventDefault();
        return;
      }
      if(ae.id==='vb-bulk-target'||ae.id==='vb-sapaan-input'){
        let bulkBtn=document.getElementById('vb-bulk-btn');
        if(bulkBtn){e.preventDefault();bulkBtn.click();}
        return;
      }
      let el=ae.parentElement,hops=0,btn=null;
      while(el&&hops<6&&!btn){
        btn=el.querySelector('button.btn');
        el=el.parentElement;hops++;
      }
      if(btn){e.preventDefault();btn.click();}
    }
    return;
  }

  if(isTyping)return;

  // Ctrl/Cmd+Z → undo pilihan chip terakhir (bukan di dalam kotak teks,
  // supaya tidak bentrok dengan undo teks bawaan browser)
  if((e.ctrlKey||e.metaKey)&&!e.shiftKey&&(e.key==='z'||e.key==='Z')){
    let prevChip=CHIP_UNDO_STACK.pop();
    if(prevChip){
      e.preventDefault();
      prevChip.click();
      showToast('Kembali ke pilihan sebelumnya','info');
    }
    return;
  }

  // Ctrl/Cmd+Enter → klik tombol Generate Prompt Foto kalau lagi kelihatan
  if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){
    let btn=document.getElementById('f-gen-btn');
    if(btn&&btn.offsetParent!==null){e.preventDefault();btn.click();}
    return;
  }

  // C → salin hasil JSON kalau output sedang tampil
  if(e.key==='c'||e.key==='C'){
    let wrap=document.getElementById('f-output-wrap');
    if(wrap&&wrap.style.display==='block'){
      let copyBtn=document.getElementById('f-copy-btn');
      if(copyBtn){e.preventDefault();copyBtn.click();}
    }
  }
});

// FIX A14: esc() dipindah ke scope global agar tidak dibuat ulang tiap render
function esc(str){return (str||'').replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
// GANTI PROVIDER KE CLAUDE: API key Claude (Anthropic) selalu diawali
// "sk-ant-" (beda dari key Groq yang dulu diawali "gsk_" atau key Gemini yang
// diawali "AIza.../AQ...."). Nama fungsi TIDAK diubah biar tidak perlu
// ganti semua call-site (_isValidGeminiKey dipanggil di beberapa tempat
// lain di file ini).
function _isValidGeminiKey(k){
  return !!(k && k.startsWith('sk-ant-'));
}

// ============================================================
// SIMPAN TEKS "ISI SENDIRI" — berlaku di semua kotak custom input
// (Foto: cara tampil, pose, lokasi x2, cahaya, angle, mood — Video:
// usia, nada bicara, aksen). Tersimpan di localStorage per field,
// bisa dipakai lagi (1 tap langsung isi + konfirmasi) atau dihapus.
// ============================================================
const CS_KEY='pb_custom_saves';
const CS_FIELDS={
  f3:{input:'f3-custom',confirm:'fPickHoldCustom'},
  f4:{input:'f4-custom',confirm:'fPickPoseCustom'},
  f5:{input:'f5-custom',confirm:'fPickLokasiCustom'},
  f5k:{input:'f5-custom-karakter',confirm:'fPickLokasiCustomKarakter'},
  f7:{input:'f7-custom',confirm:'fPickCahayaCustom'},
  f8:{input:'f8-custom',confirm:'fPickAngleCustom'},
  f9:{input:'f9-custom',confirm:'fPickMoodCustom'},
  v3:{input:'v3-custom',confirm:'vbPickPitchCustom'},
  v4:{input:'v4-custom',confirm:'vbPickAccentCustom'},
  vm3lok:{input:'vb-mode3-lokasi-custom',confirm:'vbPickMode3LokasiCustom'},
  vm3light:{input:'vb-mode3-lighting-custom',confirm:'vbPickMode3LightingCustom'}
};
function csGetAll(){try{return JSON.parse(localStorage.getItem(CS_KEY)||'{}');}catch(e){return{};}}
function csSaveAll(all){try{localStorage.setItem(CS_KEY,JSON.stringify(all));if(typeof pbCloudQueue==='function')pbCloudQueue(CS_KEY);}catch(e){}}
function csGetList(fk){let all=csGetAll();return all[fk]||[];}
function csSave(fk){
  let cfg=CS_FIELDS[fk];if(!cfg)return;
  let inp=document.getElementById(cfg.input);
  if(!inp)return;
  let text=inp.value.trim();
  if(!text){showToast('Isi dulu teksnya sebelum disimpan','error');return;}
  let all=csGetAll();
  let list=all[fk]||[];
  if(list.includes(text)){showToast('Sudah tersimpan sebelumnya','info');return;}
  list.unshift(text);
  if(list.length>15)list=list.slice(0,15);
  all[fk]=list;
  csSaveAll(all);
  showToast('Tersimpan — bisa dipakai lagi nanti','success');
  csRenderList(fk);
}
function csDelete(fk,text){
  let all=csGetAll();
  all[fk]=(all[fk]||[]).filter(t=>t!==text);
  csSaveAll(all);
  csRenderList(fk);
}
function csUse(fk,text){
  let cfg=CS_FIELDS[fk];if(!cfg)return;
  let inp=document.getElementById(cfg.input);
  if(inp){
    inp.value=text;
    inp.dispatchEvent(new Event('input'));
    if(cfg.confirm&&typeof window[cfg.confirm]==='function')window[cfg.confirm]();
  }
}
function csRenderList(fk){
  let container=document.getElementById('cs-list-'+fk);
  if(!container)return;
  let list=csGetList(fk);
  if(list.length===0){container.style.display='none';container.innerHTML='';return;}
  container.style.display='flex';
  container.innerHTML=list.map(function(t){
    let short=t.length>26?t.substring(0,26)+'…':t;
    return '<span data-full="'+esc(t)+'" style="display:inline-flex;align-items:center;gap:4px;background:var(--surface2);border:1px solid var(--border);border-radius:var(--radius-pill);padding:3px 4px 3px 9px;font-size:var(--fs-xs);color:var(--muted);">'
      +'<span onclick="csUse(\''+fk+'\',this.parentElement.dataset.full)" style="cursor:pointer;">'+esc(short)+'</span>'
      +'<span class="tap-target" onclick="event.stopPropagation();csDelete(\''+fk+'\',this.parentElement.dataset.full)" style="cursor:pointer;color:var(--red);padding:0 3px;font-weight:600;"><svg class="icon"><use href="#ic-close"></use></svg></span>'
      +'</span>';
  }).join('');
}
function csRenderAll(){
  Object.keys(CS_FIELDS).forEach(csRenderList);
}

// FIX A9: helper char counter untuk semua input custom
function fCountInp(el,counterId){
  let max=parseInt(el.getAttribute('maxlength')||'300',10);
  let len=el.value.length;
  let counter=document.getElementById(counterId);
  if(!counter)return;
  counter.textContent=len+' / '+max;
  counter.className='inp-counter'+(len>=max?' over':len>=max*0.8?' warn':'');
  // Kalau user mulai ngetik di kolom "isi sendiri" setelah sebelumnya
  // sempat pilih chip (bar "Konfirmasi & Lanjut →" lagi tampil) — batalkan
  // pilihan chip itu dan kembalikan tombol "Konfirmasi →" kolom ini,
  // supaya tetap cuma ada 1 tombol konfirmasi yang aktif/relevan.
  let card=el.closest('.wcard');
  if(card){
    let bar=card.querySelector('[id$="-confirmbar"]');
    if(bar)bar.remove();
    fRestoreCustomBlock(card);
    if(len>0)card.querySelectorAll('.chips .chip.sel, .chips .sel').forEach(c=>c.classList.remove('sel'));
  }
  fSyncMt12ConfirmBtn(el,len);
}
// FIX (dilaporkan user): dulu chip preset yang sudah dipilih (mis. "Low
// Angle") baru kehilangan warna sorotnya begitu user MULAI MENGETIK di
// kolom "Atau isi sendiri" (lihat fCountInp di atas, len>0). Kalau user
// cuma tap/klik ke kolom itu dulu (belum ketik apa-apa) karena berubah
// pikiran mau isi sendiri, chip lama masih kelihatan seperti masih dipilih
// — padahal user sudah pindah niat. Sekarang begitu kolom "isi sendiri"
// difokus, chip yang sedang dipilih langsung dilepas warnanya, sama kayak
// pola yang sudah dipakai di Negara/Penampilan (csNegaraCustomFocus dkk).
// Dipasang lewat onfocus="fCustomFocus(this)" di tiap kolom isi sendiri
// yang punya chip preset (f3, f4, f5, f5k, f7, f8, f9).
function fCustomFocus(el){
  let card=el.closest('.wcard');
  if(card) card.querySelectorAll('.chips .chip.sel, .chips .sel').forEach(c=>c.classList.remove('sel'));
}
// FITUR BARU (permintaan user): tombol "Konfirmasi →" kolom "isi sendiri"
// baru muncul begitu user sudah mengetik sesuatu (len>0) — sebelum itu
// tetap disembunyikan (default disembunyikan lewat CSS, lihat
// [data-role="mt12-confirm"]). Dipakai bareng oleh fCountInp & vbCountInpV2
// supaya perilakunya konsisten di semua step yang punya kolom "isi sendiri".
function fSyncMt12ConfirmBtn(el,len){
  let mt12=el.closest('.mt12');
  let mtBtn=mt12?mt12.querySelector('[data-role="mt12-confirm"]'):null;
  if(mtBtn && !mtBtn.dataset.hiddenByConfirm){
    mtBtn.style.display = len>0 ? 'flex' : 'none';
  }
  let card=el.closest('.wcard');
  if(card && typeof fSyncCardEditDoneBtn==='function') fSyncCardEditDoneBtn(card.id);
}

// FIX BUG #6 (V2): sama seperti fCountInp, dipakai khusus untuk kolom
// "isi usia sendiri" di V2. Bedanya: V2 punya DUA grup chip sekaligus
// dalam satu card (#vb-gender-chips untuk Jenis Kelamin + #vb-age-chips
// untuk Usia). fCountInp generik akan menghapus class 'sel' dari SEMUA
// chip di dalam card — kalau dipakai di sini, chip Gender yang sudah
// dipilih user (Laki-laki/Perempuan) ikut kebatalkan padahal user cuma
// lagi ngetik usia sendiri. Fungsi ini membatasi penghapusan 'sel' HANYA
// ke chip di dalam #vb-age-chips, chip Gender tidak disentuh.
function vbCountInpV2(el,counterId){
  // Kolom usia custom: HANYA angka, maksimal 120 (tahun). Huruf/simbol
  // dibuang otomatis, angka di atas 120 dipaksa jadi 120.
  let _isAge=(el.id==='v2-custom');
  if(_isAge){
    let d=el.value.replace(/\D/g,'').slice(0,3).replace(/^0+(?=\d)/,'');
    if(d!==''&&parseInt(d,10)>120)d='120';
    if(el.value!==d)el.value=d;
  }
  let max=parseInt(el.getAttribute('maxlength')||'120',10);
  let len=el.value.length;
  let counter=document.getElementById(counterId);
  if(counter){
    if(_isAge){
      counter.textContent='Maks. 120 tahun';
      counter.className='inp-counter';
    }else{
      counter.textContent=len+' / '+max;
      counter.className='inp-counter'+(len>=max?' over':len>=max*0.8?' warn':'');
    }
  }
  let card=el.closest('.wcard');
  if(card){
    let bar=card.querySelector('[id$="-confirmbar"]');
    if(bar)bar.remove();
    fRestoreCustomBlock(card);
    if(len>0){
      let ageChips=card.querySelector('#vb-age-chips');
      if(ageChips)ageChips.querySelectorAll('.chip.sel').forEach(c=>c.classList.remove('sel'));
    }
  }
  fSyncMt12ConfirmBtn(el,len);
}

function showToast(msg,type){
  let t=document.getElementById('toast');
  // FIX: sebelumnya kondisinya type==='success' (jadi SELAIN 'success'
  // dianggap error/merah) — akibatnya showToast(...,'info') (dipakai di
  // csDelete & csRenderList untuk pesan netral seperti "Sudah tersimpan
  // sebelumnya"/"Kembali ke pilihan sebelumnya") ikut tampil merah dengan
  // ikon ✕ seolah ada yang gagal, padahal tidak ada masalah apapun.
  // Sekarang HANYA type==='error' yang dapat styling merah/ikon ✕ — semua
  // tipe lain (termasuk 'info') dianggap netral/baik, sama seperti 'success'.
  let isError=type==='error';
  t.style.borderColor=isError?'var(--red)':'var(--green)';
  t.style.color=isError?'var(--red)':'var(--green)';
  t.innerHTML=(isError?'<svg class="icon"><use href="#ic-close"></use></svg> ':'<svg class="icon"><use href="#ic-check"></use></svg> ')+esc(msg);
  t.style.transform='translateX(-50%) translateY(0)';
  t.style.opacity='1';
  clearTimeout(t._t);
  // FIX TOAST: error tampil 4000ms agar user mobile sempat baca pesan error API
  // success/info tetap 2500ms karena tidak perlu dibaca lama
  let dur=isError?4000:2500;
  t._t=setTimeout(()=>{t.style.transform='translateX(-50%) translateY(80px)';t.style.opacity='0';},dur);
}

function showCard(id){
  let el=document.getElementById(id);
  if(!el){console.warn('showCard: elemen tidak ditemukan —',id);return;}
  // FIX BUG "STEP YANG DI-SKIP TIDAK BISA DIBUKA LAGI": showCard() dulu cuma
  // menghapus class hidden/pending, TIDAK PERNAH menghapus 'done'. Kalau card
  // ini sebelumnya ditandai done supaya di-skip (mis. F3 waktu foto produk
  // belum diupload), CSS ".wcard.done .wbody{display:none}" bikin isi card
  // tetap tersembunyi walau showCard(id) dipanggil buat menampilkan card ini
  // sebagai step aktif — layar jadi kelihatan kosong. Semua pemanggilan
  // showCard(id) di file ini bermaksud membuka card tersebut sebagai step
  // yang sedang aktif — kontradiktif dengan status 'done' — jadi aman & benar
  // untuk selalu melepas 'done' di sini juga.
  el.classList.remove('done');
  // Remove both hidden and pending states
  el.classList.remove('hidden','pending');
  // FIX KEDIPAN: card f1-f8 mulai dengan class "pending" (bukan "hidden"),
  // jadi animasi fadeUp yang dulu digantung di selector ":not(.hidden)"
  // TIDAK pernah restart saat pending dilepas (selector-nya sudah cocok
  // sejak awal render, cuma ketutup display:none!important dari .pending).
  // Solusinya: paksa restart animasi tiap kali card ini ditampilkan, lewat
  // toggle class + force reflow, apa pun state sebelumnya (hidden/pending).
  el.classList.remove('anim-in');
  void el.offsetWidth; // paksa reflow supaya animasi bisa direstart
  el.classList.add('anim-in');
  // Mark all subsequent foto cards as pending (dimmed)
  let allFotoCards=['f1','f2','f3','f4','f5','f7','f8'];
  let idx=allFotoCards.indexOf(id);
  if(idx>=0){
    for(let i=idx+1;i<allFotoCards.length;i++){
      let next=document.getElementById(allFotoCards[i]);
      if(next&&!next.classList.contains('done')){
        next.classList.remove('hidden');
        next.classList.add('pending');
      }
    }
  }
  setTimeout(()=>{
    el.scrollIntoView({behavior:'smooth',block:'nearest'});
  },150);
}

// ── PAUSE STEP AKTIF SAAT EDIT STEP LAIN ─────────────────────────────
// Permintaan user: kalau lagi di step yang belum selesai (mis. step 6,
// masih kebuka di layar) terus user buka step lain buat diubah (mis.
// step 3, lewat tap whead card 'done' atau lewat "Lompat ke step"),
// step 6 harus ketutup dulu selama step 3 diedit — begitu edit step 3
// beres, step 6 muncul lagi persis seperti sebelumnya. Dipakai LIFO
// (stack) per tab (foto/video) supaya edit bertingkat (buka step lain
// lagi saat masih edit step sebelumnya) tetap balik ke urutan yang benar.
let STEP_PAUSE_STACK={foto:[],video:[]};
function fPageIdForStepId(stepId){
  return String(stepId).charAt(0)==='v' ? 'video' : 'foto';
}
// Cari card yang lagi "aktif kebuka" (bukan done/hidden/pending/display:none)
// di tab yang sama, selain card target yang mau dibuka buat diedit.
function fFindActiveOpenCard(pageId,excludeId){
  let page=document.getElementById(pageId);
  if(!page)return null;
  let cards=page.querySelectorAll('.wcard');
  for(let i=0;i<cards.length;i++){
    let c=cards[i];
    if(c.id===excludeId)continue;
    if(c.classList.contains('done'))continue;
    if(c.classList.contains('hidden'))continue;
    if(c.classList.contains('pending'))continue;
    if(c.style.display==='none')continue;
    return c;
  }
  return null;
}
function fPauseActiveStepForEdit(targetId){
  let pageId=fPageIdForStepId(targetId);
  let active=fFindActiveOpenCard(pageId,targetId);
  if(active){
    active.classList.add('hidden');
    STEP_PAUSE_STACK[pageId].push(active.id);
  }
}
function fResumePausedStep(pageId){
  let stack=STEP_PAUSE_STACK[pageId];
  if(!stack||!stack.length)return;
  let pausedId=stack.pop();
  let el=document.getElementById(pausedId);
  if(el){
    el.classList.remove('hidden');
    el.classList.remove('anim-in');
    void el.offsetWidth; // paksa reflow supaya animasi bisa direstart
    el.classList.add('anim-in');
  }
}

function doneCard(id,ansId,text){
  // FIX RINGKASAN HILANG: kalau ada tombol "Selesai Edit — Kembali ke
  // Generate" nyangkut dari fSummaryEdit() (dipasang di step yang lagi
  // diedit), buang begitu step-nya beres lewat alur normal (chip/pick
  // biasa), bukan lewat tombol itu sendiri — biar nggak numpuk/nyisa.
  let _sedbAny=document.getElementById('summary-edit-done-btn');
  if(_sedbAny) _sedbAny.remove();

  let c=document.getElementById(id);
  // FIX BUG "STEP TERTUMPUK" (Video): catat apakah step ini barusan dibuka
  // ulang untuk DIEDIT (ditandai _doOpenEdit lewat data-reopened) — bukan
  // step yang diselesaikan dalam alur maju biasa. Dikembalikan sebagai return
  // value supaya pemanggil (vbConfirmRef, vbCheckV2Done, vbPick*Confirmed)
  // tahu kapan TIDAK boleh membuka step berikutnya lagi — lihat
  // vbAdvanceStep(). Flag langsung dibersihkan supaya tidak nyangkut.
  let _wasReopened=!!(c&&c.dataset&&c.dataset.reopened==='1');
  if(c&&c.dataset)delete c.dataset.reopened;
  if(c){
    c.classList.add('done');
    c.classList.remove('pending','hidden');
    // Store original step number
    let wnum=c.querySelector('.wnum');
    if(wnum&&!wnum._origText)wnum._origText=wnum.textContent;
    // Wire click-to-edit on whead (once only)
    let whead=c.querySelector('.whead');
    if(whead&&!whead._editWired){
      whead._editWired=true;
      function _doOpenEdit(){
        // Tutup dulu step aktif lain (yang masih kebuka/belum selesai)
        // di tab yang sama, sebelum step ini dibuka buat diedit.
        fPauseActiveStepForEdit(id);
        c.classList.remove('done');
        c.classList.remove('hidden','pending');
        // Tandai: card ini dibuka ulang untuk diedit (dibaca doneCard()).
        c.dataset.reopened='1';
        // Video: samakan header progress ("Step X dari 6" + nama step)
        // dengan step yang sedang diedit, bukan step terdepan yang tadi
        // ditinggalkan.
        if(typeof VB_STEP_META!=='undefined'&&VB_STEP_META[id]&&typeof vbUpdateProgress==='function'){
          vbUpdateProgress(VB_STEP_META[id][0],VB_STEP_META[id][1]);
        }
        // Buang sisa tombol konfirmasi kalau ada dari sesi sebelumnya
        let _oldCb=document.getElementById(id+'-confirmbar');
        if(_oldCb)_oldCb.remove();
        // Kembalikan kolom "isi sendiri" (beserta tombol "Konfirmasi →"
        // miliknya) kalau sempat disembunyikan supaya cuma 1 tombol
        // konfirmasi yang tampil
        fRestoreCustomBlock(c);
        // Restore step number
        if(wnum&&wnum._origText)wnum.textContent=wnum._origText;
        // Reset answer text
        let a2=document.getElementById(ansId);
        if(a2)a2.textContent='';
        // Isi ulang chip/kotak "tulis sendiri" dengan value yang sudah ada
        // (manual maupun hasil import) — supaya value lama TIDAK hilang
        // hanya karena card dibuka lagi untuk diubah.
        let cardNumFromId=parseInt(String(id).replace('f',''),10);
        if(!isNaN(cardNumFromId)&&typeof fRestoreStepUI==='function'){
          setTimeout(()=>fRestoreStepUI(cardNumFromId),50);
        }
        setTimeout(()=>c.scrollIntoView({behavior:'smooth',block:'nearest'}),80);
      }
      whead.addEventListener('click',function(){
        if(c.classList.contains('done')){
          // FIX BUG#4: kalau ini step Video V1-V5 dan output (vb-multi-output)
          // sudah ter-generate, edit ulang step ini akan bikin JSON yang
          // tampil di layar jadi basi (data lama) tanpa peringatan. Tanya
          // dulu, dan kalau user lanjut, bersihkan output lama supaya tidak
          // ke-copy salah.
          // FIX BUG#14 (ditemukan saat audit mendalam): regex sebelumnya cuma
          // /^v[1-4]$/ — melewatkan v5, padahal v5 (pilih mode Script: AI/
          // Manual/Bulk) justru step yang PALING langsung menghasilkan
          // vb-multi-output. Reproducible: generate 3 script/bulk sampai
          // selesai → klik header step v5 buat ganti mode (mis. dari Bulk ke
          // Manual) → kartu JSON lama TETAP nampil di layar tanpa peringatan
          // ATAU dibersihkan, jadi ada 2 sumber "hasil" yang tidak sinkron
          // sampai user generate ulang. Sekarang v5 ikut diperiksa sama
          // seperti v1-v4.
          let _isVideoStep=/^v(?:[1-5]|motion|cam|off)$/.test(id);
          let _mo=_isVideoStep?document.getElementById('vb-multi-output'):null;
          let _moHasContent=_mo&&_mo.style.display!=='none'&&_mo.innerHTML.trim()!=='';
          if(_moHasContent){
            showConfirm('Mengubah step ini akan menghapus script/JSON yang sudah dibuat, karena datanya sudah tidak sesuai lagi. Lanjutkan?',function(){
              _mo.style.display='none';
              _mo.innerHTML='';
              VB_BULK_ITEMS=[];
              VB_CARD_TAMPIL={};
              VB_CARD_LOKASI={};
              VB_PRODUCT_FOTOCOUNT={};
              VB_HOOK_OVERLAY={};
              VB_CHAR_OVR={};
              _doOpenEdit();
            },null,'Ya, Ubah & Hapus Hasil');
          }else{
            _doOpenEdit();
          }
        }
      });
    }
  }
  let a=document.getElementById(ansId);if(a)a.textContent=text;

  // SEMBUNYIKAN STEP YANG SUDAH SELESAI — sebelumnya baris ini cuma jalan
  // waktu mode import (FS.importActive), sekarang berlaku SELALU atas
  // permintaan user: begitu satu step selesai diisi, barisnya langsung
  // hilang total dari layar (bukan cuma collapse jadi baris ringkas kayak
  // sebelumnya) — cuma card yang lagi aktif yang kelihatan. Satu-satunya
  // jalan buat lihat/ubah step yang sudah lewat adalah lewat bottom sheet
  // "Lompat ke step" (tap progress bar di atas, lihat fOpenStepJump()),
  // yang manggil fSummaryEdit() untuk meng-un-hide sementara — begitu
  // selesai diedit (doneCard dipanggil lagi dari situ), otomatis
  // ke-hide lagi di sini seperti semula.
  if(c){
    c.classList.add('hidden');
  }

  // Step yang tadi ketutup sementara (karena user lagi edit step ini)
  // dimunculkan lagi sekarang, karena step ini sudah beres diedit.
  fResumePausedStep(fPageIdForStepId(id));
  return _wasReopened;
}

// ── KONFIRMASI SEBELUM LANJUT ────────────────────────────────────────
// Dulu: klik 1 chip (mis. pose "Berdiri") langsung lompat ke step
// berikutnya. Sekarang: klik chip cuma menandai pilihan (highlight),
// lalu muncul tombol "Konfirmasi & Lanjut →" — step baru pindah kalau
// tombol itu yang diklik. Dipakai generik di semua step berbasis chip
// (bukan step yang sudah punya tombol "Konfirmasi →" sendiri untuk
// input custom — itu sudah otomatis butuh klik terpisah).
function fShowConfirm(cardId, el, advanceFn){
  let card=document.getElementById(cardId);
  if(!card || typeof advanceFn!=='function'){ if(typeof advanceFn==='function')advanceFn(); return; }
  let old=document.getElementById(cardId+'-confirmbar');
  if(old)old.remove();
  let bar=document.createElement('div');
  bar.id=cardId+'-confirmbar';
  bar.style.cssText='margin-top:12px;';
  bar.innerHTML='<button class="btn sm"><svg class="icon"><use href="#ic-check"></use></svg> '+'Lanjut →'+'</button>';
  bar.querySelector('button').onclick=function(){
    let b=document.getElementById(cardId+'-confirmbar');
    if(b)b.remove();
    advanceFn();
  };
  // Taruh bar ini di PALING BAWAH card (setelah kolom "Atau isi sendiri"),
  // bukan langsung di bawah baris chip — supaya urutannya wajar: pilihan
  // chip di atas, kolom isi sendiri di tengah, dan cuma ada 1 tombol
  // konfirmasi di paling bawah sebagai penutup step ini.
  (card.querySelector('.wbody')||card).appendChild(bar);
  // SATU TOMBOL KONFIRMASI SAJA: kalau step ini punya kolom "isi sendiri"
  // dengan tombol "Konfirmasi →" sendiri, sembunyikan HANYA tombolnya
  // selama bar "Konfirmasi & Lanjut →" ini tampil — kolom input, label,
  // dan tombol "Simpan" tetap kelihatan supaya user masih bisa lihat/pakai
  // kolom isi sendiri, cuma tombol konfirmasi yang dobel yang disembunyikan.
  card.querySelectorAll('[data-role="mt12-confirm"]').forEach(function(btn){
    if(btn.style.display!=='none'){
      btn.dataset.hiddenByConfirm='1';
      btn.style.display='none';
    }
  });
  // Kalau step ini lagi dibuka dari mode "Edit" via Ringkasan, ada juga
  // tombol "Selesai Edit — Kembali ke Generate" yang selalu nempel di
  // bawah card itu. Begitu user pilih chip dan bar "Konfirmasi & Lanjut →"
  // muncul, sembunyikan dulu tombol "Selesai Edit" itu supaya tidak ada
  // 2 tombol hijau/emas yang keliatan sekaligus — cukup 1 tombol aktif
  // yang relevan dengan apa yang baru saja user lakukan. Pakai fungsi
  // terpusat (bukan hide manual di sini) supaya SEMUA titik yang bisa
  // memunculkan/menyembunyikan tombol ini selalu sepakat satu sama lain —
  // lihat komentar di fSyncCardEditDoneBtn kenapa ini penting.
  fSyncCardEditDoneBtn(cardId, true);
  setTimeout(()=>bar.scrollIntoView({behavior:'smooth',block:'nearest'}),50);
}

// SATU-SATUNYA SUMBER KEBENARAN untuk tombol "Selesai Edit — Kembali ke
// Generate": menyembunyikan/menampilkannya tergantung apakah step yang
// sedang diedit (cardId) itu punya tombol konfirmasi bawaannya sendiri
// yang sedang kelihatan. SEMUA titik di file ini yang bisa mengubah status
// tombol konfirmasi sebuah step (buka step buat edit, pilih chip, mulai
// ngetik di kolom "isi sendiri", dst.) HARUS memanggil fungsi ini di akhir
// — jangan set editBtn.style.display secara manual di tempat lain, supaya
// tidak ada lagi kondisi "2 tombol nempel bareng" yang selama ini berulang
// kali muncul lagi tiap kali ada 1 titik baru yang lupa disinkronkan.
//
// isNativeVisible boleh diisi manual (dipakai F1 foto referensi & F2 kotak
// nama produk, yang tombol bawaannya bukan pola chip+mt12-confirm standar).
// Kalau tidak diisi (undefined), fungsi ini AUTO-DETECT dengan mengecek 2
// hal yang berlaku generik untuk step manapun: (a) bar "Konfirmasi & Lanjut
// →" hasil fShowConfirm sedang tampil, atau (b) tombol "Konfirmasi →" milik
// kolom "isi sendiri" (data-role="mt12-confirm") sedang tampil. Ini yang
// dipakai step-step generik: f3 (cara pegang), f4 (pose), f5×2 (lokasi),
// f7 (cahaya), f8 (angle), f9 (mood).
function fSyncCardEditDoneBtn(cardId, isNativeVisible){
  let editBtn=document.getElementById('summary-edit-done-btn');
  if(!editBtn)return;
  let card=document.getElementById(cardId);
  if(!card||!card.contains(editBtn))return; // tombol ini lagi dipakai step lain
  if(isNativeVisible===undefined){
    // PENTING: cek offsetParent (bukan cuma btn.style.display sendiri).
    // Beberapa step (mis. f5 Lokasi) punya lebih dari satu kolom "isi
    // sendiri" yang disembunyikan lewat PANEL INDUKnya (mis.
    // #f5-produk-panel vs #f5-normal-panel, ditoggle display:none oleh
    // fToggleF1Panel) — bukan lewat style.display tombolnya sendiri.
    // btn.style.display cuma baca inline style ELEMEN ITU SENDIRI, jadi
    // tombol di dalam panel yang lagi disembunyikan tetap kebaca "visible"
    // walau sebenarnya tidak tampil sama sekali — bikin deteksi ini salah
    // dan tombol "Selesai Edit" jadi ikut disembunyikan padahal harusnya
    // muncul. offsetParent===null artinya elemen itu (atau salah satu
    // induknya) sedang display:none — cara paling andal utk cek "beneran
    // kelihatan di layar" tanpa peduli lewat elemen mana ia disembunyikan.
    let bar=document.getElementById(cardId+'-confirmbar');
    let barVisible=!!(bar && bar.getClientRects().length>0); // getClientRects (bukan offsetParent): bar Lanjut sekarang position:fixed -> offsetParent selalu null
    let mt12Visible=Array.from(card.querySelectorAll('[data-role="mt12-confirm"]')).some(function(btn){return btn.getClientRects().length>0;}); // getClientRects: tombol Lanjut "isi sendiri" kini position:fixed (dock) -> offsetParent selalu null
    isNativeVisible=barVisible||mt12Visible;
  }
  editBtn.style.display=isNativeVisible?'none':'';
}

// SATU TOMBOL KONFIRMASI SAJA (khusus F1 — Foto Referensi): step ini
// punya tombol "Selesai — Lanjut →" / "Selesai →" bawaannya sendiri
// (muncul begitu ada foto dipilih / slot produk diisi). Kalau step ini
// sedang dibuka dari mode "Edit" via Ringkasan, ada juga tombol generik
// "Selesai Edit — Kembali ke Generate" yang selalu nempel di bawah card.
// Fungsi ini menyembunyikan tombol generik itu SELAMA tombol asli step
// ini kelihatan (supaya user cuma lihat 1 tombol), dan memunculkannya
// lagi kalau tombol asli itu sempat hilang (mis. semua foto dihapus)
// supaya user tetap ada jalan keluar. Dipanggil tiap kali f1-confirm
// atau f1-produk-saja-lanjut berubah visibilitasnya.
function fSyncF1EditDoneBtn(){
  let confirm=document.getElementById('f1-confirm');
  let nativeVisible=!!(confirm&&!confirm.classList.contains('hidden'));
  fSyncCardEditDoneBtn('f1', nativeVisible);
}

// Kembalikan tombol "Konfirmasi →" kolom "isi sendiri" DAN tombol
// "Selesai Edit — Kembali ke Generate" yang sempat disembunyikan
// fShowConfirm (dipanggil saat card dibuka lagi untuk diedit, saat
// direset, atau saat user mulai mengetik di kolom "isi sendiri").
function fRestoreCustomBlock(card){
  if(!card)return;
  card.querySelectorAll('[data-role="mt12-confirm"]').forEach(function(btn){
    if(btn.dataset.hiddenByConfirm){
      // 'flex' (bukan ''): '' jatuh kembali ke CSS default display:none.
      let _in=btn.closest('.mt12')?btn.closest('.mt12').querySelector('input'):null;
      btn.style.display=(_in&&_in.value.trim().length>0)?'flex':'none';
      delete btn.dataset.hiddenByConfirm;
    }
  });
  // FIX BUG "2 TOMBOL DOBEL SAAT NGETIK DI ISI SENDIRI": sebelumnya baris
  // di bawah ini langsung "editDoneBtn.style.display=''" tanpa syarat —
  // begitu tombol "Konfirmasi →" kolom ini balik kelihatan (di atas), tombol
  // "Selesai Edit — Kembali ke Generate" IKUT balik kelihatan juga di saat
  // yang sama, padahal keduanya tidak boleh tampil bareng. Sekarang pakai
  // fSyncCardEditDoneBtn (auto-detect, tanpa parameter ke-2) supaya dia yang
  // memutuskan: karena tombol "Konfirmasi →" barusan kita tampilkan lagi di
  // atas, fungsi ini akan mendeteksinya dan MEMBIARKAN "Selesai Edit" tetap
  // tersembunyi — cuma 1 tombol yang relevan (Konfirmasi → punya kolom ini)
  // yang aktif selama user masih mengetik di kolom "isi sendiri".
  fSyncCardEditDoneBtn(card.id);
}

function showConfirm(msg,onOk,onCancel,okLabel){
  let overlay=document.createElement('div');
  overlay.className='confirm-overlay';
  let box=document.createElement('div');box.className='confirm-box';
  let h4=document.createElement('h4');h4.textContent='Yakin?';
  let p=document.createElement('p');
  // SECURITY: Pisahkan teks utama dan catatan tip — tidak pakai innerHTML
  let parts=msg.split('<br>');
  p.textContent=parts[0];
  if(parts[1]){
    let tip=document.createElement('span');
    tip.style.cssText='font-size:var(--fs-xs2);color:var(--accent);display:block;margin-top:6px;';
    tip.textContent=parts[1].replace(/<[^>]*>/g,''); // strip tag, ambil teks saja
    p.appendChild(tip);
  }
  let btns=document.createElement('div');btns.className='confirm-btns';
  let cancelBtn=document.createElement('button');cancelBtn.className='confirm-cancel';cancelBtn.textContent='Batal';
  let okBtn=document.createElement('button');okBtn.className='confirm-ok';okBtn.textContent=okLabel||'Ya, Lanjutkan';
  btns.appendChild(cancelBtn);btns.appendChild(okBtn);
  box.appendChild(h4);box.appendChild(p);box.appendChild(btns);
  overlay.appendChild(box);
  document.body.appendChild(overlay);
  okBtn.onclick=function(){overlay.remove();document.removeEventListener('keydown',_escHandler);if(onOk)onOk();};
  cancelBtn.onclick=function(){overlay.remove();document.removeEventListener('keydown',_escHandler);if(onCancel)onCancel();};
  // BUG 5 FIX: Tutup dialog dengan Escape — sebelumnya user harus klik Batal manual
  function _escHandler(e){if(e.key==='Escape'){overlay.remove();document.removeEventListener('keydown',_escHandler);if(onCancel)onCancel();}}
  document.addEventListener('keydown',_escHandler);
}

function copyText(text,btn){
  let orig=btn.textContent;
  function _onOk(){btn.innerHTML='<svg class="icon"><use href="#ic-check"></use></svg> Tersalin!';btn.style.background='rgba(76,175,125,0.2)';btn.style.color='var(--green)';setTimeout(()=>{btn.textContent=orig;btn.style.background='';btn.style.color='';},2000);}
  function _fallback(){
    // Fallback: textarea trick — bekerja di file://, HTTP, dan browser lama
    let ta=document.createElement('textarea');ta.value=text;ta.style.cssText='position:fixed;top:-9999px;left:-9999px;opacity:0;';
    document.body.appendChild(ta);ta.focus();ta.select();
    try{let ok=document.execCommand('copy');if(ok){_onOk();}else{showToast('Salin manual: '+text,'error');}}
    catch(e){showToast('Salin manual: '+text,'error');}
    document.body.removeChild(ta);
  }
  if(navigator.clipboard&&location.protocol!=='file:'){
    navigator.clipboard.writeText(text).then(_onOk).catch(_fallback);
  } else {
    // file:// protocol — Clipboard API diblokir browser, langsung pakai fallback
    _fallback();
  }
}


