// PROGRESS
// HELPER: konversi nomor card ke nomor step display yang benar
// Jalur 7-step (hasStep3): f4→4, f5→5, f7→6, f8→7 (f6/Framing dihapus)
// Jalur 6-step (!hasStep3): f4→3, f5→4, f7→5, f8→6 (f6/Framing dihapus)
// SUMBER KEBENARAN TUNGGAL urutan step tab Foto (dipakai header "Step X dari Y",
// badge nomor kartu, daftar "Lompat ke step" dan menu step desktop).
// Card f2 (Produk) & f6 (Framing) sudah dihapus dari alur, jadi nomor tidak
// boleh dihitung dari nomor card mentah (dulu f7 tampil "7" padahal step ke-6,
// total 9 padahal cuma 8). Urutan aktif:
//   Produk Saja       : Subjek, Foto Referensi, Lokasi, Cahaya, Sudut, Mood      (6)
//   Ada produk        : Subjek, Foto Referensi, Cara Tampil, Pose, Lokasi, ...   (8)
//   Tanpa produk      : Subjek, Foto Referensi, Pose, Lokasi, ...                (7)
const F_STEP_TITLES={f0:'Subjek',f1:'Foto Referensi',f3:'Cara Tampil',f4:'Pose',f5:'Lokasi',f7:'Pencahayaan',f8:'Sudut Kamera',f9:'Mood & Tone'};
// Foto referensi tipe "Lokasi" ada? Kalau ya, step Lokasi (f5) & Pencahayaan (f7) tidak dipakai —
// keduanya diambil dari foto lokasi itu sendiri.
// MODE "PRODUK + LOKASI SAJA" (permintaan user): kalau di Foto Referensi user cuma memilih Produk dan Lokasi
// (tanpa Karakter Sheet / Outfit / Aksesori), alur tetap boleh lanjut. Hasilnya diperlakukan seperti foto produk
// tanpa karakter: step Pose dilewati, prompt tidak menyebut karakter, dan Cara Tampil (mis. "di atas meja") dipakai.
function fIsNoChar(){
  try{
    if(!FS||FS.subjek==='produk'||!FS.refs)return false;
    // FIX IMPOR PRODUK+LOKASI: dulu mode impor selalu dianggap "ada karakter", jadi prompt lama yang
    // fotonya cuma Produk + Lokasi (tanpa pose) tetap dipaksa isi Pose. Sekarang prompt impor dianggap
    // tanpa karakter kalau JSON-nya memang tidak punya pose dan subject-nya kosong / "product only, no person".
    var _impProdOnly=false;
    if(FS.importActive){
      if(FS.pose||FS.poseDesc)return false;
      var _is=String(FS.importSubject||'').trim().toLowerCase();
      if(_is&&!/product only|no person/.test(_is))return false;
      // Prompt lama bekas mode "Produk Saja" (subject "product only, no person") yang fotonya cuma Produk, tanpa foto Lokasi, juga tanpa karakter.
      _impProdOnly=!!_is;
    }
    var hasP=false,hasL=false;
    for(var i=0;i<FS.refs.length;i++){
      var t=FS.refs[i].type;
      if(t==='produk')hasP=true;
      else if(t==='lokasi')hasL=true;
      else if(t==='wajah'||t==='outfit'||t==='atasan'||t==='bawahan'||t==='aksesori'||t==='outfit_random')return false;
    }
    return (hasP&&hasL)||_impProdOnly;
  }catch(e){return false;}
}
function fHasLokasiRef(){
  return !!(FS&&FS.refs&&FS.refs.some(function(r){return r.type==='lokasi';}));
}
function fActiveSteps(){
  let base;
  if(FS.subjek==='produk') base=['f0','f1','f5','f7','f8','f9'];
  else{
    let hasStep3=(FS.produkMode==='foto'||FS.produkMode==='pegang');
    base=hasStep3?['f0','f1','f3','f4','f5','f7','f8','f9']:['f0','f1','f4','f5','f7','f8','f9'];
  }
  if(fIsNoChar()||fHasPoseRef()) base=base.filter(function(id){return id!=='f4';});
  return fHasLokasiRef()?base.filter(function(id){return id!=='f5'&&id!=='f7';}):base;
}
function fTotalSteps(){
  return fActiveSteps().length;
}
// cardNum = nomor card (0=f0 Subjek, 1=f1 Foto Referensi, 3=f3, 4=f4, 5=f5, 7=f7, ...).
// Card yang tidak ada di alur aktif (mis. f2 yang sudah dihapus, atau f3 saat
// tanpa produk) dipetakan ke step berikutnya yang ada, jadi tidak pernah NaN.
function fCardToStep(cardNum){
  let steps=fActiveSteps();
  let idx=steps.indexOf('f'+cardNum);
  if(idx>=0) return idx+1;
  let after=steps.filter(function(id){return parseInt(id.slice(1),10)<cardNum;}).length;
  return Math.min(after+1,steps.length);
}

// FIX #6 (diperbaiki): nomor badge (f4-num dst) dan teks "Step X dari Y" di progress
// bar dulu dihitung oleh DUA fungsi terpisah (fSyncStepNums hardcode angkanya sendiri,
// fCardToStep menghitung dengan rumus) yang bisa saling melenceng — badge sempat
// menampilkan angka berbeda dari header "Step X dari Y" pada layar yang sama.
// Sekarang badge diturunkan LANGSUNG dari fCardToStep() supaya satu-satunya sumber
// kebenaran dan tidak bisa desync lagi.
function fSyncStepNums(){
  let f1num=document.getElementById('f1-num');
  let f3num=document.getElementById('f3-num');
  if(f1num)f1num.textContent=fCardToStep(1);
  if(f3num)f3num.textContent=fCardToStep(3);
  let f4num=document.getElementById('f4-num');
  let f5num=document.getElementById('f5-num');
  let f7num=document.getElementById('f7-num');
  let f8num=document.getElementById('f8-num');
  let f9num=document.getElementById('f9-num');
  if(f4num)f4num.textContent=fCardToStep(4);
  if(f5num)f5num.textContent=fCardToStep(5);
  if(f7num)f7num.textContent=fCardToStep(7);
  if(f8num)f8num.textContent=fCardToStep(8);
  if(f9num)f9num.textContent=fCardToStep(9);
  fSyncDesktopNav();
}

// Menu step desktop (#f-step-nav) dibangun ulang dari fActiveSteps() supaya
// selalu sama dengan header, badge kartu & daftar "Lompat ke step": tanpa
// produk tidak ada "Cara Tampil", mode Produk Saja tidak ada "Cara Tampil"/"Pose",
// dan nomornya berurutan tanpa lompatan.
function fSyncDesktopNav(){
  let nav=document.getElementById('f-step-nav');
  if(!nav) return;
  let steps=fActiveSteps();
  let sig=steps.join(',');
  if(nav.dataset.sig===sig) return;
  nav.dataset.sig=sig;
  nav.innerHTML='';
  steps.forEach(function(id,i){
    let a=document.createElement('a');
    a.textContent=(i+1)+' \u00b7 '+F_STEP_TITLES[id];
    a.onclick=function(){fJumpStep(id);};
    nav.appendChild(a);
  });
}

// ── STEP JUMP — pengganti fungsi bulatan nomor hijau yang dihapus dari
// tiap card summary. Tap progress bar di atas → buka daftar step yang
// sudah diisi di tab aktif → tap salah satu → card itu dibuka mode edit
// & layar meloncat ke situ. ──────────────────────────────────────────
function fOpenStepJump(pageId){
  let page=document.getElementById(pageId)||document.querySelector('.page.active');
  if(!page)return;
  let cards=Array.prototype.filter.call(page.querySelectorAll('.wcard.done'),function(c){
    // Step "Produk" (f2) sudah tidak dipakai — fungsinya sama dengan Foto Referensi.
    // Tidak ditampilkan di daftar Lompat ke step (tab foto).
    if(pageId==='foto' && c.id==='f2') return false;
    // Pergerakan Kamera cuma ada di Raw Asset.
    // Nov 2026: step Pergerakan Kamera sudah dihapus dari wizard (kamera lewat ikon pensil di kartu skrip) — jangan tampil di sini, termasuk dari draft lama.
    if(pageId==='video' && c.id==='vcam') return false;
    // FIX: kalau user cuma pilih Karakter Sheet + Outfit (tanpa foto produk),
    // f3 \"Cara Tampil Produk\" memang tidak relevan. Flow sengaja menandainya
    // 'done' (lihat cabang \"Tidak ada foto produk\" di fKonfirmRef) supaya
    // nomor step tidak bentrok — tapi karena berstatus 'done', dulu dia ikut
    // nongol di daftar \"Lompat ke step\" dengan jawaban kosong padahal tidak
    // ada produk yang dipilih. Step ini hanya relevan kalau ada produk
    // (produkMode 'foto'/'pegang', sama seperti syarat hasStep3 di
    // fTotalSteps/fCardToStep). CATATAN: jangan filter berdasarkan class
    // 'hidden' — doneCard() menyembunyikan SEMUA step yang selesai, jadi
    // seluruh daftar akan ikut kosong.
    if(pageId==='foto' && c.id==='f3' && typeof FS!=='undefined' && FS &&
       FS.produkMode!=='foto' && FS.produkMode!=='pegang') return false;
    // Mode \"Produk Saja\": tidak ada karakter, jadi Cara Tampil (f3) dan Pose
    // (f4) sama-sama tidak ada di alurnya (lihat fKonfirmRef & fCardToStep
    // untuk subjek 'produk'). Keduanya cuma ditandai 'done' supaya validasi
    // generate tidak memblokir — jangan sampai ikut tampil sebagai baris
    // kosong di daftar \"Lompat ke step\". Di mode ini produkMode selalu
    // 'foto', jadi filter f3 di atas TIDAK menangkapnya; harus dicek terpisah.
    if(pageId==='foto' && (c.id==='f3' || c.id==='f4') && typeof FS!=='undefined' && FS &&
       FS.subjek==='produk') return false;
    if(pageId==='foto' && c.id==='f4' && typeof fIsNoChar==='function' && fIsNoChar()) return false;
    if(pageId==='foto' && c.id==='f8' && typeof _fIsPovHandNoChar==='function' && _fIsPovHandNoChar()) return false;
    if(pageId==='foto' && c.id==='f4' && typeof fHasPoseRef==='function' && fHasPoseRef()) return false;
    return true;
  });
  let list=document.getElementById('step-jump-list');
  if(!list)return;
  list.innerHTML='';
  if(cards.length===0){
    list.innerHTML='<div class="step-jump-empty">Belum ada step yang diisi.</div>';
  }else{
    cards.forEach(function(c,idx){
      let titleEl=c.querySelector('.wtitle');
      let ansEl=c.querySelector('.wanswer');
      let title=titleEl?titleEl.textContent.trim():'Step';
      let val=ansEl?ansEl.textContent.trim():'';
      let item=document.createElement('div');
      item.className='step-jump-item';
      // Video: pakai nomor step ASLI (VB_STEP_META), bukan urutan di daftar —
      // kalau ada step di tengah yang lagi dibuka untuk diedit, dia tidak
      // ikut terdaftar (bukan .done) dan nomor step sesudahnya jadi geser
      // (mis. "Nada Bicara" tampil 2 padahal step 3).
      let _num=(pageId==='video'&&typeof VB_STEP_META!=='undefined'&&VB_STEP_META[c.id])?VB_STEP_META[c.id][0]:(idx+1);
      item.innerHTML='<div class="step-jump-num">'+_num+'</div>'+
        '<div class="step-jump-info"><div class="sjtitle"></div><div class="sjval"></div></div>';
      item.querySelector('.sjtitle').textContent=title;
      item.querySelector('.sjval').textContent=val;
      item.addEventListener('click',function(){
        fCloseStepJump();
        // Tab Foto (id card 'f0'..'f9') sudah punya mekanisme edit yang
        // matang & teruji: fSummaryEdit() — itu yang dipakai tombol "Edit"
        // di Ringkasan (f-gen-area). Dia menangani hal-hal detil yang
        // whead.click() generik TIDAK tangani (mis. tombol "Selesai Edit —
        // Kembali ke Generate" biar user balik ke Ringkasan alih-alih
        // "kebawa" lanjut ke step-step berikutnya lagi, dan penyesuaian
        // khusus card Produk). Jadi diprioritaskan di sini kalau tersedia.
        // Tab Video belum punya fungsi setara, jadi fallback ke
        // whead.click() generik (jalan, cuma tanpa tombol "Selesai Edit").
        let m=/^f(\d+)$/.exec(c.id);
        if(pageId==='foto' && m && typeof fSummaryEdit==='function'){
          fSummaryEdit(parseInt(m[1],10));
        }else{
          let whead=c.querySelector('.whead');
          if(whead)whead.click();
        }
        setTimeout(function(){fScrollToCard(c);},80);
      });
      list.appendChild(item);
    });
  }
  document.getElementById('step-jump-overlay').classList.add('open');
}
function fCloseStepJump(){
  let ov=document.getElementById('step-jump-overlay');
  if(ov)ov.classList.remove('open');
}
// Scroll manual langsung ke .app-shell (container scroll asli app ini).
// SENGAJA tidak pakai el.scrollIntoView() di sini — method itu sudah
// di-override secara global jadi no-op (lihat <script> paling atas) demi
// mematikan auto-scroll otomatis. Tapi khusus aksi INI, user sendiri yang
// tap step di daftar, jadi scroll manual di sini justru yang diinginkan —
// makanya dihitung & dieksekusi manual pakai appShell.scrollTo(), bukan
// scrollIntoView(), supaya tidak ikut kena override itu.
function fScrollToCard(el){
  if(!el)return;
  let appShell=document.querySelector('.app-shell');
  if(!appShell)return;
  let rect=el.getBoundingClientRect();
  let shellRect=appShell.getBoundingClientRect();
  let offset=rect.top-shellRect.top+appShell.scrollTop-96;
  appShell.scrollTo({top:Math.max(0,offset),behavior:'smooth'});
}

function fUpdateProgress(cardNum,stepName){
  // FIX #6: Sync nomor badge DULU sebelum hitung progress,
  // sehingga fTotalSteps() & fCardToStep() sudah sesuai state terkini
  fSyncStepNums();
  let stepNum=fCardToStep(cardNum);
  let total=fTotalSteps();
  let pct=Math.round((stepNum/total)*100);
  let fill=document.getElementById('f-progress-fill');
  let label=document.getElementById('f-progress-label');
  let title=document.getElementById('f-progress-title');
  // PULSE PROGRESS: nyalakan kilau hanya kalau step-nya beneran ganti,
  // bukan tiap kali fUpdateProgress dipanggil ulang dengan angka yang sama.
  let wrap=fill&&fill.closest('.progress-wrap');
  if(wrap&&wrap.dataset.step!==String(stepNum)){
    wrap.dataset.step=String(stepNum);
    wrap.classList.remove('step-changed');
    void wrap.offsetWidth; // restart animasi kalau dipicu beruntun cepat
    wrap.classList.add('step-changed');
    setTimeout(()=>wrap.classList.remove('step-changed'),800);
  }
  if(fill)fill.style.width=pct+'%';
  if(label)label.innerHTML='Step <span>'+stepNum+'</span> dari <span>'+total+'</span>';
  if(title)title.innerHTML=stepName||'';
}

// GENERATE FOTO
function _fGenSig(){
  try{return [FS.subjek,FS.refs.map(function(r){return r.id+':'+(r.focus||'');}).join(','),FS.produkNama,FS.lokasi,FS.cahaya,FS.angle,FS.mood,FS.pose].join('|');}catch(e){return '';}
}
function fGenerate(){
  // FITUR BARU (permintaan user): lepas blur akhir tur (pbTourFinishExt())
  // begitu tombol Generate benar-benar ditekan. DULU ini langsung membuka
  // semuanya normal lagi — SEKARANG, kalau generate ini memang bagian dari
  // sesi tur (ditandai class pb-tour-final-blur masih menyala persis
  // sebelum baris ini), area Ringkasan/Karakter Sheet/Punya Prompt
  // Lama/Generate Variasi malah disembunyikan TOTAL (pb-tour-result-simple)
  // supaya user pemula cuma lihat hasil prompt-nya saja, tidak dibuat
  // bingung — lihat pbTourAfterGenActive & pbShowSaveJsonNotif() di bawah.
  // FIX IMPOR: sebutkan step mana yang masih kosong (dulu cuma "Lengkapi semua step dulu!" tanpa petunjuk).
  if(FS.importActive && !FS.povProduk){
    // FIX IMPOR + FOTO LOKASI: kalau user menambah foto Lokasi setelah impor, Lokasi & Cahaya otomatis diambil dari foto itu
    // (sama seperti alur manual), bukan dianggap "Belum terisi".
    if(typeof fHasLokasiRef==='function' && fHasLokasiRef() && (!FS.lokasi||!FS.cahaya)){
      let _lr=fSortRefsForOrder(FS.refs.filter(function(r){return r.type!=='outfit_random';})),_ln=1;
      for(let _i=0;_i<_lr.length;_i++){if(_lr[_i].type==='lokasi'){_ln=_i+1;break;}}
      if(!FS.lokasi){FS.lokasi=FS.lokasiLabel='Dari foto lokasi';FS.lokasiDesc='the exact location shown in reference photo '+_ln+' — same architecture, props, background elements, colors, and atmosphere';}
      if(!FS.cahaya){FS.cahaya=FS.cahayaLabel='Dari foto lokasi';FS.cahayaDesc='taken entirely from reference photo '+_ln+', with the same light direction, color temperature, softness, contrast, and shadow behavior';}
    }
    let _gm=[];
    let _gNoPose=(FS.subjek==='produk'||(typeof fIsNoChar==='function'&&fIsNoChar()));
    if(!_gNoPose && !FS.pose && !FS.refs.some(function(r){return r.type==='outfit_random'&&r.focus;})) _gm.push('Pose');
    if(!FS.lokasi) _gm.push('Lokasi');
    if(!FS.cahaya) _gm.push('Cahaya');
    if(!FS.angle) _gm.push('Sudut Kamera');
    if(!FS.mood) _gm.push('Mood & Tone');
    if(_gm.length){showToast('Belum terisi: '+_gm.join(', ')+' — klik Edit di Ringkasan untuk mengisinya','error');return;}
  }
  if(FS.povProduk){
    // MODE PRODUK SAJA · POV (lihat blok script pov-js): step Pose & Sudut Kamera tidak dipakai.
    if(FS.refs.some(function(r){return r.type!=='produk';})){showToast('Foto referensi bukan produk saja — buka Foto Ref lalu tekan Lanjut dulu.','error');return;}
    if(!FS.lokasi||!FS.hold||!FS.mood||!FS.cahaya){showToast('Lengkapi semua step dulu!','error');return;}
  } else if(FS.subjek==='produk' || fIsNoChar()){
    if(!FS.lokasi||!FS.cahaya||!FS.angle||!FS.mood){showToast('Lengkapi semua step dulu!','error');return;}
  } else {
    let hasOutfitRandom=FS.refs.some(r=>r.type==='outfit_random'&&r.focus);
    if((!FS.pose&&!hasOutfitRandom)||!FS.lokasi||!FS.cahaya||!FS.angle||!FS.mood){showToast('Lengkapi semua step dulu!','error');return;}
  }
  // FIX IMPORT: FS.refs memang kosong saat mode import (foto referensinya
  // berupa teks dari JSON yang diimpor, tersimpan di FS.importRefPhotos,
  // bukan file foto asli) — jangan blok generate karena itu.
  if(!FS.importActive && FS.refs.length===0){showToast('Tambahkan minimal 1 foto referensi dulu!','error');return;}

  // FIX A1: Re-validasi bahwa pose yang tersimpan masih relevan dengan konteks saat ini.
  // Jika user back dan ganti produkMode/holdKey, FS.pose bisa berisi nilai lama yang tidak sesuai.
  // Cara paling aman: cek apakah f4 masih dalam state 'done'. Jika tidak (user back tapi belum pilih ulang), blok.
  let f4card=document.getElementById('f4');
  if(!FS.povProduk&&!(typeof fIsNoChar==='function'&&fIsNoChar())&&(!f4card||!f4card.classList.contains('done'))){
    showToast('Pilih pose terlebih dahulu (Step Pose belum diisi)!','error');
    return;
  }

  // Re-sync nama produk dari DOM kalau ada kartu foto tipe 'produk' di Step 1
  // (user mungkin edit input setelah step done).
  // FIX BUG TC5 — GENERATE TIDAK PERNAH DIBLOKIR PASCA-IMPOR: sebelumnya blok
  // ini digantung ke "FS.produkMode==='foto'". Tombol chip "Produk" di Step 1
  // (fAddRef('produk')) sebenarnya SELALU bisa dipakai kapan pun — baik di
  // alur manual maupun pasca-import — tanpa syarat produkMode harus 'foto'
  // dulu. Kalau produkMode kebetulan sudah 'pegang' (nilai default pasca-
  // import kalau JSON bawa product block sendiri, lihat fImportPrompt), foto
  // produk BARU yang ditambah lewat Step 1 dengan nama kosong sama sekali
  // tidak tercek di sini — Generate lolos begitu saja. Sekarang dicek
  // langsung berdasarkan ada/tidaknya kartu foto produk itu sendiri, tidak
  // peduli produkMode-nya apa.
  let produkRefs=FS.refs.filter(r=>r.type==='produk');
  if(produkRefs.length>0){
    // FIX: Cek apakah ada foto produk tapi nama belum diisi — arahkan ke Step 1 (foto ref), bukan Step 2
    let emptyProdukRefs=produkRefs.filter(r=>!r.focus||!r.focus.trim());
    if(emptyProdukRefs.length>0){
      showToast('Nama produk di foto '+emptyProdukRefs.map(function(r){let _o=fSortRefsForOrder(FS.refs).filter(function(x){return x.type!=='outfit_random';});return 'F'+(_o.findIndex(function(x){return x.id===r.id;})+1);}).join(', ')+' belum diisi — kembali ke Foto Referensi!','error');
      let genBtn=document.getElementById('f-gen-btn');
      if(genBtn){genBtn.disabled=false;genBtn.innerHTML='<svg class="icon"><use href="#ic-sparkle"></use></svg> Generate Prompt Foto';}
      return;
    }
    let freshNames=produkRefs.map(r=>r.focus?r.focus.trim():'').filter(n=>n);
    if(freshNames.length>0){
      // Step Produk (f2) sudah tidak bisa dibuka: nama produk sekarang HANYA diubah lewat
      // Foto Ref. Kalau namanya berubah, segarkan juga instruksi ignore foto Outfit
      // supaya tidak menyebut nama produk lama.
      let _newNama=freshNames.join(', ');
      let _namaBerubah=(_newNama!==FS.produkNama);
      FS.produkNama=_newNama;
      if(_namaBerubah && typeof fRefreshOutfitConflict==='function'){ try{ fRefreshOutfitConflict(); }catch(_e){} }
    }
  }
  // Re-validasi nama produk sebelum generate (safety net)
  if(FS.produkMode!=='tidak'&&FS.produkMode!==''&&!FS.produkNama){
    // FIX: Pesan disesuaikan — jika produkMode='foto' masalahnya di Step 1, selainnya di Step 2
    // Step 2 (Produk) sudah dihapus — nama produk diisi di kartu foto produk pada Step 1.
    let errStep='Foto Referensi (isi nama di kartu foto produk)';
    showToast('Nama produk belum diisi — ulangi dari '+errStep+'!','error');return;
  }
  // FIX: state tur baru diubah di sini, SETELAH semua validasi lolos.
  let pbWasTourFinalBlur=document.body.classList.contains('pb-tour-final-blur');
  document.body.classList.remove('pb-tour-final-blur');
  let pbSummaryCardEl=document.getElementById('summary-card');
  if(pbSummaryCardEl) pbSummaryCardEl.classList.remove('pb-tour-opened');
  if(pbWasTourFinalBlur){
    document.body.classList.add('pb-tour-result-simple');
    if(typeof pbTourAfterGenActive!=='undefined') pbTourAfterGenActive=true;
  }
  // Loading state pada tombol generate — animasi brand: logo "P" (dua layer
  // gold, meniru logo app) mulai terpisah, lalu menyatu jadi utuh persis
  // sebelum loading 2 detik selesai. Dipakai supaya user mengasosiasikan
  // jeda generate dengan branding aplikasi, bukan cuma spinner generik.
  let genBtn=document.getElementById('f-gen-btn');
  let genBtnOrigHTML=genBtn?genBtn.innerHTML:'';
  if(genBtn){
    genBtn.disabled=true;
    genBtn.classList.add('btn-loading');
    genBtn.innerHTML=
      '<div class="gen-logo-wrap" id="gen-logo-wrap">'+
        '<div class="gen-logo-box">'+
          '<svg class="gen-logo-svg" viewBox="0 0 642 635" xmlns="http://www.w3.org/2000/svg">'+
            '<defs>'+
              '<linearGradient id="genPGrad" x1="0" y1="0" x2="1" y2="1">'+
                '<stop offset="0%" stop-color="#F0D9A0"/>'+
                '<stop offset="100%" stop-color="#B8965F"/>'+
              '</linearGradient>'+
            '</defs>'+
            '<path class="p-layer p-layer-back" pathLength="1" fill="url(#genPGrad)" d="M146,92 L162,109 L179,119 L194,124 L206,126 L346,127 L373,134 L395,146 L386,133 L365,114 L343,102 L318,94 L306,92 Z M349,92 L361,96 L383,109 L401,126 L407,134 L417,154 L420,168 L431,184 L439,201 L444,219 L445,231 L481,231 L479,213 L470,183 L460,163 L443,140 L426,124 L402,108 L381,99 Z M253,195 L267,188 L293,183 L335,183 L345,185 L362,193 L375,205 L382,216 L387,229 L396,208 L399,184 L398,177 L379,162 L355,152 L331,149 L312,153 L285,166 L271,176 Z M291,150 L271,154 L251,161 L237,168 L216,182 L192,207 L182,223 L174,243 L169,271 L169,553 L203,534 L203,268 L208,239 L217,216 L233,192 L261,166 L277,156 Z M481,253 L445,253 L441,277 L435,293 L419,317 L403,333 L387,344 L370,352 L345,358 L279,359 L279,394 L325,394 L364,390 L391,381 L419,365 L447,339 L465,312 L477,281 Z"/>'+
            '<path class="p-layer p-layer-front" pathLength="1" fill="url(#genPGrad)" d="M415,201 L407,228 L397,245 L386,256 L383,267 L377,277 L360,293 L339,301 L259,302 L258,210 L243,224 L236,234 L227,254 L224,271 L224,519 L233,513 L249,497 L258,485 L258,337 L345,335 L364,330 L378,323 L393,312 L402,303 L413,287 L418,276 L423,257 L423,227 Z"/>'+
          '</svg>'+
        '</div>'+
        '<span class="gen-logo-label">Membuat Prompt...</span>'+
      '</div>';
    // Paksa reflow supaya state "terpisah" (dari CSS awal .p-layer-back/-front)
    // benar-benar ke-render dulu sebelum class "merged" ditambahkan.
    void genBtn.offsetWidth;
    setTimeout(function(){
      let w=document.getElementById('gen-logo-wrap');
      if(w)w.classList.add('merged');
    }, 650);
  }
  let _genSig=_fGenSig();
  setTimeout(function(){
    try{
      if(_fGenSig()!==_genSig){showToast('Pilihan berubah saat menunggu — tekan Generate lagi.','error');return;}
      _fDoGenerate();
    }catch(err){
      console.error('fGenerate error:',err);
      showToast('Terjadi kesalahan saat membuat prompt — coba lagi.','error');
    }finally{
      if(genBtn){genBtn.disabled=false;genBtn.classList.remove('btn-loading');genBtn.innerHTML=genBtnOrigHTML||'<svg class="icon"><use href="#ic-sparkle"></use></svg> Generate Prompt Foto';}
    }
  }, 2000);
}

function _fDoGenerate(){
  let built = _fBuildPromptJSON();
  document.getElementById('f-prompt-full').textContent = JSON.stringify(built.fullJson, null, 2);

  // ── Urutan foto — tampil langsung di label (ganti popup notifikasi lama) ──
  fBuildUploadNotice(built.realRefs, built.randomRefs);
  let _fol=document.getElementById('f-out-label'); if(_fol) _fol.innerHTML=_fBuildOutLabelBoxesHTML(built.realRefs);

  let wrap = document.getElementById('f-output-wrap');
  wrap.style.display = 'block'; let _jo=document.getElementById('f-json-output');if(_jo)_jo.style.display='block';
  let _mo=document.getElementById('f-multi-output'); if(_mo){_mo.style.display='none';_mo.innerHTML='';}
  let _ph=document.getElementById('f-preview-placeholder'); if(_ph)_ph.style.display='none';
  setTimeout(() => wrap.scrollIntoView({behavior:'smooth', block:'nearest'}), 100);
  showToast('Prompt berhasil dibuat!','success');

  // Simpan ke histori
  let fullText = document.getElementById('f-prompt-full') ? document.getElementById('f-prompt-full').textContent : '';
  // historyAdd(...) auto-save prompt DIMATIKAN — Riwayat sekarang isinya
  // "halaman tersimpan" manual lewat ikon simpan (lihat pbSaveCurrentPage),
  // bukan lagi teks prompt otomatis tiap generate.
  // Riwayat OTOMATIS Foto (terpisah dari halaman tersimpan manual) — lihat pbAutoFotoRecord.
  try{ if(typeof pbAutoFotoRecord==='function')pbAutoFotoRecord(fullText); }catch(_e){}
} // end _fDoGenerate

// ── Membangun 1 objek JSON prompt. `ov` (opsional) berisi override
// untuk fitur multi-shot: {label, poseOverride, placementOverride,
// kameraNote, forceProdukSaja, introExtra} — dipanggil tanpa argumen
// untuk generate normal (hasilnya identik seperti sebelumnya). ──────
// ============================================================
// IMPORT PROMPT LAMA — bangun JSON pakai blok yang diimpor (referensi
// foto, produk, subjek) tetap apa adanya, tapi scene (lokasi/cahaya/
// angle/pose/mood/framing) tetap ambil dari FS terkini — jadi kalau
// user reopen salah satu step itu buat diubah, hasilnya ikut berubah.
// ============================================================
// ============================================================
// Fungsi bersama: hitung teks "placement" (cara produk ditampilkan/
// dipegang) berdasarkan pilihan FS.holdKey / FS.hold TERKINI. Dipakai
// oleh _fBuildPromptJSON (mode normal) DAN _fBuildImportedPromptJSON
// (mode import) — supaya kalau user reopen step "Cara Tampil Produk"
// dan ganti pilihan, perubahannya konsisten kepakai di kedua mode,
// bukan cuma di salah satu.
// ============================================================
// Menyesuaikan teks output_quality dengan cahaya/mood/mode produk-saja (dipakai jalur normal
// DAN jalur impor, supaya keduanya tidak bisa saling melenceng).
// Kalimat pembuka "shot in a candid and natural style" hanya dipakai kalau mood kosong atau
// mengandung "candid". Untuk mood lain (Dark Moody, Luxury Premium, dll) frasa itu dibuang
// supaya tidak bentrok dengan mood yang dipilih.
function _fIntroStyle(effMood){
  let m=String(effMood||'').toLowerCase().trim();
  return (!m || /candid/.test(m)) ? ', shot in a candid and natural style' : '';
}
function _fAdaptQuality(quality, effCahaya, effMood, isProdukSaja){
  let _c=String(effCahaya||'').toLowerCase(), _m=String(effMood||'').toLowerCase();
  let _phone=/phone camera|candid/.test(_m);
  let _ctrl=/studio|softbox|e-commerce|dark moody|low key|dramatic|directional/.test(_c)||/clean, bright|luxury premium|editorial fashion|dark moody|soft pastel|high-key/.test(_m);
  if(_ctrl){
    quality.lighting='Follow the selected lighting setup exactly and keep it controlled and consistent across the frame; do not add random uneven light or phone-style exposure flaws that contradict it.';
    if(!_phone) quality.camera='High-quality, sharp, well-exposed photo with accurate colors and clean detail, matching the selected lighting and mood; realistic and natural-looking, not over-processed or artificially smoothed.';
  } else if(/natural candid/.test(_m)){
    // Mood Natural Candid: output_quality dibuat natural & lembut seperti foto HP biasa.
    // Teks lighting TIDAK memaksa "lembut/teduh" supaya tetap cocok dengan cahaya apa pun
    // yang dipilih (Siang Cerah, Hujan, Jendela, dst) dan tidak bentrok dengan scene.lighting.
    let _s=isProdukSaja?'product':"subject's face";
    quality.lighting='Light looks natural and realistic for the selected lighting, as in an ordinary phone photo: the '+_s+' stays clearly and evenly lit without harsh contrast or blown-out highlights, and shadows fall gently rather than as deep dark patches. Avoid studio-controlled lighting and artificial glow. Overall light should feel calm, organic, and real.';
    quality.camera='Shot on a modern smartphone camera with a natural handheld feel. Sharp enough on the main subject with a deep depth of field, so the background stays mostly in focus (no strong bokeh). Fine, subtle phone-camera grain in darker areas, with mild automatic smoothing typical of phone processing. Colors are natural and clean, not heavily filtered or over-saturated. Realistic dynamic range, highlights not blown out. Framing is casual and slightly imperfect, like an authentic social media photo. Not DSLR, not studio, not over-polished.';
  } else if(isProdukSaja){
    quality.lighting=quality.lighting.replace('on one side of the face and slightly brighter highlights on the other','on one side of the product and slightly brighter highlights on the other');
  }
  return quality;
}
// MODE PRODUK + LOKASI · TANGAN POV (permintaan user): di mode tanpa karakter (Foto Referensi cuma Produk + Lokasi),
// opsi Cara Tampil "Dipegang tangan (POV)" = ada satu tangan memegang produk dari sudut pandang orang pertama.
function _fIsPovHandNoChar(){
  try{return !!(FS && !FS.importActive && FS.holdKey==='tangan' && typeof fIsNoChar==='function' && fIsNoChar());}catch(e){return false;}
}
function _fComputePlacement(ov){
  ov = ov || {};
  let placement = '';
  if(ov.placementOverride){
    placement = ov.placementOverride;
  } else if(ov.forceProdukSaja){
    placement = 'displayed clearly and prominently as the sole focus of the frame, no hands or person present, centered composition showing full product detail';
  } else if(typeof fIsNoChar==='function' && fIsNoChar() && FS.holdKey==='custom' && FS.hold){
    // Produk + Lokasi saja (tanpa karakter): teks Cara Tampil dari user dipakai apa adanya
    placement = FS.hold + (/tangan|hand|pegang|hold|dipakai|worn/i.test(FS.hold) ? '' : ', no hands or person present');
  } else if(_fIsPovHandNoChar()){
    placement = 'held in one hand only \u2014 a single hand visible holding the product from a first-person POV, as if the viewer is holding it themselves; no face, no second hand and no rest of the body in the frame, product sharp, fully visible and facing the camera';
  } else if(FS.holdKey === 'dipakai'){
    placement = 'dipakai langsung oleh karakter';
  } else if(FS.holdKey === 'hanger'){
    placement = 'sudah terpasang pada hanger';
  } else if(FS.holdKey === 'tangan'){
    // FIX BUG: kalau pose yang dipilih adalah selfie (satu tangan pegang HP,
    // satu tangan pegang produk), placement default "both hands" di atas jadi
    // kontradiksi dengan instruksi pose. Deteksi via poseLabel dan pakai
    // placement khusus 1 tangan untuk kasus ini.
    // FIX: teks pose selfie sudah disederhanakan jadi "close-up selfie
    // angle, phone out of frame" (permintaan user). Deteksi cek DUA kata
    // kunci sekaligus — teks baru ('phone out of frame') DAN teks lama
    // ('POV selfie') — supaya prompt LAMA yang diimpor (masih berisi teks
    // panjang lama) tetap terdeteksi benar sebagai pose selfie, tidak
    // cuma prompt baru. Kalau cuma cek satu kata kunci baru saja, prompt
    // lama impor+pegang-tangan akan balik ke placement "dua tangan" —
    // kontradiksi dgn pose-nya sendiri yang bilang "tangan lain pegang HP".
    let _poseTextChk = (ov.poseOverride || FS.poseDesc || FS.pose || '');
    let _isSelfiePose = _poseTextChk.indexOf('ponsel tidak terlihat') !== -1 || _poseTextChk.indexOf('phone out of frame') !== -1 || _poseTextChk.indexOf('POV selfie') !== -1;
    placement = _isSelfiePose
      ? 'held in one hand and directed toward the camera lens — the other hand is holding the phone for the selfie shot, product still faces the lens clearly, sharp and fully visible'
      : 'memperlihatkan produk ke kamera';
  } else if(FS.produkMode === 'dipakai'){
    placement = 'worn as part of the outfit by the character';
  } else if(FS.hold){
    placement = 'held or displayed by the character — ' + FS.hold;
  } else if(FS.produkMode === 'pegang'){
    placement = 'held or presented by the character toward the camera';
  }
  return placement;
}

function _fBuildImportedPromptJSON(ov){
  // FIX BUG MULTI-SHOT DIABAIKAN: sebelumnya fungsi ini cuma baca
  // ov.poseOverride dan ov.kameraNote, TIDAK PERNAH baca ov.lokasiOverride /
  // ov.cahayaOverride / ov.angleOverride / ov.moodOverride — padahal fitur
  // "override khusus variasi ini" di panel multi-shot (Lokasi/Cahaya/Angle/
  // Mood per shot) sudah dikirim lewat field-field itu (lihat F_SHOT_TYPES
  // di bawah). Akibatnya kalau prompt hasil IMPOR dipakai multi-shot dan user
  // setel override lokasi/cahaya/angle/mood khusus untuk salah satu variasi,
  // override itu senyap diabaikan dan semua variasi tetap pakai lokasi/
  // cahaya/angle/mood utama yang sama. Sekarang disamakan dengan jalur
  // normal (_fBuildPromptJSON) yang sudah benar baca override ini.
  let effPose = ov.poseOverride || FS.poseDesc || FS.pose;
  let effKamera = ov.kameraNote || FS.kamera;
  let effLokasi = ov.lokasiOverride || FS.lokasiDesc || FS.lokasi;
  let effCahaya = ov.cahayaOverride || FS.cahayaDesc || FS.cahaya;
  let effAngle = ov.angleOverride || FS.angleDesc || FS.angle;
  let effMood = ov.moodOverride || FS.mood;
  // FIX BUG KONTRADIKSI DETAIL PRODUK: sebelumnya isProdukSaja di jalur
  // import HANYA baca FS.importIsProdukSaja (produk-saja-nya prompt ASLI
  // yang diimpor), tidak pernah baca ov.forceProdukSaja (dipaksa true oleh
  // shot multi-shot "Detail Produk / Detail Produk tanpa karakter"). Kalau
  // prompt yang diimpor PUNYA orang (bukan produk-saja) lalu user centang
  // variasi multi-shot "Detail Produk", placement sudah benar bilang "no
  // person" (lewat placementOv di bawah), TAPI intro/subject/"Character
  // pose" di sini tetap nulis subjek manusia — jadi satu JSON hasil generate
  // isinya kontradiksi sendiri (bilang ada orang & bilang tidak ada orang
  // sekaligus). Disamakan dengan pola jalur normal (_fBuildPromptJSON, baris
  // "ov.forceProdukSaja || FS.subjek==='produk'") supaya konsisten.
  let _impNoCharOnly = !ov.forceProdukSaja && !FS.importIsProdukSaja && (typeof fIsNoChar==='function') && fIsNoChar();
  let isProdukSaja = !!ov.forceProdukSaja || !!FS.importIsProdukSaja || _impNoCharOnly;

  // FIX BUG KONTRADIKSI TANGAN: sebelumnya mode produk-saja di jalur import
  // SELALU menganggap "tidak ada tangan/orang" (intro hardcode "no person or
  // human visible", placement dipaksa "no hands or person present") — padahal
  // ada pilihan angle khusus produk-saja "Dipegang Tangan" (scene screen
  // menyebutkan "hand entering the frame") yang tetap bisa dipilih user untuk
  // prompt hasil impor. Kalau dipilih, hasil JSON jadi kontradiksi sendiri:
  // camera_angle bilang ada tangan, tapi prompt/placement bilang tidak ada
  // orang sama sekali. Disamakan dengan jalur normal (_fBuildPromptJSON,
  // variabel angleHasHand) supaya konsisten.
  let _impPovHand = isProdukSaja && !ov.placementOverride && !ov.forceProdukSaja && FS.holdKey==='custom' && /first-person POV, as if the viewer is holding it themselves/.test(String(FS.hold||''));
  let angleHasHand = (isProdukSaja && !ov.placementOverride && /\bhand\b/i.test(effAngle)) || _impPovHand;

  // FIX BUG: sebelumnya placement produk di mode import selalu pakai teks
  // beku dari JSON yang diimpor (FS.importProductBlock.placement), jadi
  // kalau user reopen step "Cara Tampil Produk" dan ganti pilihan, itu
  // TIDAK PERNAH kepakai di hasil akhir. Sekarang: placement dihitung ulang
  // dari FS.hold/FS.holdKey terkini via _fComputePlacement (fungsi yang sama
  // dipakai mode normal), sementara name & instruction asli dari produk yang
  // diimpor tetap dipertahankan apa adanya.
  // FIX BUG PRODUK-SAJA: generate satu-shot biasa manggil _fBuildPromptJSON()
  // TANPA argumen (ov={}), jadi ov.forceProdukSaja tidak pernah ke-set dari
  // pemanggilnya. Kalau tidak dipaksa di sini, _fComputePlacement() gak akan
  // tahu ini prompt produk-saja dan malah jatuh ke pengecekan FS.holdKey/
  // FS.hold biasa (yang bisa saja masih berisi nilai basi). Paksa
  // forceProdukSaja:true di sini kalau memang produk-saja, tanpa menimpa ov
  // asli (supaya alur multi-shot yang sudah eksplisit set placementOverride
  // sendiri tetap jalan seperti biasa — placementOverride selalu dicek lebih
  // dulu di _fComputePlacement).
  // FIX BUG KONTRADIKSI TANGAN (lanjutan): kalau angleHasHand true, JANGAN
  // paksa forceProdukSaja ke _fComputePlacement — kalau dipaksa, cabang
  // "no hands or person present" di _fComputePlacement selalu menang duluan
  // dan hasilnya tidak akan pernah bisa jadi teks "ada tangan" di bawah.
  let placementOv = (isProdukSaja && !angleHasHand && !_impNoCharOnly) ? Object.assign({}, ov, {forceProdukSaja:true}) : ov;
  // FIX BUG NAMA PRODUK TIDAK KE-UPDATE: sebelumnya "name" di sini selalu
  // pakai FS.importProductBlock.name (beku dari JSON awal), padahal user BISA
  // mengedit nama produk lewat tombol "ubah" di Ringkasan (lihat
  // fKonfirmProdukManual, yang nulis ke FS.produkNama — dipakai juga di
  // aturan konflik/placement lain). Kalau user ganti nama produk setelah
  // impor, nama lama tetap yang muncul di JSON hasil generate. Sekarang
  // pakai FS.produkNama (live) dengan fallback ke nama beku kalau belum
  // pernah diedit sama sekali.
  let effPlacementImp = _fComputePlacement(placementOv);
  // v11.58: placement custom/tidak dikenal dari JSON impor dipakai apa adanya selama belum diedit.
  // Tanpa ini _fComputePlacement() menambah prefix "held or displayed by the character — " lagi.
  if(!isProdukSaja && !ov.placementOverride && FS.holdKey==='custom' && FS.hold && FS.importProductBlock && FS.hold===FS.importProductBlock.placement){
    effPlacementImp = FS.hold;
  }
  // FIX BUG KONTRADIKSI TANGAN (lanjutan): kalau angle jelas-jelas "Dipegang
  // Tangan" tapi placement masih kosong (holdKey/hold memang tidak diisi
  // untuk mode produk-saja), isi teks default yang konsisten dengan angle-nya
  // — sama seperti fallback di _fBuildPromptJSON (angleHasHand).
  if(!effPlacementImp && isProdukSaja && !angleHasHand){
    effPlacementImp = 'displayed clearly and prominently as the sole focus of the frame, no hands or person present, centered composition showing full product detail';
  }
  if(angleHasHand){
    // v11.58: produk-saja + angle "Dipegang Tangan" SELALU pakai teks tangan, bukan sisa FS.hold impor
    // (dulu jadi "held or displayed by the character — held by a hand…" yang kontradiktif).
    effPlacementImp = _impPovHand ? FS.hold : 'held by a hand entering the frame — only the hand is visible, product sharp, fully visible and prominently framed toward camera';
  }
  // FIX BUG TERSEMBUNYI (audit lanjutan skenario import — belum pernah
  // dites di Test Case manapun sebelumnya): effProductBlock di bawah tadinya
  // gate pada `FS.importProductBlock` truthy/falsy — snapshot BEKU yang cuma
  // diisi SEKALI saat fImportPrompt() jalan (line ~5992: `FS.importProductBlock
  // = parsed.product || null`) dan cuma di-NULL-kan oleh _fSyncImportProdukState()
  // saat SEMUA foto produk dihapus (line ~3541). Masalahnya: _fSyncImportProdukState()
  // TIDAK PERNAH mengisi FS.importProductBlock lagi di cabang "ada foto produk"
  // (line ~3559-3567) — cabang itu cuma set FS.produkMode='foto' & FS.produkNama,
  // tanpa pernah menyentuh FS.importProductBlock. Akibatnya: begitu foto produk
  // pernah dihapus SATU KALI (→ FS.importProductBlock jadi null permanen), lalu
  // user tambah foto produk BARU dari kosong — Ringkasan sudah benar tampil
  // "Dari foto produk · <nama>" (baca dari FS.produkMode/FS.produkNama, bukan
  // FS.importProductBlock), TAPI JSON hasil generate SAMA SEKALI TIDAK PERNAH
  // dapat key "product" atau kalimat "Hero product: ..." lagi selama-lamanya di
  // sesi itu — karena effProductBlock permanen null. User tidak akan tahu ini
  // terjadi karena Ringkasan terlihat benar (sama persis pola bug produk/outfit
  // yang sudah diperbaiki sebelumnya, cuma arahnya kebalik: dulu "nyangkut usai
  // dihapus", sekarang "hilang permanen usai ditambah lagi").
  // Fix: pakai kondisi LIVE yang sama seperti jalur normal (_fBuildPromptJSON,
  // variabel `hasProdukRef` + `FS.produkMode!=='tidak'`) — bukan snapshot beku.
  // FS.importProductBlock tetap dipakai sebagai fallback nama/instruksi ASLI
  // dari JSON yang diimpor (supaya instruksi custom dari prompt lama tidak
  // hilang selama belum pernah di-null-kan), dengan instruksi default yang
  // sama seperti jalur normal kalau memang sudah tidak ada snapshot lagi.
  let hasProdukRefImp = FS.refs ? FS.refs.some(function(r){return r.type==='produk';}) : false;
  let _impBlockNoPhoto = !!(FS.importProdukNoPhoto && FS.importProductBlock && FS.importProductBlock.name);
  let effProductBlock = (FS.produkMode !== 'tidak' && (hasProdukRefImp || _impBlockNoPhoto)) ? {
    name: FS.produkNama || (FS.importProductBlock && FS.importProductBlock.name) || '[product from reference photo]',
    placement: effPlacementImp,
    instruction: (FS.importProductBlock && FS.importProductBlock.instruction) || 'This product MUST be clearly visible, sharp, and prominently displayed. Preserve its exact shape, color, size, logo, and all visual details. Do NOT alter, resize, or obscure the product at any point.'
  } : null;

  let introProdukSajaTextImp = angleHasHand
    ? 'A photorealistic product image, clean and detailed, product held by a hand entering the frame — only the hand is visible, no face or rest of the body. '
    : 'A photorealistic product-only image, clean and detailed, no person or human visible. ';

  let _impRandomDescs = (!isProdukSaja && FS.refs) ? FS.refs.filter(function(r){return r.type==='outfit_random';}).map(function(r){return r.focus;}).filter(Boolean) : [];
  let outfitRandomIntroImp = _impRandomDescs.length ? 'Outfit (AI-generated, no reference photo): ' + _impRandomDescs.join(' | ') + '. ' : '';
  let intro = (isProdukSaja
      ? introProdukSajaTextImp
      : (effProductBlock ? 'A photorealistic product image' : 'A photorealistic lifestyle fashion image') + _fIntroStyle(effMood) + '. Subject: ' + (FS.importSubject || 'a person') + '. ')
    + outfitRandomIntroImp
    + (effProductBlock ? 'Hero product: ' + effProductBlock.name + (effProductBlock.placement ? ', ' + effProductBlock.placement + '. ' : '. ') + (effProductBlock.instruction || '') + ' ' : '')
    + 'Scene: ' + effLokasi + '. '
    + 'Lighting: ' + effCahaya + '. '
    + (isProdukSaja ? '' : (effPose ? 'Character pose: ' + effPose + '. ' : ''))
    + (effKamera ? 'Camera framing: ' + effKamera + '. ' : '')
    + 'Camera angle: ' + effAngle + '. '
    + 'Mood & tone: ' + effMood + '.';

  // v11.58: output_quality asli dari JSON hanya dipakai kalau cahaya/mood/mode belum berubah sejak impor.
  // Kalau JSON tidak membawa output_quality, atau user mengedit cahaya/mood, disesuaikan seperti jalur normal.
  let effQualityImp;
  if(FS.importOutputQuality && (!FS.importSceneSig || FS.importSceneSig === (String(effCahaya||'')+'||'+String(effMood||'')+'||'+(isProdukSaja?'1':'0')))){
    // (tanpa tanda tangan = halaman tersimpan dari versi lama → pakai output_quality aslinya, seperti dulu)
    effQualityImp = FS.importOutputQuality;
  } else {
    effQualityImp = _fAdaptQuality({
      camera: 'Shot using a smartphone camera (not DSLR), with natural handheld feel. The image includes subtle digital noise and grain typical of a phone camera, especially in shadows and low-light areas. Slight imperfections such as minor motion blur, soft focus inconsistencies, and natural exposure shifts are present. The dynamic range is realistic (not overly HDR), with slightly clipped highlights and soft shadow details. The framing is slightly imperfect, not perfectly centered, with a subtle wide lens feel and natural perspective distortion. Overall look resembles an authentic phone photo, not a polished or studio-quality image.',
      lighting: 'Lighting is natural and imperfect, coming from a window or ambient indoor source rather than studio lights. The light falls unevenly across the subject, creating soft shadows on one side of the face and slightly brighter highlights on the other. There may be mild overexposure in small highlight areas and gentle shadow gradients across the scene. The lighting is not perfectly balanced, with slight warmth and natural color variation. Some areas of the scene may be dimmer or less illuminated, creating a cozy, lived-in atmosphere. Avoid flat lighting or perfectly even illumination. Overall lighting should feel organic, spontaneous, and human, not staged or studio-controlled.'
    }, effCahaya, effMood, isProdukSaja);
  }

  let fullJson = {
    prompt: intro,
    subject: FS.importSubject || (isProdukSaja ? 'product only, no person' : 'a person'),
    mood_and_tone: effMood,
    ...(function(){
      // FIX BUG: critical_rule sebelumnya cuma baca FS.importCriticalRule
      // (beku dari JSON impor awal). Kalau JSON yang diimpor tidak (atau
      // belum) punya critical_rule sendiri, reference_photos yang direkonstruksi
      // dari FS.refs (lihat fix reference_photos di bawah) tidak dapat instruksi
      // "baca tiap foto secara selektif" sama sekali — padahal jalur normal
      // SELALU menyertakan default ini kapanpun ada reference_photos.
      let hasRealRefsImp = (FS.refs && FS.refs.some(function(r){return r.type!=='outfit_random';})) || (FS.importRefPhotos||[]).some(function(p){return p && !_fREF_LABEL_TO_KEY[p.type];});
      if(FS.importCriticalRule && hasRealRefsImp) return {critical_rule: FS.importCriticalRule};
      return hasRealRefsImp ? {critical_rule: 'Read each reference photo SELECTIVELY. Extract ONLY the specified elements from each photo and ignore everything else. Every extract_only and ignore_completely directive is ABSOLUTE — do NOT blend elements across photos unless explicitly stated.'} : {};
    })(),
    ...(function(){
      // FIX BUG: conflict_priority sebelumnya cuma baca FS.importConflictRule
      // (beku dari JSON awal) — tidak pernah baca FS.conflictLevel yang
      // dihitung ULANG secara live tiap kali user reopen step "Cara Tampil
      // Produk" (fPickHold/fPickHoldCustom mendeteksi konflik nama produk vs
      // foto outfit). Akibatnya kalau konflik BARU terdeteksi setelah impor
      // (mis. user ganti nama produk jadi item yang overlap dengan foto
      // outfit), instruksi prioritas top-level ini tidak ikut muncul —
      // padahal instruksi ignore_completely per-foto outfit sudah ikut
      // ter-update (lihat fix reference_photos di bawah). Disamakan dengan
      // conflictRule di _fBuildPromptJSON.
      if(FS.conflictLevel === 1){
        return {conflict_priority: 'PRIORITY OVERRIDE: The product photo is the SINGLE authoritative source for ' + FS.produkNama + '. Any appearance of a similar item in other reference photos (especially the outfit photo) must be completely IGNORED and replaced by the product from the product reference photo. The product photo takes absolute priority over all other photos for this specific item.'};
      }
      return (FS.importConflictRule && FS.refs && FS.refs.some(function(r){return r.type==='produk';})) ? {conflict_priority: FS.importConflictRule} : {};
    })(),
    // FIX BUG KRITIS — REFERENCE_PHOTOS TIDAK PERNAH KE-UPDATE: sebelumnya
    // baris ini ({reference_photos: FS.importRefPhotos}) selalu pakai array
    // MENTAH hasil parse JSON saat pertama kali ditempel — TIDAK PERNAH
    // disinkronkan ulang ke FS.refs yang sudah diedit user (fokus/extract/
    // ignore/ukuran produk di Step 1). Akibatnya: SEMUA edit yang dilakukan
    // user di Step 1 pada foto referensi (wajah/outfit/produk/dll) setelah
    // impor SAMA SEKALI TIDAK NGEFEK ke hasil generate — user kira sudah
    // keedit, padahal yang dipakai tetap teks lama dari JSON impor.
    // Sekarang dibangun ulang dari FS.refs terkini, persis pola yang sama
    // dipakai jalur normal (_fBuildPromptJSON) dan yang sudah dipakai untuk
    // generated_outfit di bawah — photo_number di-renumber ulang.
    ...(function(){
      // FITUR BARU (permintaan user): jalur import (tempel JSON prompt lama)
      // WAJIB pakai urutan yang SAMA dengan jalur normal — 1) Wajah/Karakter,
      // 2) Outfit, 3) Produk/Objek — bukan urutan mentah FS.refs. Sebelumnya
      // fungsi ini TIDAK memanggil fSortRefsForOrder() sama sekali, jadi
      // hasil generate lewat "Import Prompt Lama" bisa punya urutan foto
      // berbeda dari yang tampil di Step 1 (F1/F2/F3) maupun dari jalur
      // generate normal (_fBuildPromptJSON) — padahal urutan ini menentukan
      // urutan upload foto ke Google Flow, jadi kalau salah, hasil fotonya
      // ikut salah juga.
      let realRefsImp = FS.refs ? fSortRefsForOrder(FS.refs.filter(function(r){return r.type!=='outfit_random';})) : [];
      let photoCounterImp = 0;
      let refPhotosImp = realRefsImp.map(function(r){
        let def = FTYPE[r.type];
        if(!def) return null;
        photoCounterImp++;
        let extractText = (r.extractCustom !== undefined ? r.extractCustom : def.extract).trim();
        let ignoreText = (r.ignoreCustom !== undefined ? r.ignoreCustom : def.ignore).trim();
        let obj = { photo_number: photoCounterImp, type: def.label };
        if(extractText) obj.extract_only = extractText + (r.ukuran && r.type==='produk' ? '. Product physical size: '+r.ukuran+' — render the product accurately to this size ratio relative to the scene.' : '');
        if(ignoreText) obj.ignore_completely = ignoreText;
        if(r.type==='pose') obj.detail = 'Use this photo ONLY as a body-pose guide for the character from the character reference photo. Copy only the pose (head tilt, gaze direction, hand and finger positions, arm and leg positions, posture, body lean, facing direction). Do NOT carry over the face, hair, skin tone, body shape, clothing, accessories, background, lighting, or any objects from this photo.' + (r.focus ? ' Pose notes: ' + r.focus : '');
        else if(r.focus) obj.detail = r.focus;
        return obj;
      }).filter(Boolean);
      // Jaga-jaga: kalau JSON yang diimpor punya entri reference_photos dengan
      // "type" yang TIDAK dikenali aplikasi (jadi tidak pernah disinkronkan ke
      // FS.refs sejak awal impor), tetap sertakan apa adanya di sini supaya
      // datanya tidak hilang begitu saja dari hasil generate.
      let unknownOriginal = (FS.importRefPhotos || []).filter(function(p){
        return p && !_fREF_LABEL_TO_KEY[p.type];
      });
      unknownOriginal.forEach(function(p){
        photoCounterImp++;
        refPhotosImp.push(Object.assign({}, p, {photo_number: photoCounterImp}));
      });
      return refPhotosImp.length ? {reference_photos: refPhotosImp} : {};
    })(),
    // FIX IMPORT OUTFIT AI: bangun ulang generated_outfit dari FS.refs yang
    // sekarang (sumber kebenaran setelah user edit), bukan array statis hasil
    // parse awal — supaya perubahan teks di Step 1 ikut kepakai saat generate ulang.
    ...(function(){
      // FIX BUG KONTRADIKSI PRODUK-SAJA: sebelumnya generated_outfit tidak
      // pernah dicek terhadap isProdukSaja — padahal exclude filter shot
      // "Detail Produk (tanpa karakter)" (F_SHOT_TYPES.detail.excludeRefTypes)
      // TIDAK memasukkan 'outfit_random', jadi kalau prompt impor punya
      // generated_outfit atau ref outfit_random, shot yang seharusnya "no
      // person" tetap bisa membawa instruksi "generate outfit lengkap untuk
      // karakter" — kontradiksi diri sendiri. Disamakan dengan jalur normal
      // (_fBuildPromptJSON, syarat "!ov.forceProdukSaja").
      if(isProdukSaja) return {};
      // FIX BUG TC2 — GENERATED_OUTFIT NYANGKUT: sebelumnya kalau FS.refs
      // sudah tidak punya outfit_random lagi (user hapus foto AI Outfit),
      // kode ini fallback ke FS.importGeneratedOutfit — array MENTAH beku
      // dari JSON impor awal yang tidak pernah dibersihkan waktu ref-nya
      // dihapus. Akibatnya generated_outfit tetap muncul di hasil generate
      // dengan data outfit yang sudah dihapus user. FS.refs adalah sumber
      // kebenaran (sama seperti reference_photos di atas) — kalau kosong,
      // artinya memang tidak ada outfit AI lagi, jangan fallback ke apa pun.
      let outfitRefsGO = FS.refs ? FS.refs.filter(function(r){return r.type==='outfit_random';}) : [];
      let goList = outfitRefsGO.map(function(r,i){
        return {
          outfit_number: i+1,
          instruction: 'DO NOT look for a reference photo for this outfit. Instead, GENERATE the complete outfit entirely from this text description.',
          description: r.focus || '',
          generate: 'Create a complete, cohesive outfit — all garments, colors, textures, accessories, and styling details — based solely on the description above. Make it look naturally worn on the character, realistic, and consistent with the overall scene.'
        };
      });
      return goList.length ? {generated_outfit: goList} : {};
    })(),
    ...(effProductBlock ? {product: effProductBlock} : {}),
    scene: {
      location: effLokasi,
      ...(isProdukSaja || !effPose ? {} : {pose: effPose}),
      ...(effKamera ? {camera_framing: effKamera} : {}),
      camera_angle: effAngle,
      lighting: effCahaya,
      mood_and_tone: effMood
    },
    output_quality: effQualityImp
  };
  if(FS.importStyleReference) fullJson.style_reference = FS.importStyleReference;

  // FIX NOMOR FOTO LOKASI BASI PASCA-EDIT IMPOR: teks Lokasi/Cahaya dari JSON lama menyebut nomor foto ("reference photo 2").
  // Kalau user menghapus/menambah foto lain di Foto Referensi, nomor foto lokasi bergeser, tapi teks lama tetap menyebut nomor lama
  // -> JSON merujuk foto yang salah. Sekarang nomor itu dihitung ulang dari urutan foto yang aktif (hanya untuk teks lokasi & cahaya).
  try{
    let _ordL = FS.refs ? fSortRefsForOrder(FS.refs.filter(function(r){return r.type!=='outfit_random';})) : [], _nL = 0;
    for(let _i=0;_i<_ordL.length;_i++){ if(_ordL[_i].type==='lokasi'){ _nL=_i+1; break; } }
    if(_nL){
      let _fix = function(t){ return (typeof t==='string') ? t.replace(/reference photo \d+/g,'reference photo '+_nL) : t; };
      if(fullJson.scene){ fullJson.scene.location=_fix(fullJson.scene.location); fullJson.scene.lighting=_fix(fullJson.scene.lighting); }
      if(fullJson.output_quality && typeof fullJson.output_quality==='object') fullJson.output_quality.lighting=_fix(fullJson.output_quality.lighting);
      if(typeof fullJson.prompt==='string') fullJson.prompt=fullJson.prompt.replace(/((?:location shown in|taken entirely from|lighting of) reference photo )\d+/g,'$1'+_nL);
    }
  }catch(_e){}

  let subjekLabel = ov.label || 'Prompt Diimpor';
  // FIX BUG NOTICE URUTAN FOTO TIDAK SINKRON PASCA-EDIT IMPOR: sebelumnya
  // realRefs/randomRefs di sini SELALU dikembalikan kosong (hardcode []),
  // padahal reference_photos di fullJson di atas sudah benar dibangun ulang
  // dari FS.refs yang LIVE (bisa beda dari saat pertama impor, kalau user
  // tambah/hapus/edit foto di Step 1 setelah impor). Akibatnya fBuildUploadNotice()
  // selalu jatuh ke fallback-nya yang pakai FS.importRefPhotos — snapshot BEKU
  // dari JSON yang pertama kali ditempel — jadi notifikasi urutan upload bisa
  // menampilkan daftar lama yang sudah tidak sesuai dengan reference_photos
  // yang sebenarnya dikirim di JSON hasil generate. Sekarang dihitung dari
  // FS.refs yang sama seperti dipakai untuk membangun reference_photos di atas,
  // supaya notice selalu match dengan JSON aktual. Ini juga otomatis
  // memperbaiki notice multi-shot untuk prompt hasil impor: FS.refs sudah
  // difilter sesuai excludeRefTypes shot yang bersangkutan oleh pemanggil
  // (_fDoGenerateMultiShot) sebelum fungsi ini dipanggil.
  let realRefsImp = FS.refs ? fSortRefsForOrder(FS.refs.filter(function(r){return r.type!=='outfit_random';})) : [];
  let randomRefsImp = FS.refs ? FS.refs.filter(function(r){return r.type==='outfit_random';}) : [];
  return {fullJson, realRefs: realRefsImp, randomRefs: randomRefsImp, subjekLabel};
}

function fToggleImportArea(){
  let area = document.getElementById('f-import-area');
  if(area) area.classList.toggle('hidden');
}

// ── REVERSE-LOOKUP LABEL — dipakai saat import prompt lama ──────────────
// Prompt lama cuma berisi teks deskripsi panjang (val), bukan label pendek
// yang tampil di UI (mis. "Ruang Tamu Mewah"). Fungsi-fungsi ini mencari
// label pendek yang cocok dengan cara mencocokkan teks val ke chip yang
// sudah ada di halaman (untuk lokasi/cahaya/angle/mood) atau ke data
// pose/HOLD_MAP (untuk pose & cara tampil produk). Kalau tidak ketemu,
// caller akan fallback ke teks asli yang dipotong.
function _fReverseLookupChip(text, funcName){
  if(!text) return null;
  let t = String(text).trim();
  let els = document.querySelectorAll('[onclick^="'+funcName+'("]');
  let re = new RegExp(funcName+"\\('((?:[^'\\\\]|\\\\.)*)'\\s*,\\s*this\\s*,\\s*'((?:[^'\\\\]|\\\\.)*)'\\)");
  for(let i=0;i<els.length;i++){
    let oc = els[i].getAttribute('onclick')||'';
    let m = oc.match(re);
    if(m && m[1].trim()===t) return m[2];
  }
  return null;
}
function _fFindPoseLabel(text){
  if(!text) return null;
  let t = String(text).trim();
  for(let subj in POSES_NO_PRODUK){
    let arr = POSES_NO_PRODUK[subj];
    for(let i=0;i<arr.length;i++) if(arr[i][0].trim()===t) return arr[i][1];
  }
  for(let subj in POSES_WITH_PRODUK){
    let byHold = POSES_WITH_PRODUK[subj];
    for(let hk in byHold){
      let arr = byHold[hk];
      for(let i=0;i<arr.length;i++) if(arr[i][0].trim()===t) return arr[i][1];
    }
  }
  return null;
}
function _fFindHoldLabel(text){
  if(!text) return null;
  let t = String(text).trim();
  if(t.indexOf('worn directly on the character as an accessory or garment')===0) return 'Dipakai langsung';
  if(t.indexOf('dipakai langsung oleh karakter')===0) return 'Dipakai langsung';
  if(t.indexOf('memperlihatkan produk ke kamera')===0) return 'Dipegang — diarahkan ke kamera';
  if(t.indexOf('sudah terpasang pada hanger')===0) return 'Pakai hanger — ke kamera';
  if(t.indexOf('held in both hands directed straight toward the camera lens')===0) return 'Dipegang — diarahkan ke kamera';
  if(t.indexOf('held in one hand and directed toward the camera lens')===0) return 'Dipegang — diarahkan ke kamera';
  if(t.indexOf('displayed on a hanger presented by the character to the camera')===0) return 'Pakai hanger — ke kamera';
  return null;
}
const _fSUBJECT_TEXT_MAP = {
  'a woman': {subjek:'hijab', label:'Perempuan'},
  'a man': {subjek:'pria', label:'Laki-laki'},
  'a person': {subjek:'hijab', label:'Karakter (dari prompt lama)'}
};
function _fTrunc(text, n){
  if(!text) return '';
  let t = String(text).trim();
  return t.length>n ? t.substring(0,n)+'…' : t;
}

// Cari nilai teks di antara kunci "key": "..." di JSON mentah — dipakai
// sebagai fallback kalau JSON.parse gagal karena user paste teks yang
// sedikit rusak/terpotong.
function _fImportExtractField(rawText, key){
  let re = new RegExp('"' + key + '"\\s*:\\s*"((?:[^"\\\\]|\\\\.)*)"');
  let m = rawText.match(re);
  if(!m) return '';
  try{ return JSON.parse('"' + m[1] + '"'); }catch(e){ return m[1]; }
}

// Peta label tipe foto (yang tersimpan di JSON hasil generate, field "type")
// balik ke key internal FTYPE — dipakai import buat mencocokkan reference_photos
// ke tipe chip yang benar (Wajah/Outfit/Produk/dst).
const _fREF_LABEL_TO_KEY={
  'Wajah Karakter':'wajah',
  'Outfit Lengkap':'outfit',
  'Baju Atasan':'atasan',
  'Baju Bawahan':'bawahan',
  'Aksesori':'aksesori',
  'Produk':'produk',
  'Hewan / Objek':'objek',
  'Lokasi':'lokasi',
  'Pose Referensi':'pose'
};

// Pembaca JSON longgar untuk impor prompt lama (v11.58): terima JSON biasa, JSON yang
// ter-escape dua kali (string), array [ {...} ] (ambil objek prompt pertama), dan teks
// yang kutip lurusnya berubah jadi kutip pintar (“ ”) karena lewat WhatsApp/Notes/Word.
function _fImportParseLoose(txt){
  function tryP(s){ try{ return JSON.parse(s); }catch(e){ return undefined; } }
  function pick(p, depth){
    if(depth>2) return null;
    if(typeof p==='string'){ let q=tryP(p.trim()); return q===undefined ? null : pick(q, depth+1); }
    if(Array.isArray(p)){
      for(let i=0;i<p.length;i++){ let x=pick(p[i], depth+1); if(x && (x.scene||x.product||x.prompt)) return x; }
      return null;
    }
    return (p && typeof p==='object') ? p : null;
  }
  function sanitize(s){
    return s.replace(/[\u201C\u201D\u201E\u201F\u00AB\u00BB]/g,'"').replace(/[\u2018\u2019\u201A\u201B]/g,"'").replace(/[\u00A0\u200B\uFEFF]/g,' ');
  }
  // v14.11: koma berlebih sebelum } atau ] (sering muncul kalau JSON disalin dari chat/editor) dibuang.
  function noTrail(s){ return s.replace(/,\s*([}\]])/g,'$1'); }
  let cands=[txt];
  let s=txt.indexOf('{'), en=txt.lastIndexOf('}');
  if(s!==-1 && en>s) cands.push(txt.substring(s,en+1));
  let t2=sanitize(txt);
  if(t2!==txt){
    cands.push(t2);
    let s2=t2.indexOf('{'), e2=t2.lastIndexOf('}');
    if(s2!==-1 && e2>s2) cands.push(t2.substring(s2,e2+1));
  }
  let extra=[];
  cands.forEach(function(c){ let n=noTrail(c); if(n!==c) extra.push(n); });
  cands=cands.concat(extra);
  for(let i=0;i<cands.length;i++){
    let p=tryP(cands[i]);
    if(p===undefined) continue;
    let r=pick(p,0);
    if(r) return r;
  }
  // v14.11: JSON terpotong / rusak (mis. kurang kurung penutup karena salin tidak lengkap) —
  // dulu langsung ditolak. Sekarang ambil isian scene per-kunci pakai regex; foto referensi tidak ikut.
  let flat=t2;
  let sc={}, got=0;
  ['location','lighting','camera_angle','camera_framing','pose','mood_and_tone'].forEach(function(k){
    let v=_fImportExtractField(flat,k);
    if(v){ sc[k]=v; got++; }
  });
  if(!got) return null;
  return {prompt:_fImportExtractField(flat,'prompt'), subject:_fImportExtractField(flat,'subject'), scene:sc, __loose:true};
}

function fImportPrompt(){
  // v11.58: validasi teks (kosong / bukan JSON / tanpa isian) dilakukan DULU, baru dialog konfirmasi
  // "timpa isian" — dulu dialog muncul lebih awal sehingga user disuruh konfirmasi dulu baru
  // dikasih tahu textarea-nya kosong. State lama (strip status impor) juga baru dibersihkan setelah lolos.
  let errBox = document.getElementById('f-import-error');
  let statusBox = document.getElementById('f-import-status');
  if(errBox){errBox.classList.add('hidden');errBox.textContent='';}

  let raw = document.getElementById('f-import-textarea').value.trim();
  if(!raw){showToast('Paste dulu JSON prompt-nya ya','error');return;}

  // Bersihkan markdown fence kalau ada, lalu coba parse langsung
  let cleaned = raw.replace(/^```json\s*/i,'').replace(/^```\s*/,'').replace(/\s*```$/,'').trim();
  let parsed = _fImportParseLoose(cleaned);

  let scene = parsed && parsed.scene;
  if(!parsed || (!scene && !parsed.product && !parsed.prompt)){
    if(errBox){
      errBox.textContent = 'Teks ini kelihatannya bukan JSON prompt dari tools kita, atau formatnya rusak. Pastikan kamu paste JSON lengkapnya (dari tanda { paling awal sampai } paling akhir).';
      errBox.classList.remove('hidden');
    }
    showToast('Gagal baca prompt — cek lagi teksnya','error');
    return;
  }
  scene = scene || {};
  // VALIDASI ISI (hasil audit): JSON yang valid tapi tidak membawa satu pun isian (mis. cuma {"prompt":"..."})
  // dulu tetap dianggap "berhasil" — wizard dikosongkan lalu diisi mode Produk Saja yang kosong. Sekarang
  // ditolak SEBELUM state wizard disentuh, jadi isian yang sedang berjalan tidak hilang percuma.
  if(!(scene.location||scene.lighting||scene.camera_angle||scene.pose||scene.mood_and_tone||parsed.mood_and_tone||(parsed.product&&parsed.product.name))){
    if(errBox){
      errBox.textContent = 'JSON-nya terbaca, tapi tidak ada isian yang bisa diambil (lokasi, cahaya, sudut kamera, pose, mood, atau produk). Pastikan yang ditempel JSON lengkap dari tools ini.';
      errBox.classList.remove('hidden');
    }
    showToast('Tidak ada isian yang bisa diambil dari prompt ini','error');
    return;
  }

  // PENGAMAN (permintaan user: fitur ini tidak boleh mengganggu proses pembuatan prompt foto):
  // impor MENULIS ULANG semua step foto. Kalau wizard sudah ada isinya, minta konfirmasi dulu supaya
  // isian yang sedang berjalan tidak hilang karena salah tap.
  if(!window._fImportConfirmed && (FS.subjek||FS.lokasi||FS.pose||FS.cahaya||FS.angle||FS.mood||FS.produkNama)){
    showConfirm('Impor akan menimpa isian wizard foto yang sedang berjalan. Lanjutkan?',function(){
      window._fImportConfirmed=true;
      try{ fImportPrompt(); }finally{ window._fImportConfirmed=false; }
    },null,'Ya, Timpa');
    return;
  }
  // Buang sisa "step yang ketutup sementara karena lagi diedit" dari sesi sebelumnya.
  STEP_PAUSE_STACK.foto=[];
  if(statusBox){statusBox.classList.add('hidden');statusBox.textContent='';}
  let _impArea0 = document.getElementById('f-import-area'); if(_impArea0) _impArea0.classList.remove('ft-imported');

  // FIX BUG HANGER/RIWAYAT NYANGKUT: sebelum ini, field FS (lokasi, cahaya,
  // angle, pose, kamera, mood, hold, holdKey, produkMode, dst) cuma diisi
  // KALAU field yang bersangkutan ADA di JSON yang ditempel (pola
  // "if(scene.X){FS.X=...}"), TANPA ada else yang membersihkan nilai lama.
  // Akibatnya kalau JSON yang diimpor tidak membawa suatu field (mis. tidak
  // ada "product", atau scene tidak ada "camera_angle"), FS.X tetap berisi
  // nilai dari sesi SEBELUMNYA (manual atau impor lain) — itu sebabnya foto
  // bisa muncul pakai hanger padahal tidak disetel di prompt yang baru
  // ditempel. Reset dulu semua field wizard ke kosong di sini, supaya
  // hasil impor selalu murni dari JSON yang baru, tidak ada riwayat nyangkut.
  FS.subjek=''; FS.produkMode=''; FS.produkNama='';
  FS.holdKey=''; FS.hold='';
  FS.pose=''; FS.poseLabel=''; FS.poseDesc='';
  FS.lokasi=''; FS.lokasiLabel=''; FS.lokasiDesc='';
  FS.kamera='';
  FS.cahaya=''; FS.cahayaLabel=''; FS.cahayaDesc='';
  FS.angle=''; FS.angleLabel=''; FS.angleDesc='';
  FS.mood=''; FS.moodLabel='';
  FS.conflictLevel=0; FS.shotOverrides={};
  FS.povProduk=false; FS.holdLabel=''; FS.povPlacement=''; FS.povCamera='';   // keluar dari mode Produk saja · POV
  if(typeof povSync==='function')povSync();

  // isProdukSaja: prompt lama tanpa pose di scene = mode produk-saja
  // FIX (audit): dulu produk-saja = "tidak ada pose" saja, jadi prompt karakter (subject "a woman"/"a man")
  // yang kebetulan tanpa pose salah diimpor sebagai Produk Saja — hasil generate-nya jadi kontradiktif
  // ("no person visible" tapi subject: a woman). Sekarang teks subject ikut menentukan; tebakan lama
  // (tanpa pose) hanya dipakai kalau subject tidak mengenali karakter.
  let _impSubjTxt = String(parsed.subject || (parsed.prompt ? _fImportExtractField(cleaned,'subject') : '') || '').trim().toLowerCase();
  FS.importIsProdukSaja = false; // mode "Produk Saja" sudah dihapus
  let _impSubjProdukOnly = (_impSubjTxt === 'product only, no person');
  FS.importActive = true;
  FS.importSubject = parsed.subject || (parsed.prompt ? _fImportExtractField(cleaned,'subject') : '') || '';
  FS.importRefPhotos = Array.isArray(parsed.reference_photos) ? parsed.reference_photos : [];
  FS.importCriticalRule = parsed.critical_rule || '';
  FS.importConflictRule = parsed.conflict_priority || '';
  FS.importGeneratedOutfit = Array.isArray(parsed.generated_outfit) ? parsed.generated_outfit : [];
  // FIX IMPORT FOTO REF: sebelumnya reference_photos (Wajah/Produk/dst) dan
  // generated_outfit (Outfit AI) cuma disimpan sebagai teks mentah di
  // FS.importRefPhotos/FS.importGeneratedOutfit dan TIDAK PERNAH
  // disinkronkan ke FS.refs — padahal chip badge, kotak edit teks, dan list
  // foto di Step 1 semuanya baca dari FS.refs. Akibatnya waktu dibuka lagi,
  // semuanya kelihatan kosong/"butuh foto" padahal datanya ada di JSON.
  // Sekarang: setiap item disinkronkan jadi FS.refs beneran, supaya muncul
  // & bisa diedit langsung di list foto, sama seperti alur manual.
  FS.refs = []; FS.refCounter = 0; FS.hasProdukFoto = false;
  FS.importRefPhotos.forEach(function(p){
    if(!p) return;
    let keyRP = _fREF_LABEL_TO_KEY[p.type];
    if(!keyRP || !FTYPE[keyRP]) return; // tipe tidak dikenal — tetap tercatat di notice teks, dilewati di sini
    FS.refCounter++;
    let idRP='fr'+FS.refCounter;
    let defRP=FTYPE[keyRP];
    FS.refs.push({
      id:idRP, type:keyRP,
      focus:p.detail?String(p.detail):((keyRP==='produk'&&parsed.product&&parsed.product.name)?String(parsed.product.name):''),
      extractCustom:(p.extract_only!==undefined&&p.extract_only!==null&&p.extract_only!=='')?String(p.extract_only):defRP.extract,
      ignoreCustom:(p.ignore_completely!==undefined&&p.ignore_completely!==null&&p.ignore_completely!=='')?String(p.ignore_completely):defRP.ignore,
      autoSyncOutfit:false // FIX: teks Ambil/Abaikan hasil impor jangan ditimpa fSyncWajahOutfitDefault()
    });
    if(keyRP==='produk') FS.hasProdukFoto=true;
  });
  FS.importGeneratedOutfit.forEach(function(g){
    FS.refCounter++;
    let idGO='fr'+FS.refCounter;
    let defGO=FTYPE['outfit_random'];
    FS.refs.push({id:idGO,type:'outfit_random',focus:(g&&g.description)?String(g.description):'',extractCustom:defGO.extract,ignoreCustom:defGO.ignore});
  });
  FS.importProductBlock = parsed.product || null;
  FS.importOutputQuality = parsed.output_quality || null;
  FS.importStyleReference = parsed.style_reference || null;

  // Isi FS scene fields — teks lengkap dari prompt lama TETAP disimpan apa
  // adanya di FS.xDesc/FS.x (dipakai untuk generate ulang & untuk isi ulang
  // kotak "tulis sendiri" kalau user tap "ubah"). FS.xLabel dicoba dicocokkan
  // ke label pendek chip bawaan supaya tampilannya rapi seperti waktu diisi
  // manual — kalau tidak ketemu, fallback ke label 'Custom' + teks dipotong.
  let filled = [];

  if(scene.location){
    FS.lokasi = scene.location; FS.lokasiDesc = scene.location;
    let m = _fReverseLookupChip(scene.location,'fPickLokasi');
    FS.lokasiLabel = m || 'Custom';
    doneCard('f5','fa5', m || _fTrunc(scene.location,40));
    filled.push('Lokasi');
  }
  if(scene.lighting){
    FS.cahaya = scene.lighting; FS.cahayaDesc = scene.lighting;
    let m = _fReverseLookupChip(scene.lighting,'fPickCahaya');
    FS.cahayaLabel = m || 'Custom';
    doneCard('f7','fa7', m || _fTrunc(scene.lighting,40));
    filled.push('Cahaya');
  }
  if(scene.camera_angle){
    FS.angle = scene.camera_angle; FS.angleDesc = scene.camera_angle;
    let m = _fReverseLookupChip(scene.camera_angle,'fPickAngle');
    FS.angleLabel = m || 'Custom';
    doneCard('f8','fa8', m || _fTrunc(scene.camera_angle,40));
    filled.push('Sudut Kamera');
  }
  if(scene.pose){
    FS.pose = scene.pose; FS.poseDesc = scene.pose;
    let m = _fFindPoseLabel(scene.pose);
    FS.poseLabel = m || 'Custom';
    doneCard('f4','fa4', m || _fTrunc(scene.pose,40));
    filled.push('Pose');
  }
  if(scene.camera_framing) FS.kamera = scene.camera_framing;
  FS.mood = scene.mood_and_tone || parsed.mood_and_tone || '';
  if(FS.mood){
    let m = _fReverseLookupChip(FS.mood,'fPickMood');
    FS.moodLabel = m || 'Custom';
    doneCard('f9','fa9', m || _fTrunc(FS.mood,40));
    filled.push('Mood & Tone');
  }
  if(FS.importProductBlock && FS.importProductBlock.name) FS.produkNama = FS.importProductBlock.name;
  // v11.58: JSON lama bisa membawa blok "product" TANPA foto bertipe Produk di reference_photos.
  // Dulu blok itu hilang diam-diam saat generate ulang. Tandai supaya tetap dipakai.
  FS.importProdukNoPhoto = !!(FS.importProductBlock && FS.importProductBlock.name && !FS.hasProdukFoto);
  // Tanda tangan cahaya+mood+mode saat impor — dipakai builder untuk tahu apakah output_quality
  // asli dari JSON masih cocok, atau harus disesuaikan ulang karena user mengedit cahaya/mood.
  FS.importSceneSig = String(FS.cahayaDesc||FS.cahaya||'')+'||'+String(FS.mood||'')+'||'+((FS.importIsProdukSaja||(typeof fIsNoChar==='function'&&fIsNoChar()))?'1':'0');
  if(_impSubjProdukOnly && !(typeof fIsNoChar==='function'&&fIsNoChar())) showToast('Mode "Produk Saja" sudah dihapus — prompt ini diimpor sebagai karakter, silakan pilih pose-nya.','error');

  // Subjek — cocokkan teks "subject" dari prompt lama ke jenis subjek yang dikenal
  let subjMatch = _fSUBJECT_TEXT_MAP[String(FS.importSubject||'').trim().toLowerCase()];
  if(subjMatch){
    FS.subjek = subjMatch.subjek;
    doneCard('f0','fa0', subjMatch.label);
  } else {
    FS.subjek = FS.subjek || 'hijab';
    doneCard('f0','fa0', FS.importSubject ? _fTrunc(FS.importSubject,40) : 'Dari prompt lama');
  }

  // FIX BUG PANEL PRODUK-SAJA TIDAK PERNAH DITOGGLE: sebelumnya fToggleF1Panel
  // (yang switch antara panel "karakter" dan panel "produk-saja" untuk step
  // Foto Referensi/f1, Lokasi/f5, Cahaya/f7, Angle/f8 — termasuk chip khusus
  // "Dipegang Tangan" di panel produk-saja f8) HANYA dipanggil dari fPickSubjek
  // (pilih subjek manual). fImportPrompt men-set FS.subjek='produk' langsung
  // tanpa pernah memanggil fToggleF1Panel — padahal semua panel produk-saja
  // default-nya display:none di HTML. Akibatnya kalau user reopen (tap "Edit"
  // di Ringkasan) step Lokasi/Cahaya/Angle untuk prompt produk-saja hasil
  // impor, yang muncul adalah panel KARAKTER (salah), bukan panel produk —
  // chip "Dipegang Tangan" jadi sama sekali tidak reachable dari UI. Sekarang
  // dipanggil di sini juga, supaya panel yang tampil selalu sinkron dengan
  // FS.subjek hasil impor.
  fToggleF1Panel();

  // Cara Tampil Produk — cocokkan teks placement ke HOLD_MAP
  if(FS.importProductBlock){
    let holdLabel = _fFindHoldLabel(FS.importProductBlock.placement);
    // v11.58: untuk hanger, simpan HANYA bagian setelah prefix (sama seperti HOLD_MAP.hanger.val).
    // _fComputePlacement() menambahkan prefix sendiri; kalau FS.hold sudah berisi placement penuh,
    // prefix-nya menumpuk lagi di setiap impor→generate.
    let _impPl = String(FS.importProductBlock.placement || '');
    if(holdLabel === 'Pakai hanger — ke kamera'){
      let _hp = 'displayed on a hanger presented by the character to the camera';
      let _rest = _impPl.indexOf(_hp)===0 ? _impPl.substring(_hp.length).replace(/^\s*[—–-]+\s*/,'').trim() : '';
      FS.hold = _rest || HOLD_MAP.hanger.val;
    } else {
      FS.hold = _impPl;
    }
    FS.holdKey = holdLabel ? {'Dipakai langsung':'dipakai','Pakai hanger — ke kamera':'hanger','Dipegang — diarahkan ke kamera':'tangan'}[holdLabel] : 'custom';
    // FIX RINGKASAN IMPORT: FS.produkMode sebelumnya tidak pernah di-set di
    // sini, padahal fRenderSummary() baris "Cara Tampil" hanya muncul kalau
    // FS.produkMode === 'pegang'. Akibatnya row "Cara Tampil" hilang dari
    // Ringkasan meski FS.hold/FS.holdKey sudah terisi & step 3 sudah bisa
    // diedit dengan benar. Import selalu memakai jalur "pegang" (bukan
    // 'foto', karena import tidak pernah membawa foto produk asli).
    FS.produkMode = 'pegang';
    doneCard('f3','fa3', holdLabel || ('Diimpor: '+(FS.importProductBlock.name||'')));
  }

  // FIX IMPORT — SEMBUNYIKAN STEP CARDS: pastikan SEMUA card step 1-8
  // tersembunyi setelah import, jadi yang kelihatan cuma Ringkasan. doneCard()
  // di atas sudah otomatis nge-hide tiap kartu yang field-nya ada di JSON;
  // loop ini jaring pengaman untuk kartu yang datanya kebetulan tidak ada
  // (mis. JSON hasil edit manual yang field-nya dihapus), supaya tidak
  // nyangkut kebuka. Edit tetap bisa lewat tombol "Edit" di Ringkasan.
  ['f0','f1','f3','f4','f5','f7','f8','f9'].forEach(function(id){
    let c = document.getElementById(id);
    if(c){ c.classList.add('done'); c.classList.remove('pending'); c.classList.add('hidden'); }
  });
  let refTypes = FS.importRefPhotos.map(function(p){return p && p.type;}).filter(Boolean);
  refTypes = refTypes.filter(function(v,i){return refTypes.indexOf(v)===i;});
  doneCard('f1','fa1', refTypes.length ? (FS.importRefPhotos.length+' foto ('+refTypes.join(', ')+')') : 'Referensi diimpor');

  // Refresh chip badge & list foto Step 1 supaya Outfit AI (dan foto lain
  // yang barusan disinkronkan ke FS.refs) langsung kelihatan terisi, bukan
  // nunggu re-render manual.
  if(typeof fUpdateCounters === 'function') fUpdateCounters();
  if(typeof fRenderList === 'function') fRenderList();

  let genArea = document.getElementById('f-gen-area');
  if(genArea) genArea.classList.remove('hidden');
  if(typeof fRenderSummary === 'function') fRenderSummary();

  let _impMissing = [];
  if(!FS.lokasi && !(typeof fHasLokasiRef==='function' && fHasLokasiRef())) _impMissing.push('Lokasi');
  if(!FS.cahaya && !(typeof fHasLokasiRef==='function' && fHasLokasiRef())) _impMissing.push('Cahaya');
  if(!FS.angle) _impMissing.push('Sudut Kamera');
  if(!FS.mood) _impMissing.push('Mood & Tone');
  if(!FS.importIsProdukSaja && !(typeof fIsNoChar==='function'&&fIsNoChar()) && !FS.pose && !(FS.refs||[]).some(function(r){return r.type==='outfit_random'&&r.focus;})) _impMissing.push('Pose');
  if((FS.refs||[]).some(function(r){return r.type==='produk'&&!(r.focus&&String(r.focus).trim());})) _impMissing.push('Nama produk (di Foto Referensi)');
  if(statusBox){
    statusBox.innerHTML = 'Berhasil diimpor: <strong>' + esc(filled.join(', ')) + '</strong>. Tap "Edit" di Ringkasan buat ganti isian sebelum generate ulang.' + (_impMissing.length ? '<br><span style="color:var(--red);">Belum terisi: <strong>' + esc(_impMissing.join(', ')) + '</strong> — tap "Edit" di Ringkasan dan isi dulu, kalau tidak prompt-nya bolong.</span>' : '') + '<br><button onclick="fCancelImportAsk()" style="background:none;border:none;color:var(--red);font-size:var(--fs-xs);text-decoration:underline;cursor:pointer;padding:4px 0 0;"><svg class="icon"><use href="#ic-close"></use></svg> Batal, mulai dari awal</button>';
    if(parsed.__loose) statusBox.innerHTML += '<br><span style="color:var(--muted);">JSON-nya terpotong/rusak, jadi hanya isian yang terbaca yang diambil. Foto referensi &amp; nama produk tidak ikut — tambahkan lagi di Step Foto Referensi.</span>';
    statusBox.classList.remove('hidden');
  }
  // Setelah impor, area tempel diciutkan jadi strip status saja (lihat CSS .ft-imported) supaya
  // textarea besar tidak menumpuk di atas Ringkasan; tombol "Batal, mulai dari awal" tetap terlihat.
  let _impArea = document.getElementById('f-import-area');
  if(_impArea){ _impArea.classList.remove('hidden'); _impArea.classList.add('ft-imported'); }
  showToast('Prompt lama berhasil diimpor!','success');
  // v14.11 FIX IMPOR PROMPT LAMA: sejak layar "Prompt Foto AI" (Live Console) dipakai, semua kartu wizard, Ringkasan
  // dan tombol Generate HANYA tampil kalau layar itu terbuka (#foto.pfa-open). Impor tidak pernah membukanya,
  // jadi setelah "Import & Isi Otomatis" user cuma melihat strip status dan tidak bisa lanjut ke Generate.
  // Sekarang layar langsung dibuka dan digeser ke Ringkasan + Generate (kecuali sedang tur panduan).
  try{
    if(typeof window.pfaOpen==='function' && !document.body.classList.contains('pb-tour-active')){
      window.pfaOpen();
      setTimeout(function(){ try{ if(typeof window.pfaView==='function') window.pfaView('prompt'); }catch(e){} },150);
    }
  }catch(e){}
  setTimeout(()=>genArea && genArea.scrollIntoView({behavior:'smooth',block:'nearest'}),200);
}

// Batalkan import dan kembali ke wizard normal dari awal
// v14.11: dipanggil dari tombol "Mulai dari awal" di strip status impor (dulu fungsi ini tidak punya tombol sama sekali).
function fCancelImportAsk(){
  showConfirm('Impor dibatalkan dan semua isian wizard foto dikosongkan. Lanjutkan?',fCancelImport,null,'Ya, Kosongkan');
}
function fCancelImport(){
  // v14.11: pakai reset penuh yang sama dengan tombol Reset (bersihkan state impor, hasil generate, progress),
  // lalu tutup layar Prompt Foto AI supaya user kembali ke pilihan awal.
  try{
    if(typeof fResetNow==='function'){
      fResetNow();
      try{ if(typeof window.pfaClose==='function') window.pfaClose(); }catch(e){}
      return;
    }
  }catch(e){}
  FS.importActive = false;
  FS.importRefPhotos = null;
  FS.importCriticalRule = '';
  FS.importConflictRule = '';
  FS.importGeneratedOutfit = null;
  FS.importProductBlock = null;
  FS.importOutputQuality = null;
  FS.importStyleReference = null;
  FS.importSubject = '';
  FS.importIsProdukSaja = false; FS.importProdukNoPhoto = false; FS.importSceneSig = '';
  fResetFrom(0);
  let ta = document.getElementById('f-import-textarea'); if(ta) ta.value='';
  let statusBox = document.getElementById('f-import-status'); if(statusBox) statusBox.classList.add('hidden');
  let _impAreaC = document.getElementById('f-import-area'); if(_impAreaC) _impAreaC.classList.remove('ft-imported');
}


// ── Membangun 1 objek JSON prompt. `ov` (opsional) berisi override
// untuk fitur multi-shot: {label, poseOverride, placementOverride,
// kameraNote, forceProdukSaja, introExtra} — dipanggil tanpa argumen
// untuk generate normal (hasilnya identik seperti sebelumnya). ──────
function _fBuildPromptJSON(ov){
  ov = ov || {};
  if(FS.importActive) return _fBuildImportedPromptJSON(ov);

  // ── Pisahkan outfit_random dari foto nyata ──────────────────────
  // outfit_random = instruksi GENERATIF (tidak ada foto fisik untuk di-upload)
  // foto nyata    = semua tipe selain outfit_random (ada foto fisik yang di-upload)
  let realRefs   = FS.refs.filter(r => r.type !== 'outfit_random');
  let randomRefs = FS.refs.filter(r => r.type === 'outfit_random');
  // FITUR BARU (permintaan user): urutan foto referensi di JSON WAJIB tetap
  // 1) Wajah/Karakter, 2) Outfit, 3) Produk/Objek — apapun urutan chip yang
  // ditap user di Step 1 (mis. tap "Produk" duluan, baru "Karakter Sheet"
  // belakangan). Pakai fRefOrderPriority/fSortRefsForOrder yang sama dengan
  // fRenderList() (nomor F1/F2/F3 yang tampil di layar), supaya urutan yang
  // dilihat user di Step 1 selalu konsisten dengan urutan di JSON hasil
  // generate — tidak ada lagi kartu tampil F1=Produk padahal di JSON fotonya
  // jadi nomor 2. Notifikasi "Urutan Foto" (fBuildUploadNotice) otomatis
  // ikut benar karena dipanggil dengan realRefs yang sudah diurutkan ulang
  // ini (lihat _fDoGenerate).
  realRefs = fSortRefsForOrder(realRefs);

  // Build reference_photos — HANYA dari foto nyata, renumber 1..N
  let _noCharPS = !!(ov.forceProdukSaja || FS.subjek==='produk' || fIsNoChar());
  let photoCounter = 0;
  let refPhotos = realRefs.map(r => {
    photoCounter++;
    let def = FTYPE[r.type];
    // FIX: sebelumnya `r.extractCustom || def.extract` — kalau user menghapus
    // teksnya jadi string kosong, itu dianggap falsy dan diam-diam BALIK ke
    // teks default (perubahan user tidak ngefek). Sekarang: cek eksplisit
    // apakah field pernah diisi (bukan undefined), lalu trim. Kalau memang
    // sengaja dikosongkan, key-nya di-OMIT total dari JSON — beneran hilang.
    let extractText = (r.extractCustom !== undefined ? r.extractCustom : def.extract).trim();
    let ignoreText = (r.ignoreCustom !== undefined ? r.ignoreCustom : def.ignore).trim();
    let obj = {
      photo_number: photoCounter,
      type: def.label
    };
    if(extractText) obj.extract_only = extractText + (r.ukuran && r.type==='produk' ? '. Product physical size: '+r.ukuran+' — render the product accurately to this size ratio relative to the scene.' : '');
    if(ignoreText) obj.ignore_completely = ignoreText;
    if(r.type==='lokasi'){
      obj.detail = (_noCharPS
        ? 'Light the product exactly the same way the location is lit, so the shadows, highlights, and color cast on the product match the environment. Add realistic contact shadows on the surface it rests on.'
        : 'Light the character and outfit exactly the same way the location is lit, so the shadows, highlights, and color cast on skin and clothes match the environment. Add realistic contact shadows on the ground.') + (r.focus ? ' Location notes: ' + r.focus : '');
    } else if(r.type==='pose'){
      obj.detail = 'Use this photo ONLY as a body-pose guide for the character from the character reference photo. Copy only the pose (head tilt, gaze direction, hand and finger positions, arm and leg positions, posture, body lean, facing direction). Do NOT carry over the face, hair, skin tone, body shape, clothing, accessories, background, lighting, or any objects from this photo.' + (r.focus ? ' Pose notes: ' + r.focus : '');
    } else if(r.focus) obj.detail = r.focus;
    return obj;
  });

  // Build generated_outfit block — dari outfit_random (teks deskripsi, bukan foto)
  // Setiap item adalah satu instruksi generatif terpisah
  let generatedOutfits = randomRefs.map((r, i) => ({
    outfit_number: i + 1,
    instruction: 'DO NOT look for a reference photo for this outfit. Instead, GENERATE the complete outfit entirely from this text description.',
    description: r.focus || '',
    generate: 'Create a complete, cohesive outfit — all garments, colors, textures, accessories, and styling details — based solely on the description above. Make it look naturally worn on the character, realistic, and consistent with the overall scene.'
  }));

  // Inject conflict priority rule jika level 1
  let conflictRule = '';
  if(FS.conflictLevel === 1){
    conflictRule = 'PRIORITY OVERRIDE: The product photo is the SINGLE authoritative source for ' + FS.produkNama + '. Any appearance of a similar item in other reference photos (especially the outfit photo) must be completely IGNORED and replaced by the product from the product reference photo. The product photo takes absolute priority over all other photos for this specific item.';
  }

  // ── isProdukSaja: dipaksa true untuk shot "Detail Produk" (tanpa karakter) ──
  let isProdukSaja = ov.forceProdukSaja || FS.subjek==='produk' || fIsNoChar();
  let subjekDesc=isProdukSaja?'product only, no person':({'hijab':'a woman','pria':'a man'}[FS.subjek]||'a person');

  // Dipindah lebih awal (sebelumnya dihitung di bawah, setelah Product block) —
  // dibutuhkan di sini supaya fallback placement produk-saja (di bawah) bisa
  // konsisten dengan info "ada tangan di frame atau tidak", tidak kontradiksi.
  let effAngle = ov.angleOverride || FS.angleDesc || FS.angle;
  // FIX: kalau mode produk-saja TAPI angle yang dipilih adalah "dipegang tangan"
  // (ada tangan di frame), jangan bilang "no person or human visible" — itu
  // kontradiksi langsung sama instruksi tangannya sendiri, bikin AI bingung
  // dan akhirnya render tanpa tangan sama sekali.
  // FIX #2: HANYA berlaku kalau shot ini TIDAK punya placementOverride sendiri
  // (jalur generate biasa) — kalau ov sudah bawa placementOverride sendiri
  // (misal multi-shot "Detail Produk tanpa karakter" yang eksplisit MELARANG
  // tangan), jangan sampai auto-detect ini malah nabrak/kontradiksi instruksi
  // shot itu sendiri hanya karena angle dasar user kebetulan "Dipegang Tangan".
  let _povHandNC = isProdukSaja && !ov.placementOverride && !ov.forceProdukSaja && _fIsPovHandNoChar();
  let angleHasHand = (isProdukSaja && !ov.placementOverride && /\bhand\b/i.test(effAngle)) || _povHandNC;
  if(_povHandNC) subjekDesc = 'product only, no person visible except a single hand holding the product (first-person POV)';
  if(_povHandNC && !ov.angleOverride) effAngle = 'POV style (first-person perspective), as if the viewer is holding the product' + (effAngle && !/^POV style/.test(effAngle) ? ' \u2014 ' + effAngle : '');
  let produkSajaIntroText = angleHasHand
    ? 'A photorealistic product image, clean and detailed, product held by a hand entering the frame — only the hand is visible, no face or rest of the body. '
    : 'A photorealistic product-only image, clean and detailed, no person or human visible. ';

  // Product block
  let produkBlock = null;
  let hasProdukRef = FS.refs.some(r=>r.type==='produk');
  if(FS.produkMode !== 'tidak' && hasProdukRef){
    let placement = _fComputePlacement(ov);
    // FIX BUG: kalau subjek = "Produk Saja" dipakai lewat jalur generate utama
    // (bukan lewat checkbox multi-shot "Detail Produk"), holdKey/hold memang
    // sengaja tidak pernah diisi (step "Cara Tampil Produk" di-skip untuk mode
    // ini) — akibatnya _fComputePlacement() di atas selalu balik string kosong,
    // dan field "placement" di JSON produk jadi kosong walau field lain
    // (camera_framing, dst) sudah terisi. Sekarang: kalau masih kosong DAN
    // memang mode produk-saja, isi teks default yang konsisten dengan
    // angleHasHand di atas — supaya tidak kontradiksi ("no hands" vs angle
    // yang justru minta tangan masuk frame).
    if(!placement && isProdukSaja){
      placement = angleHasHand
        ? 'held by a hand entering the frame — only the hand is visible, product sharp, fully visible and prominently framed toward camera'
        : 'displayed clearly and prominently as the sole focus of the frame, no hands or person present, centered composition showing full product detail';
    }
    produkBlock = {
      name: FS.produkNama || '[product from reference photo]',
      placement: placement,
      instruction: 'This product MUST be clearly visible, sharp, and prominently displayed. Preserve its exact shape, color, size, logo, and all visual details. Do NOT alter, resize, or obscure the product at any point.'
    };
  }

  // Output quality
  let quality = {
    camera: 'Shot using a smartphone camera (not DSLR), with natural handheld feel. The image includes subtle digital noise and grain typical of a phone camera, especially in shadows and low-light areas. Slight imperfections such as minor motion blur, soft focus inconsistencies, and natural exposure shifts are present. The dynamic range is realistic (not overly HDR), with slightly clipped highlights and soft shadow details. The framing is slightly imperfect, not perfectly centered, with a subtle wide lens feel and natural perspective distortion. Overall look resembles an authentic phone photo, not a polished or studio-quality image.',
    lighting: 'Lighting is natural and imperfect, coming from a window or ambient indoor source rather than studio lights. The light falls unevenly across the subject, creating soft shadows on one side of the face and slightly brighter highlights on the other. There may be mild overexposure in small highlight areas and gentle shadow gradients across the scene. The lighting is not perfectly balanced, with slight warmth and natural color variation. Some areas of the scene may be dimmer or less illuminated, creating a cozy, lived-in atmosphere. Avoid flat lighting or perfectly even illumination. Overall lighting should feel organic, spontaneous, and human, not staged or studio-controlled.'
  };

  // ── Build natural language intro ────────────────────────────────
  // FIX: sebelumnya pakai FS.pose/FS.lokasi/FS.cahaya/FS.angle yang untuk
  // pilihan chip cuma berisi LABEL singkat (misal "Eye Level", "Dipegang
  // Tangan") — deskripsi lengkapnya (bahasa Inggris, detail) tidak pernah
  // sampai ke AI sama sekali. Sekarang pakai field *Desc yang menyimpan
  // teks lengkapnya, dengan fallback ke field lama untuk jaga-jaga.
  let effPose = ov.poseOverride || FS.poseDesc || FS.pose;
  let effKamera = ov.kameraNote || FS.kamera;
  let effLokasi = ov.lokasiOverride || FS.lokasiDesc || FS.lokasi;
  let effCahaya = ov.cahayaOverride || FS.cahayaDesc || FS.cahaya;
  let effMood = ov.moodOverride || FS.mood;
  // Foto referensi LOKASI: lokasi & pencahayaan diambil dari foto itu (step Lokasi/Pencahayaan dilewati).
  let _lokRef = realRefs.find(r => r.type === 'lokasi');
  let _lokNo = _lokRef ? realRefs.indexOf(_lokRef) + 1 : 0;
  if(_lokRef){
    effLokasi = 'the exact location shown in reference photo ' + _lokNo + ' — same architecture, props, background elements, colors, and atmosphere' + (isProdukSaja ? '' : '; the character looks naturally present in the space with correct scale and perspective');
    effCahaya = 'taken entirely from reference photo ' + _lokNo + ', with the same light direction, color temperature, softness, contrast, and shadow behavior, copied onto ' + (isProdukSaja ? 'the product' : 'the character and outfit');
  }
  // FIX: output_quality dulu SELALU menulis "foto HP, bukan studio", "hindari cahaya rata" dan menyebut "wajah" —
  // bentrok dengan Softbox/Studio rata/Dark Moody, mood Clean/Luxury/Editorial, dan mode Produk Saja (tanpa wajah).
  _fAdaptQuality(quality, effCahaya, effMood, isProdukSaja);
  if(_lokRef){
    quality.lighting = 'Follow the lighting of reference photo ' + _lokNo + ' exactly and keep it consistent across the whole frame, on the character, the outfit, and the background; do not add studio lighting or any light that contradicts the location.';
    quality.camera = String(quality.camera || '') + (isProdukSaja ? ' The product must not look cut-out or pasted into the scene.' : ' The character must not look cut-out or pasted into the scene.');
    if(isProdukSaja) quality.lighting = quality.lighting.replace('on the character, the outfit, and the background','on the product and the background');
  }

  // Tambahkan keterangan outfit random ke intro jika ada
  let outfitRandomIntro = '';
  if(generatedOutfits.length > 0 && !ov.forceProdukSaja){
    let descs = randomRefs.map(r => r.focus).filter(Boolean);
    outfitRandomIntro = 'Outfit (AI-generated, no reference photo): ' + descs.join(' | ') + '. ';
  }

  let intro = (isProdukSaja
    ? produkSajaIntroText
    : (hasProdukRef
        ? 'A photorealistic product image'+_fIntroStyle(effMood)+'. Subject: '+subjekDesc+'. '
        : 'A photorealistic lifestyle fashion image'+_fIntroStyle(effMood)+'. Subject: '+subjekDesc+'. '))
    + outfitRandomIntro
    + (produkBlock ? 'Hero product: ' + produkBlock.name + (produkBlock.placement ? ', ' + produkBlock.placement + '. ' : '. ') + produkBlock.instruction + ' ' : '')
    + 'Scene: ' + effLokasi + '. '
    + 'Lighting: ' + effCahaya + '. '
    // FIX BUG KONSISTENSI JALUR NORMAL vs IMPORT: sebelumnya baris ini tidak
    // cek apakah effPose kosong (beda dengan _fBuildImportedPromptJSON yang
    // sudah pakai guard "effPose ?" di kondisi yang sama). Kalau effPose
    // kosong tapi isProdukSaja false, hasilnya kalimat rusak
    // "...Character pose: . Camera angle: ..." nyangkut di tengah prompt.
    // Disamakan dengan jalur import supaya tidak pernah menulis pose kosong.
    + (isProdukSaja || !effPose ? '' : 'Character pose: ' + effPose + '. ')
    + (effKamera ? 'Camera framing: ' + effKamera + '. ' : '')
    + 'Camera angle: ' + effAngle + '. '
    + 'Mood & tone: ' + effMood + '.';

  // ── FULL JSON ───────────────────────────────────────────────────
  let fullJson = {
    prompt: intro,
    subject: subjekDesc,
    mood_and_tone: effMood,
    ...(refPhotos.length > 0 && realRefs.length > 0 ? {
      critical_rule: 'Read each reference photo SELECTIVELY. Extract ONLY the specified elements from each photo and ignore everything else. Every extract_only and ignore_completely directive is ABSOLUTE — do NOT blend elements across photos unless explicitly stated.'
    } : {}),
    ...(conflictRule ? {conflict_priority: conflictRule} : {}),
    ...(refPhotos.length > 0 ? {reference_photos: refPhotos} : {}),
    ...(generatedOutfits.length > 0 && !ov.forceProdukSaja ? {generated_outfit: generatedOutfits} : {}),
    ...(produkBlock ? {product: produkBlock} : {}),
    scene: {
      location: effLokasi,
      // FIX BUG KONSISTENSI JALUR NORMAL vs IMPORT: sama seperti fix intro
      // di atas — tanpa "!effPose" di sini, field "pose":"" bisa ikut
      // terkirim kosong ke JSON kalau effPose kosong padahal bukan mode
      // produk-saja. Disamakan dengan _fBuildImportedPromptJSON yang sudah
      // benar (baris scene.pose di sana pakai "isProdukSaja || !effPose").
      ...(isProdukSaja || !effPose ? {} : {pose: effPose}),
      ...(effKamera ? {camera_framing: effKamera} : {}),
      camera_angle: effAngle,
      lighting: effCahaya,
      mood_and_tone: effMood
    },
    output_quality: quality
  };

  let subjekLabel = ov.label || (FS.subjek==='hijab'?'Hijab':FS.subjek==='pria'?'Pria':'Produk');
  return {fullJson, realRefs, randomRefs, subjekLabel};
} // end _fBuildPromptJSON

// ── Notifikasi Upload — bangun & tampilkan ───────────────────────
let _fUploadNoticeList = '';

// FITUR BARU (permintaan user): tampilan "urutan foto" di sebelah tombol
// Salin JSON diganti dari teks polos jadi kotak-kotak kecil bergaya preview
// lampiran (seperti kotak thumbnail foto yang mau diupload ke Google Flow),
// tapi isinya ICON per jenis foto (bukan foto asli) + label di bawahnya,
// diikuti 1 pill kecil berisi ikon kamera + jumlah foto (×N) tanpa teks
// "Gambar" — cukup ikon dan angkanya saja.
const FTYPE_ICON_MAP={
  lokasi:'ic-pin', wajah:'ic-face', outfit:'ic-outfit', atasan:'ic-outfit', bawahan:'ic-outfit',
  aksesori:'ic-outfit', produk:'ic-box', objek:'ic-box', outfit_random:'ic-outfit'
};
// Caption singkat per jenis foto (bukan label panjang FTYPE) — biar kotaknya
// tetap ringkas & mirip gaya preview lampiran, tapi jenis fotonya masih
// jelas dibaca sekilas.
const FTYPE_SHORT_LABEL={
  lokasi:'Foto Lokasi', wajah:'Foto Karakter Sheet', outfit:'Foto Outfit', atasan:'Foto Atasan', bawahan:'Foto Bawahan',
  aksesori:'Foto Aksesori', produk:'Foto Produk', objek:'Foto Objek', outfit_random:'Foto Outfit'
};
// Tampilan "urutan foto": alur horizontal bertahap (nomor, ikon, label per foto)
// dengan garis penghubung; menyesuaikan jumlah foto, bisa digeser jika sempit.
function _fBuildOutLabelBoxesHTML(realRefs){
  if(!realRefs || !realRefs.length) return '';
  let steps = realRefs.map(function(r, i){
    let iconId = FTYPE_ICON_MAP[r.type] || 'ic-camera';
    let label = FTYPE_SHORT_LABEL[r.type] || 'Foto';
    let dot = (i < realRefs.length - 1) ? '<span class="fo-dot" style="animation-delay:'+(i*0.4)+'s"></span>' : '';
    return '<div class="fo-step">'
      + '<span class="fo-num">'+(i+1)+'</span>'
      + '<svg class="icon fo-ic"><use href="#'+iconId+'"></use></svg>'
      + '<span class="fo-lbl">'+esc(label)+'</span>'
      + dot
      + '</div>';
  }).join('');
  return '<div class="fo-title">Upload ke Google Flow sesuai urutan ini</div>'
    + '<div class="fo-sub">Jika terbalik, hasil foto akan salah.</div>'
    + '<div class="fo-flow">' + steps + '</div>';
}

function _fComputeUploadNoticeStr(realRefs, randomRefs){
  if(realRefs && realRefs.length > 0){
    return realRefs.map((r, i) => (i+1) + '. foto ' + FTYPE[r.type].label.toLowerCase()).join('  ·  ');
  }
  // FIX IMPORT: prompt yang diimpor tidak punya FS.refs/realRefs (tidak ada file
  // foto asli), tapi urutan fotonya tetap ada di FS.importRefPhotos (dari field
  // "reference_photos" JSON yang diimpor). Field .type di situ sudah berupa
  // label siap pakai (mis. "Wajah Karakter"), bukan key FTYPE — pakai apa adanya.
  if(FS.importActive && FS.importRefPhotos && FS.importRefPhotos.length > 0){
    return FS.importRefPhotos.map((r, i) => (i+1) + '. foto ' + esc(String((r && r.type) || 'referensi').toLowerCase())).join('  ·  ');
  }
  return '';
}
function fBuildUploadNotice(realRefs, randomRefs){
  _fUploadNoticeList = _fComputeUploadNoticeStr(realRefs, randomRefs);
}

function fShowUploadNotice(){
  if(!_fUploadNoticeList) return;

  // Hapus notif lama jika ada
  let old = document.getElementById('f-urutan-notif');
  if(old) old.remove();

  let el = document.createElement('div');
  el.id = 'f-urutan-notif';
  el.style.cssText = 'position:fixed;top:calc(16px + env(safe-area-inset-top,0px));left:50%;transform:translateX(-50%);z-index:9999;'
    + 'background:linear-gradient(180deg,var(--surface3),var(--surface));color:var(--text);border-radius:var(--radius-lg);'
    + 'border:1px solid rgba(var(--pulse-rgb),0.28);'
    + 'padding:16px 18px;width:calc(100% - 32px);max-width:480px;'
    + 'box-shadow:var(--shadow-lg),0 0 0 1px rgba(var(--pulse-rgb),0.08);animation:notifSlideDown 0.25s ease;';

  el.innerHTML = '<div style="display:flex;align-items:center;gap:9px;margin-bottom:8px;">'
    + '<span style="width:26px;height:26px;flex-shrink:0;border-radius:var(--radius-md);background:var(--accent-dim-bg);display:flex;align-items:center;justify-content:center;">'
    + '<svg class="icon" style="font-size:var(--fs-md);color:var(--accent-2);"><use href="#ic-warning"></use></svg>'
    + '</span>'
    + '<span style="font-size:var(--fs-sm);font-weight:600;letter-spacing:0.2px;color:var(--text);">Urutan Foto Tidak Boleh Terbalik</span>'
    + '</div>'
    + '<div style="font-size:var(--fs-xs2);margin-bottom:12px;color:var(--muted);line-height:1.65;">Upload ke Google Flow sesuai urutan ini — jika terbalik, hasil foto akan salah.</div>'
    + '<div style="font-size:var(--fs-sm);font-weight:500;margin-bottom:14px;color:var(--accent-2);font-family:\'Hanken Grotesk\',system-ui,sans-serif;letter-spacing:0.1px;background:var(--surface2);border:1px solid var(--border);border-radius:var(--radius-sm);padding:8px 10px;">' + _fUploadNoticeList + '</div>'
    + '<button onclick="var n=document.getElementById(\'f-urutan-notif\');if(n)n.remove();" '
    + 'style="width:100%;background:linear-gradient(135deg,var(--accent),var(--accent-dim));color:#171310;border:none;padding:10px;border-radius:var(--radius);'
    + 'font-size:var(--fs-sm);font-weight:600;cursor:pointer;font-family:Hanken Grotesk,sans-serif;box-shadow:0 4px 12px rgba(184,150,95,0.18);">Saya Mengerti</button>';

  document.body.appendChild(el);

  // Auto-dismiss setelah 12 detik jika tidak ditutup
  setTimeout(() => { let n=document.getElementById('f-urutan-notif'); if(n) n.remove(); }, 12000);
}

// ── Helper salin teks yang robust — coba Clipboard API, kalau gagal/tidak
// tersedia fallback ke execCommand (penting untuk beberapa browser/WebView HP) ──
function _copyTextRobust(text,onOk,onFail){
  function viaExec(){
    let ta=document.createElement('textarea');ta.value=text;
    ta.style.cssText='position:fixed;top:-9999px;left:-9999px;opacity:0;';
    document.body.appendChild(ta);ta.focus();ta.select();
    try{
      let ok=document.execCommand('copy');
      document.body.removeChild(ta);
      if(ok){if(onOk)onOk();}else{if(onFail)onFail();}
    }catch(e){
      document.body.removeChild(ta);
      if(onFail)onFail();
    }
  }
  if(navigator.clipboard&&navigator.clipboard.writeText){
    // FIX (bug kecil di _copyTextRobust): sebelumnya pakai
    // .then(onOk).catch(viaExec) — kalau ada exception DI DALAM onOk
    // sendiri, .catch itu ikut menangkapnya juga, jadi viaExec ikut jalan
    // (menyalin kedua kali) dan onOk bisa terpanggil dua kali tanpa ada
    // pesan error yang jelas. .then(onOk, viaExec) memastikan viaExec
    // cuma jadi fallback untuk writeText() yang gagal, bukan untuk error
    // di dalam onOk.
    navigator.clipboard.writeText(text).then(function(){if(onOk)onOk();},viaExec);
  }else{
    viaExec();
  }
}

// ════════════════════════════════════════════════════════════════
// KARAKTER SHEET — popup terpisah dari wizard biasa, generate 1
// kalimat prompt siap pakai untuk foto karakter multi-angle. Cuma
// 3 hal yang bisa diatur user (Karakter/Usia/Negara) — outfit,
// ekspresi, angle, & background FIXED sesuai template.
// ════════════════════════════════════════════════════════════════
let csState={gender:'wanita',usia:null,negara:'Indonesia',penampilan:'Cantik, Putih',outfit:"Setelan abaya syar'i"};
let csLastPromptText='';
// FITUR BARU (permintaan user): halaman aktif di wizard Karakter Sheet
// (1=Karakter, 2=Negara, 3=Penampilan, 4=Outfit). Dipakai csGoPage()/
// csGoBack() buat tahu harus render label "Langkah X dari 4" yang mana &
// kapan tombol back (‹) ditampilkan.
let csCurrentPage=1;
const CS_TOTAL_PAGES=4;
// Batas usia karakter (bilangan bulat). Samakan dengan atribut min/max pada
// input #cs-usia-input di HTML. Mau rentang lain? Ubah dua angka ini saja.
const CS_USIA_MIN=18, CS_USIA_MAX=70;
// Chip terakhir yang dipilih per kolom. Dipakai csRestoreChipValue(): begitu
// kolom "isi sendiri" dikosongkan lagi, csState balik ke nilai chip ini,
// bukan tertinggal huruf sisa dari ketikan yang dihapus ("T" dari "Turki").
let csChipMemo={negara:null,penampilan:null,outfit:null};
// true kalau modal dibuka dari tur Langkah 3 (pbOpenCharacterSheetFromTour).
// Di luar tur, salin prompt TIDAK boleh melempar user ke kartu tur.
let csFromTour=false;
// Nomor "generasi" modal: naik tiap modal dibuka/ditutup dan tiap klik Buat
// Prompt. Animasi 2 detik yang modalnya keburu ditutup jadi tahu dirinya
// sudah basi dan tidak memunculkan hasil prompt di layar utama.
let csGenToken=0;
// Penjaga ketukan ganda pada tombol "Salin prompt" (lihat csCopyPrompt()).
let csCopyBusy=false;

function csOpenModal(){
  document.getElementById('cs-modal').style.display='flex';
  // Selalu mulai dari "bukan dari tur"; pbOpenCharacterSheetFromTour()
  // baru menyalakan csFromTour SESUDAH fungsi ini selesai.
  csFromTour=false;
  csGenToken++;
  csCopyBusy=false;
  // Samakan chip & kolom isian dengan csState. csState ikut tersimpan di
  // draft/undo, tapi class 'sel' pada chip tidak, jadi tanpa ini layar bisa
  // menunjukkan Wanita/Indonesia padahal prompt-nya "laki-laki asal Mesir".
  csSyncUiFromState();
  // Setiap modal dibuka (baik dari luar tur maupun dari tur), wizard SELALU
  // mulai lagi dari halaman 1 (Karakter) — bukan nyangkut di halaman
  // terakhir yang sempat dibuka sebelumnya.
  csGoPage(1);
  // Pastikan tombol "Tutup" selalu kelihatan lagi di pemakaian normal
  // (di luar tur) — yang menyembunyikannya cuma alur tur Langkah 3
  // lewat pbOpenCharacterSheetFromTour(), lihat komentar di sana.
  let closeBtn=document.getElementById('cs-close-btn');
  if(closeBtn) closeBtn.style.display='';
}
function csCloseModal(){
  document.getElementById('cs-modal').style.display='none';
  // Batalkan animasi "Buat Prompt" yang mungkin masih berjalan.
  csGenToken++;
}
// Tampilan modal <- csState (lihat komentar di csOpenModal()). Urutannya
// penting: semua 'sel' chip dilepas dulu karena csRelabelPenampilan() &
// csRelabelOutfit() MENIMPA csState kalau menemukan chip ber-'sel', padahal
// nilai yang dipulihkan itulah yang benar.
function csSyncUiFromState(){
  let isLaki=csState.gender==='laki-laki';
  let gW=document.getElementById('cs-gender-wanita');
  let gL=document.getElementById('cs-gender-lakilaki');
  if(gW)gW.classList.toggle('sel',!isLaki);
  if(gL)gL.classList.toggle('sel',isLaki);
  csGenderUi();
  ['negara','penampilan','outfit'].forEach(function(f){
    document.querySelectorAll('#cs-'+f+'-chips .chip').forEach(function(c){c.classList.remove('sel');});
  });
  csRelabelPenampilan();
  csRelabelOutfit();
  ['negara','penampilan','outfit'].forEach(function(f){
    let inp=document.getElementById('cs-'+f+'-custom');
    let cur=csState[f];
    if(!cur){ if(inp)inp.value=''; csRestoreChipValue(f); return; }
    let hit=null;
    document.querySelectorAll('#cs-'+f+'-chips .chip').forEach(function(c){
      if(c.textContent.trim()===cur)hit=c;
    });
    if(hit){
      hit.classList.add('sel');
      csChipMemo[f]=hit;
      if(inp)inp.value='';
    } else if(inp){
      inp.value=cur;
    }
  });
  let uBox=document.getElementById('cs-usia-box');
  let uInp=document.getElementById('cs-usia-input');
  let uBtn=document.getElementById('cs-usia-toggle');
  if(uBox&&uInp&&uBtn&&csState.usia!=null&&csState.usia!==''){
    uInp.value=csState.usia;
    csUsiaUi(true);
  }
}
// Lepas 'sel' dari semua chip satu kolom, tapi ingat dulu chip mana yang
// sedang terpilih (untuk csRestoreChipValue()).
function csDeselectChips(f){
  let cur=document.querySelector('#cs-'+f+'-chips .chip.sel');
  if(cur)csChipMemo[f]=cur;
  document.querySelectorAll('#cs-'+f+'-chips .chip').forEach(function(c){c.classList.remove('sel');});
}
// Kolom "isi sendiri" dikosongkan: csState balik ke chip terakhir yang dipilih
// (atau chip pertama kalau belum pernah ada) dan chip itu menyala lagi.
function csRestoreChipValue(f){
  let chips=Array.prototype.slice.call(document.querySelectorAll('#cs-'+f+'-chips .chip'));
  if(!chips.length)return;
  let el=(csChipMemo[f]&&chips.indexOf(csChipMemo[f])>=0)?csChipMemo[f]:chips[0];
  csState[f]=el.textContent.trim();
  chips.forEach(function(c){c.classList.toggle('sel',c===el);});
}
// Usia yang boleh masuk prompt: bilangan bulat CS_USIA_MIN..CS_USIA_MAX.
// Atribut min/max di HTML TIDAK berlaku di sini (input bukan bagian <form>),
// jadi 0, -5, 999, 2.5, "1e2" dst harus dicegat manual. Kotak usia
// tersembunyi atau kosong = tanpa usia (sah).
function csReadUsia(){
  let box=document.getElementById('cs-usia-box');
  let inp=document.getElementById('cs-usia-input');
  if(!box||!inp||box.classList.contains('hidden'))return {ok:true,val:null};
  let raw=(inp.value||'').trim();
  if(!raw)return (inp.validity&&inp.validity.badInput)?{ok:false}:{ok:true,val:null};
  if(!/^\d+$/.test(raw))return {ok:false};
  let n=parseInt(raw,10);
  if(n<CS_USIA_MIN||n>CS_USIA_MAX)return {ok:false};
  return {ok:true,val:n};
}
// Usia tidak sah: balik ke halaman 1 (tempat kolom usia), fokuskan, kasih tahu.
function csUsiaInvalid(){
  csGoPage(1);
  let inp=document.getElementById('cs-usia-input');
  if(inp){inp.focus();try{inp.select();}catch(e){}}
  showToast('Usia harus antara '+CS_USIA_MIN+' dan '+CS_USIA_MAX+' tahun','error');
}
// ── FITUR BARU (permintaan user): navigasi wizard satu-halaman-per-langkah.
// Sembunyikan semua .cs-page lalu tampilkan cs-page-<n> saja, update label
// "Langkah X dari 4", tombol back (cs-back-btn) cuma kelihatan mulai
// halaman ke-2, dan begitu masuk halaman 4 (Outfit) tombol "Buat Prompt"
// otomatis dikasih denyutan (.cs-pulse-btn) supaya user sadar itu yang
// harus ditekan. Konten modal juga di-scroll balik ke atas tiap pindah
// halaman biar user selalu mulai lihat dari judul field, bukan nyangkut
// di posisi scroll halaman sebelumnya. ─────────────────────────────────
function csGoPage(n){
  document.querySelectorAll('.cs-page').forEach(function(p){p.classList.add('hidden');});
  let target=document.getElementById('cs-page-'+n);
  if(target) target.classList.remove('hidden');
  csCurrentPage=n;
  let backBtn=document.getElementById('cs-back-btn');
  if(backBtn) backBtn.style.display=(n>1)?'':'none';
  let lbl=document.getElementById('cs-page-label');
  if(lbl){ lbl.textContent='Langkah '+n+' dari '+CS_TOTAL_PAGES; lbl.style.display='none'; }
  let genBtn=document.getElementById('cs-generate-btn');
  if(genBtn && n===4) genBtn.classList.add('cs-pulse-btn');
  let scrollBox=document.getElementById('cs-modal');
  if(scrollBox) scrollBox.scrollTop=0;
}
function csGoBack(){
  if(csCurrentPage>1) csGoPage(csCurrentPage-1);
}
function csPickGender(val,el){
  csState.gender=val;
  document.querySelectorAll('#cs-gender-wanita,#cs-gender-lakilaki').forEach(c=>c.classList.remove('sel'));
  el.classList.add('sel');
  csGenderUi();
  csRelabelPenampilan();
  csRelabelOutfit();
}
// Ganti label chip Penampilan sesuai gender ("Cantik" utk wanita, "Ganteng"
// utk laki-laki). Kalau chip yang sedang aktif (sel) adalah salah satu dari
// keduanya, csState.penampilan ikut disegarkan biar isi prompt konsisten
// sama label baru yang kelihatan di layar.
function csRelabelPenampilan(){
  let isLaki=csState.gender==='laki-laki';
  document.querySelectorAll('#cs-penampilan-chips .chip').forEach(c=>{
    let label=isLaki?c.dataset.m:c.dataset.f;
    if(!label)return;
    c.textContent=label;
    if(c.classList.contains('sel'))csState.penampilan=label;
  });
}
// ── Outfit — field BARU (permintaan user), sama pola dengan Penampilan di
// atas: cuma 1 chip yang tampil sesuai gender ("Setelan abaya syar'i" utk
// wanita, "Outfit casual" utk laki-laki) + isi sendiri. ─────────────────
function csRelabelOutfit(){
  let isLaki=csState.gender==='laki-laki';
  document.querySelectorAll('#cs-outfit-chips .chip').forEach(c=>{
    let label=isLaki?c.dataset.m:c.dataset.f;
    if(!label)return;
    c.textContent=label;
    if(c.classList.contains('sel'))csState.outfit=label;
  });
  // Placeholder "Atau isi sendiri" juga ikut disesuaikan gender — contoh
  // "gamis" gak relevan buat laki-laki, jadi diganti contoh outfit cowok.
  let customInp=document.getElementById('cs-outfit-custom');
  if(customInp){
    let ph=isLaki?customInp.dataset.phM:customInp.dataset.phF;
    if(ph)customInp.placeholder=ph;
  }
}
// Tampilan panel (desain "Preview B"): geser indikator Wanita/Laki-laki &
// sinkronkan aria-pressed. Dipanggil csPickGender() & csSyncUiFromState().
function csGenderUi(){
  let isLaki=csState.gender==='laki-laki';
  let seg=document.getElementById('cs-seg');
  if(seg)seg.dataset.v=isLaki?'laki':'wanita';
  [['cs-gender-wanita',!isLaki],['cs-gender-lakilaki',isLaki]].forEach(function(p){
    let e=document.getElementById(p[0]);
    if(e)e.setAttribute('aria-pressed',p[1]?'true':'false');
  });
}
// Baris "Atur usia": saklar (mati) <-> stepper − 25 + (nyala), seperti di
// preview. Saat nyala saklar disembunyikan, jadi tombol "Hapus usia" yang
// mematikannya lagi (memanggil csToggleUsia() juga).
function csUsiaUi(on){
  let box=document.getElementById('cs-usia-box');
  let sw=document.getElementById('cs-usia-toggle');
  let off=document.getElementById('cs-usia-off');
  let hint=document.getElementById('cs-usia-hint');
  if(box)box.classList.toggle('hidden',!on);
  if(sw){sw.classList.toggle('hidden',on);sw.setAttribute('aria-checked',on?'true':'false');}
  if(off)off.classList.toggle('hidden',!on);
  if(hint)hint.textContent=on?('Rentang '+CS_USIA_MIN+' sampai '+CS_USIA_MAX+' tahun'):'Opsional, kosongkan kalau bebas';
}
function csToggleUsia(){
  let box=document.getElementById('cs-usia-box');
  let inp=document.getElementById('cs-usia-input');
  if(!box.classList.contains('hidden')){
    inp.value='';
    csState.usia=null;
    csUsiaUi(false);
  } else {
    if(!inp.value)inp.value=25;
    csUsiaUi(true);
  }
}
// Tombol − / + di stepper usia, dibatasi CS_USIA_MIN..CS_USIA_MAX.
function csStepUsia(d){
  let inp=document.getElementById('cs-usia-input');
  let cur=parseInt(inp.value,10);
  if(isNaN(cur))cur=25;
  inp.value=Math.max(CS_USIA_MIN,Math.min(CS_USIA_MAX,cur+d));
}
function csPickNegara(val,el){
  csState.negara=val;
  document.getElementById('cs-negara-custom').value='';
  document.querySelectorAll('#cs-negara-chips .chip').forEach(c=>c.classList.remove('sel'));
  el.classList.add('sel');
  csChipMemo.negara=el;
}
// Begitu user tap ke kolom "isi sendiri", langsung lepas warna kuning dari
// chip Negara — sebelum sempat ngetik apa pun — supaya gak kelihatan kayak
// dua-duanya (chip + isian sendiri) bakal dipakai bareng di prompt.
function csNegaraCustomFocus(){
  csDeselectChips('negara');
}
// Kalau user keluar dari kolom tanpa ngetik apa-apa, kembalikan warna
// kuning ke chip yang sesuai csState.negara (biar gak kelihatan kosong).
function csNegaraCustomBlur(){
  let v=(document.getElementById('cs-negara-custom').value||'').trim();
  if(v)return;
  document.querySelectorAll('#cs-negara-chips .chip').forEach(c=>{
    if(c.textContent.trim()===csState.negara)c.classList.add('sel');
  });
}
// Dipicu langsung tiap kali user mengetik (oninput) — bukan lewat tombol
// "Pakai" lagi, supaya isian custom langsung dianggap "berlaku" begitu
// diketik, dan chip Indonesia/Mesir/Arab Saudi yang lagi aktif langsung
// kehilangan warna kuningnya (menjawab keluhan: kelihatan seolah masih
// pakai Indonesia padahal user sudah mau isi sendiri). Kalau field
// dikosongkan lagi, nilai negara BALIK ke chip yang terakhir dipilih
// (csRestoreChipValue) — bukan tertinggal huruf sisa dari ketikan yang
// dihapus, dan prompt tetap tidak pernah kosong.
function csNegaraCustomInput(){
  let v=(document.getElementById('cs-negara-custom').value||'').trim();
  if(!v){csRestoreChipValue('negara');return;}
  csState.negara=v;
  csDeselectChips('negara');
}
// ── Penampilan — field baru, sama pola dengan Negara di atas: pilih chip
// ATAU isi sendiri (live lewat oninput, tanpa tombol "Pakai"). Nilainya
// dipakai gantiin kata sifat "cantik/tampan" yang dulu di-hardcode
// berdasarkan gender saja di csGeneratePrompt(). ──────────────────────
function csPickPenampilan(el){
  csState.penampilan=el.textContent.trim();
  document.getElementById('cs-penampilan-custom').value='';
  document.querySelectorAll('#cs-penampilan-chips .chip').forEach(c=>c.classList.remove('sel'));
  el.classList.add('sel');
  csChipMemo.penampilan=el;
}
// Sama seperti Negara: lepas warna kuning chip Penampilan begitu kolom
// "isi sendiri" difokus, dan kembalikan kalau ditinggal kosong.
function csPenampilanCustomFocus(){
  csDeselectChips('penampilan');
}
function csPenampilanCustomBlur(){
  let v=(document.getElementById('cs-penampilan-custom').value||'').trim();
  if(v)return;
  document.querySelectorAll('#cs-penampilan-chips .chip').forEach(c=>{
    if(c.textContent.trim()===csState.penampilan)c.classList.add('sel');
  });
}
function csPenampilanCustomInput(){
  let v=(document.getElementById('cs-penampilan-custom').value||'').trim();
  if(!v){csRestoreChipValue('penampilan');return;}
  csState.penampilan=v;
  csDeselectChips('penampilan');
}
// ── Outfit — field BARU (permintaan user): pola sama dengan Negara/
// Penampilan (pilih chip ATAU isi sendiri, live lewat oninput, tanpa
// tombol "Pakai"). Bedanya cuma ada 1 chip yang tampil sesuai gender
// (lihat csRelabelOutfit()). Nilainya dipakai gantiin outfit yang dulu
// di-hardcode berdasarkan gender saja di csGeneratePrompt(). ──────────
function csPickOutfit(el){
  csState.outfit=el.textContent.trim();
  document.getElementById('cs-outfit-custom').value='';
  document.querySelectorAll('#cs-outfit-chips .chip').forEach(c=>c.classList.remove('sel'));
  el.classList.add('sel');
  csChipMemo.outfit=el;
}
function csOutfitCustomFocus(){
  csDeselectChips('outfit');
}
function csOutfitCustomBlur(){
  let v=(document.getElementById('cs-outfit-custom').value||'').trim();
  if(v)return;
  document.querySelectorAll('#cs-outfit-chips .chip').forEach(c=>{
    if(c.textContent.trim()===csState.outfit)c.classList.add('sel');
  });
}
function csOutfitCustomInput(){
  let v=(document.getElementById('cs-outfit-custom').value||'').trim();
  if(!v){csRestoreChipValue('outfit');return;}
  csState.outfit=v;
  csDeselectChips('outfit');
}
// ── Klik "Buat Prompt" — tombol diganti sementara jadi animasi logo "P"
// (sama persis dengan loading Generate Prompt Foto di f-gen-btn: pecah
// dulu lalu nyatu di ~650ms, total 2 detik) baru hasil promptnya
// ditampilkan — supaya jeda generate di sini terasa konsisten sebagai
// bagian dari branding aplikasi, bukan cuma teks yang muncul instan.
// FITUR BARU (permintaan user): logo dibuat lebih besar supaya "terlihat
// jelas" (48px, sebelumnya 40px bawaan .gen-logo-box) dan label teks
// "Membuat Prompt..." DIHAPUS selama animasi ini berjalan — logo P sendiri
// yang jadi fokus, tanpa teks apa pun di bawahnya. Denyutan .cs-pulse-btn
// juga dilepas begitu tombol ditekan (biar tidak "berdenyut" bareng
// animasi logo), dan dipasang lagi tiap kali user balik ke halaman Outfit
// lewat csGoPage(). ─────────────────────────────────────────────────
function csGeneratePrompt(){
  // Usia dicek DULU sebelum animasi 2 detik jalan — jangan bikin user
  // menunggu dulu baru ditolak.
  if(!csReadUsia().ok){csUsiaInvalid();return;}
  let myGen=++csGenToken;
  let genBtn=document.getElementById('cs-generate-btn');
  let genBtnOrigHTML=genBtn?genBtn.innerHTML:'';
  if(genBtn){
    genBtn.classList.remove('cs-pulse-btn');
    genBtn.disabled=true;
    genBtn.classList.add('btn-loading');
    genBtn.innerHTML='<div class="gen-logo-wrap" id="cs-gen-logo-wrap" style="padding:4px 0;">'
      +'<div class="gen-logo-box" style="width:48px;height:48px;">'
        +'<svg class="gen-logo-svg" style="width:38px;height:38px;" viewBox="0 0 642 635" xmlns="http://www.w3.org/2000/svg">'
          +'<defs><linearGradient id="csGenPGrad" x1="0" y1="0" x2="1" y2="1"><stop offset="0%" stop-color="#F0D9A0"/><stop offset="100%" stop-color="#B8965F"/></linearGradient></defs>'
          +'<path class="p-layer p-layer-back" pathLength="1" fill="url(#csGenPGrad)" d="M146,92 L162,109 L179,119 L194,124 L206,126 L346,127 L373,134 L395,146 L386,133 L365,114 L343,102 L318,94 L306,92 Z M349,92 L361,96 L383,109 L401,126 L407,134 L417,154 L420,168 L431,184 L439,201 L444,219 L445,231 L481,231 L479,213 L470,183 L460,163 L443,140 L426,124 L402,108 L381,99 Z M253,195 L267,188 L293,183 L335,183 L345,185 L362,193 L375,205 L382,216 L387,229 L396,208 L399,184 L398,177 L379,162 L355,152 L331,149 L312,153 L285,166 L271,176 Z M291,150 L271,154 L251,161 L237,168 L216,182 L192,207 L182,223 L174,243 L169,271 L169,553 L203,534 L203,268 L208,239 L217,216 L233,192 L261,166 L277,156 Z M481,253 L445,253 L441,277 L435,293 L419,317 L403,333 L387,344 L370,352 L345,358 L279,359 L279,394 L325,394 L364,390 L391,381 L419,365 L447,339 L465,312 L477,281 Z"/>'
          +'<path class="p-layer p-layer-front" pathLength="1" fill="url(#csGenPGrad)" d="M415,201 L407,228 L397,245 L386,256 L383,267 L377,277 L360,293 L339,301 L259,302 L258,210 L243,224 L236,234 L227,254 L224,271 L224,519 L233,513 L249,497 L258,485 L258,337 L345,335 L364,330 L378,323 L393,312 L402,303 L413,287 L418,276 L423,257 L423,227 Z"/>'
        +'</svg>'
      +'</div>'
    +'</div>';
    void genBtn.offsetWidth;
    setTimeout(function(){
      let w=document.getElementById('cs-gen-logo-wrap');
      if(w) w.classList.add('merged');
    },650);
  }
  setTimeout(function(){
    // Modal ditutup (atau dibuka ulang) selama animasi: jangan munculkan
    // hasil prompt di layar utama. Tombol tetap dipulihkan seperti biasa.
    if(myGen===csGenToken) _csDoGeneratePrompt();
    if(genBtn){genBtn.disabled=false;genBtn.classList.remove('btn-loading');genBtn.innerHTML=genBtnOrigHTML;}
  },2000);
}
function _csDoGeneratePrompt(){
  // Baca usia langsung dari input (jaga-jaga kalau user isi tanpa toggle ke
  // off dulu) dan VALIDASI: bilangan bulat CS_USIA_MIN..CS_USIA_MAX, kalau
  // tidak prompt tidak dibuat. csGeneratePrompt() sudah mencegat lebih awal;
  // ini jaring pengaman kalau fungsi ini dipanggil dari tempat lain.
  let usia=csReadUsia();
  if(!usia.ok){csUsiaInvalid();return;}
  csState.usia=usia.val;

  // Prompt karakter sheet dibuat dalam BAHASA INGGRIS. Pilihan chip (gender, negara, penampilan,
  // outfit) berlabel Indonesia, jadi diterjemahkan lewat peta di bawah. Isian "isi sendiri" yang
  // tidak ada di peta dipakai apa adanya (sesuai ketikan user).
  let _csEn=function(map,val,fallback){
    let k=String(val||'').trim().toLowerCase();
    return Object.prototype.hasOwnProperty.call(map,k)?map[k]:(String(val||'').trim()||fallback);
  };
  let isLaki=csState.gender==='laki-laki';
  let genderEn=isLaki?'man':'woman';
  let negaraEn=_csEn({'indonesia':'Indonesia','mesir':'Egypt','arab saudi':'Saudi Arabia'},csState.negara,'Indonesia');
  let penampilanEn=_csEn({
    'cantik, putih':'beautiful, fair-skinned','ganteng, putih':'handsome, fair-skinned',
    'cantik, sawo matang':'beautiful, tan-skinned','ganteng, sawo matang':'handsome, tan-skinned',
    'biasa aja':'average-looking','jelek':'plain, unattractive'
  },csState.penampilan,isLaki?'handsome, fair-skinned':'beautiful, fair-skinned').toLowerCase();
  let outfitEn=_csEn({
    "setelan abaya syar'i":"a modest syar'i abaya set",'outfit casual':'a casual outfit'
  },csState.outfit||(isLaki?'outfit casual':"setelan abaya syar'i"),'a casual outfit');
  let usiaClause=csState.usia?('aged '+csState.usia+' '):'';
  let text='Create a complete multi-angle character sheet photo with various expressions and several angles: front, side, low angle, high angle, and eye level. The character is a '
    +genderEn+' '+usiaClause+'with '+(/^[aeiou]/i.test(penampilanEn)?'an ':'a ')+penampilanEn+' appearance, from '+negaraEn
    +', wearing '+outfitEn+', on a clean white background. Make sure the character is a realistic human, not an animated image.';

  csLastPromptText=text;
  csShowResultNotif(text);
}
// Notifikasi tengah layar berisi Hasil Prompt + tombol Salin, muncul di
// ATAS modal Karakter Sheet (#cs-modal tetap kebuka di belakangnya) begitu
// user klik "Buat Prompt". Ada tombol kecil "Buat ulang" — kalau user mau
// ganti-ganti pilihan dulu sebelum salin, tinggal tekan itu buat nutup
// notifikasi ini aja (modal Karakter Sheet di belakang tetap ada & masih

// bisa diedit, tinggal klik "Buat Prompt" lagi).
function csShowResultNotif(text){
  let old=document.getElementById('cs-result-notif');
  if(old)old.remove();
  csCopyBusy=false; // hasil baru = tombol Salin boleh dipakai lagi
  let overlay=document.createElement('div');
  overlay.className='confirm-overlay cs-result-page';
  overlay.id='cs-result-notif';
  overlay.style.zIndex='9999';
  let box=document.createElement('div');
  box.className='confirm-box';
  box.style.cssText='max-width:440px;text-align:left;';
  let label=document.createElement('label');
  label.className='inplabel';
  label.style.cssText='margin-top:0;';
  label.textContent='Hasil Prompt';
  let textBox=document.createElement('div');
  textBox.id='cs-result-text';
  textBox.style.cssText='background:var(--surface2);border:1px solid var(--border);border-radius:var(--radius-sm);padding:12px 14px;font-size:var(--fs-xs);color:var(--text);line-height:1.65;white-space:pre-wrap;margin-bottom:12px;max-height:55vh;overflow-y:auto;-webkit-user-select:text;user-select:text;-webkit-touch-callout:default;';
  // Teks hasil WAJIB bisa dipilih/ditahan: aturan global body *{user-select:none}
  // membuatnya tak bisa dipilih, padahal itu satu-satunya jalan salin manual
  // kalau clipboard diblokir (WebView TikTok/Instagram).
  textBox.textContent=text;
  let copyBtn=document.createElement('button');
  copyBtn.id='cs-copy-btn';
  copyBtn.className='cs-pulse-btn';
  copyBtn.textContent='Salin prompt';
  // FITUR BARU (permintaan user): tombol Salin dikasih denyutan
  // (.cs-pulse-btn, dilepas otomatis begitu ditekan — lihat csCopyPrompt())
  // dan latar kuningnya dibikin TIDAK selebar penuh lagi (beda dari
  // sebelumnya width:100%) — cukup sepanjang teksnya, ditengah, biar lebih
  // enak diliat. UPDATE (permintaan user): tombol diperkecil sedikit
  // (padding/min-width/font) dan labelnya jadi "Salin prompt".
  copyBtn.style.cssText="width:auto;min-width:118px;max-width:100%;margin:0 auto;display:block;background:var(--accent);color:var(--bg);border:none;padding:8px 18px;border-radius:var(--radius-md);font-size:var(--fs-xs2);font-weight:600;cursor:pointer;font-family:'Hanken Grotesk',sans-serif;text-align:center;";
  copyBtn.onclick=csCopyPrompt;
  let redoBtn=document.createElement('button');
  redoBtn.textContent='Buat ulang';
  redoBtn.style.cssText="display:block;width:100%;background:none;border:none;color:var(--muted);font-size:var(--fs-xs2);cursor:pointer;text-decoration:underline;padding:10px 0 0;text-align:center;font-family:'Hanken Grotesk',sans-serif;";
  // FITUR BARU (permintaan user): "Buat ulang" sekarang beneran mengulang
  // proses PEMBUATAN dari awal (halaman 1 — Karakter/jenis kelamin), bukan
  // cuma menutup notifikasi hasil prompt & diam di halaman Outfit seperti
  // sebelumnya. Modal Karakter Sheet di belakang TETAP terbuka.
  redoBtn.onclick=function(){overlay.remove();csGoPage(1);};
  box.appendChild(label);box.appendChild(textBox);box.appendChild(copyBtn);box.appendChild(redoBtn);
  overlay.appendChild(box);
  document.body.appendChild(overlay);
}
// Notifikasi tengah layar sesudah user salin prompt Karakter Sheet — beda
// dari showConfirm() (judulnya selalu "Yakin?" + tombol Batal/Ya) karena
// ini murni info sepihak, cuma butuh 1 tombol "Mengerti". Dipakai warna
// aksen emas (bukan merah seperti .confirm-ok) karena ini bukan aksi
// destruktif. ───────────────────────────────────────────────────────
function csShowSavedNotif(onDone){
  // Jaga-jaga dobel: kalau dialog ini sudah tampil, jangan bikin yang kedua.
  if(document.getElementById('cs-saved-notif'))return;
  let overlay=document.createElement('div');
  overlay.id='cs-saved-notif';
  overlay.className='confirm-overlay pb-tour-notif';
  let box=document.createElement('div');box.className='confirm-box';
  let p=document.createElement('p');
  p.style.cssText='color:var(--text);font-size:var(--fs-sm);line-height:1.65;margin-bottom:16px;';
  p.textContent='yang kamu salin namanya "prompt". Itu adalah kunci untuk membuat foto karakter sheet.';
  let okBtn=document.createElement('button');
  okBtn.textContent='Mengerti';
  okBtn.style.cssText="width:100%;background:var(--accent);color:var(--bg);border:none;padding:11px;border-radius:var(--radius-md);font-size:var(--fs-sm);font-weight:600;cursor:pointer;font-family:'Hanken Grotesk',sans-serif;";
  box.appendChild(p);box.appendChild(okBtn);
  overlay.appendChild(box);
  document.body.appendChild(overlay);
  okBtn.onclick=function(){overlay.remove();if(onDone)onDone();};
}
function csCopyPrompt(){
  let btn=document.getElementById('cs-copy-btn');
  let text=csLastPromptText||'';
  if(!text){showToast('Buat prompt-nya dulu ya','error');return;}
  // Ketukan kedua selagi proses salin masih jalan DIABAIKAN. Tanpa ini tiap
  // ketukan memasang timer 600ms sendiri sehingga dialog "Mengerti" muncul dobel.
  if(csCopyBusy)return;
  csCopyBusy=true;
  if(btn)btn.disabled=true;
  // Dibaca sekarang: csFromTour dinyalakan pbOpenCharacterSheetFromTour() dan
  // di-nol-kan tiap csOpenModal(). Dialog "Mengerti" tetap tampil di luar tur,
  // tapi HANYA di dalam tur user dibawa balik ke Langkah 3 (pbBackToStep3).
  // Dulu selalu dipanggil, jadi user yang memakai tombol Karakter Sheet biasa
  // tiba-tiba dilempar ke kartu tur "Install Google Flow".
  let dariTur=csFromTour;
  // Lanjutan sesudah prompt tersalin. Dipakai salin otomatis yang sukses DAN
  // tombol "Sudah kusalin manual" (jalan keluar kalau clipboard diblokir).
  // Prompt sudah tersalin — tutup notifikasi hasil prompt + modal Karakter
  // Sheet, kasih tahu lewat notifikasi tengah bahwa yang disalin itu "prompt"
  // dan bakal dipakai di langkah berikutnya, lalu begitu "Mengerti" ditekan
  // baru (kalau dari tur) tur BALIK ke Langkah 3 (buka butir no.1: install
  // Google Flow) — bukan langsung lompat ke Langkah 4.
  function lanjut(delay){
    setTimeout(function(){
      let notif=document.getElementById('cs-result-notif');
      if(notif)notif.remove();
      csCloseModal();
      csShowSavedNotif(function(){ if(dariTur) pbBackToStep3(); });
    },delay);
  }
  function onOk(){
    if(btn){
      btn.classList.remove('cs-pulse-btn');
      btn.textContent='Tersalin!';
      setTimeout(()=>{btn.textContent='Salin prompt';},2000);
    }
    lanjut(600);
  }
  // Salin otomatis gagal total: kunci dibuka lagi (boleh coba lagi) dan user
  // ditawari salin manual. Tanpa ini user di dalam tur BUNTU: tombol "Tutup"
  // modal sengaja disembunyikan di tur, dan toast error dulu tertutup hasil prompt.
  function onGagal(){
    csCopyBusy=false;
    if(btn)btn.disabled=false;
    showToast('Gagal salin otomatis','error');
    csShowManualCopy(function(){ csCopyBusy=true; lanjut(0); });
  }
  function onFail(){
    let ta=document.createElement('textarea');ta.value=text;
    ta.style.cssText='position:fixed;top:-9999px;left:-9999px;opacity:0;';
    document.body.appendChild(ta);ta.focus();ta.select();
    let ok=false;
    try{ok=document.execCommand('copy');}catch(e){ok=false;}
    document.body.removeChild(ta);
    if(ok)onOk();else onGagal();
  }
  if(navigator.clipboard&&navigator.clipboard.writeText){
    try{navigator.clipboard.writeText(text).then(onOk,onFail);}catch(e){onFail();}
  } else {
    onFail();
  }
}
// Pilih (blok) seluruh teks hasil prompt supaya bisa langsung disalin lewat
// menu tahan-lalu-"Salin" milik HP.
function csSelectResultText(){
  let el=document.getElementById('cs-result-text');
  if(!el)return;
  try{
    let r=document.createRange();r.selectNodeContents(el);
    let sel=window.getSelection();sel.removeAllRanges();sel.addRange(r);
  }catch(e){}
}
// Jalan keluar kalau salin otomatis gagal (mis. WebView TikTok/Instagram yang
// memblokir clipboard): teks hasil prompt dipilih otomatis, lalu tombol "Sudah
// kusalin manual" meneruskan alur yang sama seperti salin sukses (termasuk
// lanjut tur).
function csShowManualCopy(onDone){
  csSelectResultText();
  if(document.getElementById('cs-manual-copy'))return;
  let box=document.querySelector('#cs-result-notif .confirm-box');
  if(!box)return;
  let wrap=document.createElement('div');
  wrap.id='cs-manual-copy';
  wrap.style.cssText='margin-top:14px;text-align:center;';
  let hint=document.createElement('p');
  hint.style.cssText='color:var(--muted);font-size:var(--fs-xs2);line-height:1.55;margin:0 0 8px;';
  hint.textContent='Salin otomatis gagal. Tahan teks prompt di atas, pilih "Salin", lalu ketuk tombol di bawah ini.';
  let doneBtn=document.createElement('button');
  doneBtn.type='button';
  doneBtn.textContent='Sudah kusalin manual';
  doneBtn.style.cssText="width:auto;min-width:118px;max-width:100%;margin:0 auto;display:block;background:var(--surface2);color:var(--accent);border:1px solid var(--border-hi);padding:8px 18px;border-radius:var(--radius-md);font-size:var(--fs-xs2);font-weight:600;cursor:pointer;font-family:'Hanken Grotesk',sans-serif;text-align:center;";
  doneBtn.onclick=function(){doneBtn.disabled=true;onDone();};
  wrap.appendChild(hint);wrap.appendChild(doneBtn);
  box.insertBefore(wrap,box.lastChild); // sebelum link "Buat ulang"
}

function fCopy(){
  let btn=document.getElementById('f-copy-btn');
  let el=document.getElementById('f-prompt-full');
  let text=(el.textContent||el.innerText||'').trim();
  if(!text){showToast('Belum ada prompt untuk disalin!','error');return;}
  function onOk(){
    btn.innerHTML='Tersalin!';btn.classList.add('copied');
    setTimeout(()=>{btn.innerHTML='Salin Prompt';btn.classList.remove('copied');},2000);
    let doneLabel=document.getElementById('f-copy-done');
    if(doneLabel)doneLabel.classList.remove('hidden');
  }
  function onFail(){
    let ta=document.createElement('textarea');ta.value=text;
    ta.style.cssText='position:fixed;top:-9999px;left:-9999px;opacity:0;';
    document.body.appendChild(ta);ta.focus();ta.select();
    try{let ok=document.execCommand('copy');if(ok)onOk();else showToast('Gagal salin — coba select manual','error');}catch(e){showToast('Gagal salin — coba select manual','error');}
    document.body.removeChild(ta);
  }
  if(navigator.clipboard){
    navigator.clipboard.writeText(text).then(onOk).catch(onFail);
  } else {
    onFail();
  }
}

function fReset(){
  // FIX A13: Tawarkan opsi salin prompt terakhir sebelum reset, agar user tidak kehilangan hasil
  let hasOutput=(document.getElementById('f-json-output')?.style.display!=='none')||(document.getElementById('f-multi-output')?.style.display==='flex');
  let confirmMsg='Semua data foto akan dihapus dan kamu mulai dari awal.';
  if(hasOutput){confirmMsg='Semua data foto akan dihapus dan kamu mulai dari awal.<br><span style="font-size:var(--fs-xs2);color:var(--accent);">Tip: Salin prompt dulu sebelum reset jika masih dibutuhkan.</span>';}
  showConfirm(confirmMsg,fResetNow);
}
// Inti reset wizard Foto TANPA dialog konfirmasi — dipanggil fReset() (setelah
// user konfirmasi) dan pbReplayTour() (tur ulang butuh wizard yang bersih).
function fResetNow(){
  (function(){
    fResetFrom(0);
    FS.shotOverrides={};
    let mo=document.getElementById('f-multi-output');if(mo){mo.style.display='none';mo.innerHTML='';}
    let ph=document.getElementById('f-preview-placeholder');if(ph)ph.style.display='';
    let fcd=document.getElementById('f-copy-done');if(fcd)fcd.classList.add('hidden');

    // Bersihkan state & UI import prompt lama juga
    FS.importActive=false;FS.importRefPhotos=null;FS.importCriticalRule='';FS.importConflictRule='';
    FS.importGeneratedOutfit=null;FS.importProductBlock=null;FS.importOutputQuality=null;
    FS.importStyleReference=null;FS.importSubject='';FS.importIsProdukSaja=false;FS.importProdukNoPhoto=false;FS.importSceneSig='';
    let importTa=document.getElementById('f-import-textarea');if(importTa)importTa.value='';
    let importStatus=document.getElementById('f-import-status');if(importStatus)importStatus.classList.add('hidden');
    let importErr=document.getElementById('f-import-error');if(importErr)importErr.classList.add('hidden');
    let importArea=document.getElementById('f-import-area');if(importArea){importArea.classList.add('hidden');importArea.classList.remove('ft-imported');}

    // Reset progress bar ke tampilan awal (sebelum user pilih subjek)
    let fill=document.getElementById('f-progress-fill');if(fill)fill.style.width='0%';
    let label=document.getElementById('f-progress-label');
    if(label)label.innerHTML='Step <span>1</span> dari <span>7</span>'; // total awal 7 = sama dengan HTML awal (subjek belum dipilih)
    let title=document.getElementById('f-progress-title');if(title)title.textContent='Subjek Foto';
    fSyncStepNums();

    // FIX BUG "TAMPILAN KOSONG" SETELAH RESET: baris ini sebelumnya pakai
    // f0.scrollIntoView(...) — method itu SUDAH DIOVERRIDE GLOBAL jadi no-op
    // (cuma kasih kilau .just-revealed, TIDAK BENERAN SCROLL — lihat <script>
    // paling atas). Kalau user reset saat posisi scroll masih di bawah
    // (lihat hasil JSON generate), layar tidak pernah ikut digeser balik ke
    // atas walau semua card & FS sudah berhasil direset — user cuma
    // ngeliat area output yang baru saja dikosongkan, kelihatan seperti
    // "tampilan kosong" padahal wizard-nya sudah kembali ke Step 1 di atas.
    // Pola yang benar sudah dipakai di switchPage()/fScrollToCard(): scroll
    // MANUAL ke .app-shell (container scroll asli app ini), bukan
    // scrollIntoView(), supaya tidak ikut kena override itu.
    let _appShellReset=document.querySelector('.app-shell');
    if(_appShellReset) _appShellReset.scrollTo({top:0,behavior:'smooth'});
    if(typeof pbResetProgress==='function') pbResetProgress();
  })();
}

// ============================================================
// VAI — UNCHANGED
// ============================================================
// BUG FIX: konstanta ini dipakai di vbGenerate3AI() & _vbCallBulkBatch() tapi
// sebelumnya tidak pernah dideklarasikan di mana pun → setiap generate AI di
// Video Builder langsung error "GEMINI_ENDPOINT is not defined" dan gagal total.
// GANTI model di bawah kalau kamu memang mau pakai versi model lain.
// ── PINDAH KE CLAUDE (permintaan user, Sep 2026) ─────────────────────────
// Sebelumnya provider-nya Groq (sebelum itu Gemini). Sekarang diganti ke
// Claude (Anthropic) — endpoint Messages API resminya, BUKAN format
// request/response Gemini/OpenAI. Supaya semua kode pemanggil di bawah
// (_vbFetchWithClaudeFallback, _vbStreamClaudeJSONWithRetryModel, dst —
// namanya sengaja TIDAK diganti biar tidak perlu ubah puluhan call-site
// lain) tidak perlu diubah satu-satu, kedua fungsi itu yang menerjemahkan:
// request dibungkus ulang jadi format Claude (content blocks {type:'text'}/
// {type:'image',source:{...}}) sebelum dikirim, lalu response Claude
// dibungkus BALIK jadi bentuk {candidates:[{content:{parts:[{text}]}}]}
// persis seperti balikan Gemini — jadi seluruh kode yang membaca
// data.candidates[0].content.parts[0].text tetap jalan apa adanya.
// CATATAN CORS: Claude API baru bisa dipanggil langsung dari browser kalau
// header 'anthropic-dangerous-direct-browser-access':'true' disertakan di
// tiap request (lihat _vbStreamClaudeJSONWithRetryModel &
// _vbFetchWithClaudeFallback) — tanpa header ini browser akan diblokir CORS.
// ── PROXY (permintaan user, Sep 2026) ───────────────────────────────────
// App TIDAK LAGI memanggil api.anthropic.com langsung dari browser dan
// TIDAK LAGI minta API Key dari user. Semua request AI sekarang lewat
// Cloudflare Worker proxy milik pemilik app (API key Claude disimpan aman
// di server sebagai secret, tidak pernah terkirim ke browser user).
// GANTI URL ini kalau nanti pindah/redeploy Worker-nya.
const ANTHROPIC_ENDPOINT='https://promptbuilder.vid1hihu.workers.dev';
// (v11.67: konstanta ANTHROPIC_VERSION dihapus — tidak pernah dipakai; aplikasi ini tidak mengirim header anthropic-version.)
// Identitas anonim per-perangkat (bukan data pribadi) — dipakai Worker
// buat menghitung kuota generate per user/device, bukan per-key lagi
// (karena key sekarang shared/milik pemilik app, bukan per-user).
function _pbGetDeviceId(){
  try{
    var k='pb_device_id_v1';
    var id=localStorage.getItem(k);
    if(id)return id;
    id='dev-'+Array.from(crypto.getRandomValues(new Uint8Array(12))).map(function(b){return b.toString(16).padStart(2,'0');}).join('');
    localStorage.setItem(k,id);
    return id;
  }catch(e){return 'dev-unknown';}
}
// FIX KEAMANAN #2 lanjutan (nutup celah kuota Gratis anonim, Sept 2026):
// Worker proxy sekarang verifikasi tier lewat Firestore ID token, bukan
// dari localStorage lagi (lihat komentar besar dekat PB_FIREBASE_CONFIG).
// Fungsi ini ambil ID token user yang sedang login lalu dikirim ke Worker
// tiap generate lewat header X-Firebase-Token — TANPA ini, Worker anggap
// semua orang anonim dan user Standar/Premium ikut kena limit Gratis.
// getIdToken() Firebase SDK otomatis refresh sendiri kalau token sudah
// lama (>1 jam), jadi aman dipanggil tiap request tanpa cache manual di
// sini. Kosong ('') kalau belum login / Firebase belum siap — app tetap
// jalan normal sebagai anonim (kena limit Gratis + pagar IP di Worker).
// FIX (audit auth #2, Sept 2026): kalau user sudah login tapi sesi Firebase belum siap
// (signInWithCredential masih jalan / sesi dipulihkan), TUNGGU dulu (maks 8 dtk). Kalau tetap
// kosong padahal paket berbayar, JANGAN kirim anonim (Worker akan pakai limit Gratis) —
// lempar error jelas (err.pbAuthSession). User Gratis tetap jalan seperti biasa.
function _pbWaitFirebaseUser(ms){
  return new Promise(function(resolve){
    var done=false,unsub=null,t=null;
    function fin(){
      if(done)return; done=true; clearTimeout(t);
      try{unsub&&unsub();}catch(e){}
      var u=null; try{u=firebase.auth().currentUser;}catch(e){}
      resolve(u);
    }
    t=setTimeout(fin,ms);
    try{unsub=firebase.auth().onAuthStateChanged(function(u){if(u)fin();});}catch(e){fin();return;}
    try{if(window.pbCloudReady&&window.pbCloudReady.then)window.pbCloudReady.then(fin,fin);}catch(e){}
  });
}
async function _pbGetFirebaseIdToken(){
  var loggedIn=false,paid=false;
  try{loggedIn=!!localStorage.getItem('pb_auth_user');paid=(typeof pbGetTier==='function'&&pbGetTier()!=='free');}catch(e){}
  try{
    if(typeof firebase!=='undefined'&&firebase.auth){
      var u=firebase.auth().currentUser;
      if(!u&&loggedIn)u=await _pbWaitFirebaseUser(8000);
      if(u){var t=(await u.getIdToken())||'';if(t)return t;}
    }
  }catch(e){}
  if(loggedIn&&paid&&navigator.onLine!==false){
    var err=new Error('Sesi akunmu belum tersambung ke server, jadi paket berbayarmu belum bisa dipakai. Tutup lalu buka lagi aplikasinya; kalau masih sama, keluar lalu login ulang.');
    err.pbAuthSession=true;
    throw err;
  }
  return '';
}
// FIX (permintaan user, Sept 2026): Sonnet-5 SEBAGAI CADANGAN DIMATIKAN
// TOTAL — sebelumnya kalau Haiku gagal total setelah retry habis, app
// otomatis pindah ke Sonnet-5. Sekarang HANYA Haiku 4.5 yang dipakai,
// tidak ada lagi model lain. CLAUDE_MODEL_FALLBACK SENGAJA disamakan
// nilainya dengan CLAUDE_MODEL_PRIMARY (bukan dihapus) — kalau nanti mau
// aktifkan model fallback yang BEDA lagi, cukup ganti nilai konstanta
// ini kembali.
// FIX BUG KRITIS (audit lanjutan, Sept 2026 — "stale-guard reset
// isGenerating padahal proses masih hidup"): comment versi lama di sini
// menganggap "percobaan ke-2 pakai fallback otomatis jadi retry biasa"
// itu netral/aman. TERNYATA TIDAK — _vbStreamClaudeJSONWithRetry dan
// _vbFetchWithClaudeFallback tetap menjalankan SIKLUS PERCOBAAN PENUH
// ke-2 dari nol (jaring pengaman ~3 menit lagi di
// _vbStreamClaudeJSONWithRetryModel) walau modelnya persis sama —
// membuat total tunggu sebelum benar-benar gagal bisa sampai ~6+ menit,
// MELEWATI _VB_GEN_STALE_MS (5 menit) di bawah. Kalau itu kejadian saat
// primary kena error transient (429/503/529) berturut-turut,
// _vbGuardGenerating() auto-reset VAI._isGenerating=false padahal
// fetch/stream aslinya masih jalan di background — user bisa pencet
// Generate lagi, 2 request jalan bersamaan, biaya token dobel, kartu
// bisa ketiban. Sekarang KEDUA fungsi itu sudah diubah supaya hanya
// menjalankan 1 siklus percobaan (PRIMARY) selama CLAUDE_MODEL_FALLBACK
// masih sama dengan CLAUDE_MODEL_PRIMARY — total tunggu balik ke ~3
// menit sesuai janji komentar MAX_TOTAL_WAIT_MS, aman di bawah
// _VB_GEN_STALE_MS. Kalau nanti CLAUDE_MODEL_FALLBACK diisi model BEDA
// lagi, siklus percobaan ke-2 perlu ditambahkan balik secara sadar di
// kedua fungsi itu (bukan otomatis aktif lagi).
// GANTI MODEL (permintaan user, 30 Sep 2026): Haiku 4.5 -> Claude Sonnet 5.5
// ('claude-sonnet-5-5', tarif $2/juta input & $10/juta output — tier Sonnet
// termurah saat ini, sama dengan Sonnet 5). System prompt & pesan user TIDAK
// diubah sama sekali, cuma ID model + parameter thinking di bawah.
// PENTING: Worker proxy (ANTHROPIC_ENDPOINT) harus mengizinkan ID model ini
// kalau di sisi Worker ada whitelist model.
// PILIHAN MODEL (permintaan user, 30 Sep 2026): tombol Sonnet / Haiku di tab
// Panduan (#pb-model-picker). Pilihan disimpan di localStorage dan dibaca
// SETIAP panggilan AI lewat _pbModelId() — system prompt & pesan user
// SAMA PERSIS untuk kedua model, yang beda cuma ID model. 'thinking' dan
// tarif harga ikut model karena aturan API-nya memang berbeda: Sonnet 5.5
// wajib {type:'between_tools'} (menolak 'disabled'), sedangkan Haiku 4.5
// tidak menyalakan thinking kalau field itu tidak dikirim (undefined otomatis
// dibuang JSON.stringify). Tarif Haiku 4.5 = $1/juta input & $5/juta output.
// PENTING: Worker proxy harus mengizinkan kedua ID model ini kalau ada whitelist.
var PB_AI_MODELS={
  sonnet:{id:'claude-sonnet-5-5',label:'Sonnet',thinking:{type:'between_tools'},priceIn:2.0,priceOut:10.0},
  haiku:{id:'claude-haiku-4-5-20251001',label:'Haiku',thinking:undefined,priceIn:1.0,priceOut:5.0},
  // GROQ (permintaan user, Sep-Okt 2026): Qwen 3.8 27B — model vision Groq yang
  // aktif (Llama 4 Scout sudah dipensiunkan Groq). Bisa baca foto (maks 3 foto
  // per request), tarif $0.80/juta input & $4.00/juta output, maks output 16384.
  // Lewat Worker proxy yang sama (format OpenAI-compatible, lihat _pbBuildGroqBody).
  // Mode 'instruct' (reasoning_effort:none) dipakai supaya cepat & hemat token.
  groq:{id:'qwen/qwen3.8-27b',label:'Groq',provider:'groq',thinking:undefined,priceIn:0.80,priceOut:4.00},
  // GROQ GPT-OSS (permintaan user, 1 Okt 2026): OpenAI gpt-oss-120b lewat Groq.
  // Jalur, system prompt, & format pesan SAMA PERSIS dengan 'groq' di atas
  // (provider:'groq' -> _pbBuildGroqBody). Beda kecil yang wajib:
  //  - reasoning:'low'  -> model ini TIDAK menerima reasoning_effort 'none'
  //    (hanya low/medium/high). 'low' = paling cepat & hemat token.
  //  - maxImages:0      -> model ini teks saja (tidak bisa baca foto), jadi foto
  //    tidak dikirim & label [Image N] tidak dipasang.
  // Tarif Groq: $0.15/juta input & $0.60/juta output.
  // PENTING: id ini juga harus ada di GROQ_MODELS pada Worker proxy.
  gptoss:{id:'openai/gpt-oss-120b',label:'GPT-OSS',provider:'groq',thinking:undefined,priceIn:0.15,priceOut:0.60,reasoning:'low',maxImages:0},
  // GEMINI (permintaan user, 1 Okt 2026): model Gemini TERMURAH yang masih bisa
  // baca foto = Gemini 2.5 Flash-Lite, lewat endpoint OpenAI-compatible Google
  // (Worker yang sama, key di secret GEMINI_API_KEY). Tarif paid tier
  // $0.10/juta input & $0.40/juta output. reasoning_effort:'none' mematikan
  // thinking (hanya valid untuk seri 2.5). CATATAN: model 2.5 adalah generasi
  // lama; kalau nanti diberi 404/pensiun, ganti ke 'gemini-3.5-flash-lite'
  // (sekitar $0.15/$1.25) DAN ubah reasoning gemini di PB_OAI_PROVIDERS jadi
  // 'minimal' (seri 3.x tidak menerima 'none').
  // FIX 404 (1 Okt 2026, v9.8): gemini-2.5-flash-lite 'no longer available to new users' (Google, 18 Sep 2026).
  // Diganti gemini-3.5-flash-lite (GA, tarif $0.30 input / $2.50 output per juta token, cache baca $0.03).
  // Alternatif lebih murah kalau suatu saat perlu: 'gemini-3.1-flash-lite' ($0.25/$1.50).
  gemini:{id:'gemini-3.5-flash-lite',label:'Gemini',provider:'gemini',thinking:undefined,priceIn:0.30,priceOut:2.50}
};
// Groq & Gemini sama-sama format OpenAI-compatible: satu set fungsi dipakai
// untuk keduanya, yang beda cuma batas output, batas foto, & reasoning_effort.
var PB_OAI_PROVIDERS={
  groq:{maxOut:16384,maxImages:3,reasoning:'none'},
  gemini:{maxOut:16384,maxImages:16,reasoning:''} // '' = reasoning_effort TIDAK dikirim (seri 3.x menolak 'none'; default 3.5 Flash-Lite sudah thinking 'minimal')
};
function _pbProviderOf(id){
  for(var k in PB_AI_MODELS){if(PB_AI_MODELS[k].id===id)return PB_AI_MODELS[k].provider||'';}
  return '';
}
// Nama provider untuk pesan error ke user (Claude/Groq/Gemini) sesuai model terpilih.
function _pbProviderLabel(){
  var pv=_pbProviderOf(_pbModelId());
  return pv==='groq'?'Groq':(pv==='gemini'?'Gemini':'Claude');
}
// Nama lama dipertahankan: true untuk SEMUA model non-Claude (Groq & Gemini).
function _pbIsGroqModel(id){return !!PB_OAI_PROVIDERS[_pbProviderOf(id)];}
// Batas foto per request untuk model yang sedang dipilih (Groq 3, Gemini 16).
// Claude tidak dibatasi di sini (API-nya menerima sampai 100 gambar).
function _pbMaxImages(){
  var mid=_pbModelId();
  if(!PB_OAI_PROVIDERS[_pbProviderOf(mid)])return 100;
  return _pbOaiCfg(mid).maxImages;
}
// Konfigurasi OpenAI-compatible untuk 1 model: default dari provider-nya,
// bisa ditimpa per-model lewat field reasoning / maxImages di PB_AI_MODELS.
function _pbOaiCfg(model){
  var pv=PB_OAI_PROVIDERS[_pbProviderOf(model)]||PB_OAI_PROVIDERS.groq;
  var cfg={maxOut:pv.maxOut,maxImages:pv.maxImages,reasoning:pv.reasoning};
  for(var k in PB_AI_MODELS){
    var m=PB_AI_MODELS[k];
    if(m.id===model){
      if(m.reasoning!==undefined)cfg.reasoning=m.reasoning;
      if(m.maxImages!==undefined)cfg.maxImages=m.maxImages;
      break;
    }
  }
  return cfg;
}
// Ubah 'parts' gaya Gemini (text / inline_data) jadi messages format OpenAI/Groq.
function _pbGroqMessages(parts,systemText,maxImages){
  var msgs=[];
  if(systemText)msgs.push({role:'system',content:systemText});
  var content=[],hasImg=false;
  var imgCount=0;
  (parts||[]).forEach(function(p){
    var d=p&&(p.inline_data||p.inlineData);
    if(d){
      if(imgCount>=(maxImages==null?3:maxImages))return;
      imgCount++;
      hasImg=true;
      var mime=d.mime_type||d.mimeType||'image/jpeg';
      content.push({type:'image_url',image_url:{url:'data:'+mime+';base64,'+d.data}});
    }else{
      content.push({type:'text',text:(p&&p.text)||''});
    }
  });
  if(!hasImg)content=content.map(function(c){return c.text;}).join('\n\n');
  msgs.push({role:'user',content:content});
  return msgs;
}
function _pbBuildGroqBody(model,parts,systemText,maxTokens,stream,chatMsgs){
  var pv=_pbOaiCfg(model);
  var b={model:model,max_completion_tokens:Math.min(pv.maxOut,maxTokens||2048),messages:_pbGroqMessages(parts,systemText,pv.maxImages)};
  if(pv.reasoning)b.reasoning_effort=pv.reasoning;
  // Mode percakapan (semua model OpenAI-compatible: Gemini, Groq, GPT-OSS): daftar pesan bergantian user/assistant menggantikan satu pesan user.
  if(chatMsgs&&chatMsgs.length){
    var _cm=[];if(systemText)_cm.push({role:'system',content:systemText});
    chatMsgs.forEach(function(m){_cm.push({role:m.role,content:m.text});});
    b.messages=_cm;
  }
  if(stream){b.stream=true;b.stream_options={include_usage:true};}
  return b;
}
// FIX BIAYA (audit, 1 Okt 2026): ubah blok 'usage' format OpenAI-compatible
// (Groq & Gemini) jadi bentuk usageInfo yang dipakai pencatat biaya. Untuk
// GEMINI, token yang kena cache implisit (prompt_tokens_details.cached_tokens)
// dipisah dari input biasa dan dicatat sebagai cache_read — tarif resmi Google
// untuk Gemini 2.5 Flash-Lite: input $0.10/juta, cache $0.01/juta (= 10%, sama
// dengan pengali cache_read di _vbCalcUsd). Kalau API tidak mengirim rincian
// ini, nilainya 0 dan hitungan sama persis seperti sebelumnya. Groq sengaja
// TIDAK dipisah (diskon cache Groq beda dari 10%, jadi dihitung input biasa).
function _vbOaiUsageToInfo(gu,model){
  gu=gu||{};
  var pt=gu.prompt_tokens||0,ct=gu.completion_tokens||0,cached=0;
  if(_pbProviderOf(model)==='gemini'){
    var d=gu.prompt_tokens_details;
    cached=Math.min(pt,Math.max(0,(d&&d.cached_tokens)||0));
  }
  return{input_tokens:pt-cached,output_tokens:ct,cache_creation_input_tokens:0,cache_read_input_tokens:cached};
}
// FIX BIAYA TERPUTUS (audit, 1 Okt 2026): Claude melaporkan token input di
// event awal stream, jadi percobaan yang putus tetap punya angka input. Groq/
// Gemini baru melaporkan usage di chunk TERAKHIR — kalau stream putus, semua
// angka masih 0 dan percobaan itu dulu TIDAK tercatat sama sekali. Untuk
// provider OpenAI-compatible, percobaan terputus dianggap tertagih kalau
// sudah ada teks yang mengalir; outputnya dicatat sebagai PERKIRAAN terpisah
// (outEstTok, dari panjang teks). Input percobaan ini tidak diketahui, jadi
// tidak ikut dihitung (batas-bawah).
function _vbHasInterruptedUsage(u,isOai,textChars){
  if(u.input_tokens>0||u.cache_creation_input_tokens>0||u.cache_read_input_tokens>0)return true;
  return !!isOai&&(u.output_tokens>0||textChars>0);
}
