function _vbRefOpts(){var _u=(typeof pbUserRefOpts==='function')?pbUserRefOpts():null;if(_u)return _u;return _vbIsDua()?VB_REFERENCE_OPTIONS_DUA:(_vb16()?VB_REFERENCE_OPTIONS_16:VB_REFERENCE_OPTIONS);}
